INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9159543936', 'Gancho adesivo Command transparente médio 2 unid HB004270540 3M', 'Gancho adesivo Command transparente médio 2 unid HB004270540 - 3M Decora e organiza sua casa de forma prática. Não estraga as paredes, servindo para pendurar sem furar. Não deixa resíduos. Gancho para pendurar fácil de aplicar e ser removido. O gancho adesivo 3M Command transparente é a solução ideal para organizar e decorar sua casa, dando destaque apenas ao que estiver pendurado. Faça você mesmo em minutos de forma prática, sem sujeira, sem furos e remova quando quiser, sem estragar sua parede. Detalhes: - Firme e seguro: Cada gancho suporta até 900g - Sem ferramentas: Fácil de aplicar e remover - Remoção limpa: Não deixa adesivo nem danifica a parede - Gancho: Polietileno e aço inoxidável - Tira adesiva: Fita de polietileno com adesivo à base de borracha.', 33.12, 33.12, NULL, 'Home & Living > Home Organizers > Hooks', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mg2lvcbb9821c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F9159543936', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
