INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997999918', 'Caderno espiral capa dura universitário 1x1 80 folhas Snoopy Tilibra', 'O Caderno Espiral Capa Dura Universitário 1 Matéria Snoopy 80 Folhas possui capa dura com a parte interna decorada, bolsa de papel decorada para guardar trabalhos e anotações e folha com adesivos funcionais. Ideal para o dia a dia na escola ou na faculdade. Além disso, as folhas desse caderno são compatíveis com o aplicativo Tilibra Connect, disponível gratuitamente na Apple Store e Google Play. Com esse app você consegue digitalizar suas anotações com mais agilidade, elaborar perguntas e respostas com o conteúdo escaneado, criar e revisar fichas. Mais praticidade para estudar em qualquer hora e lugar! Detalhes: - Capa: dura - Bolsa de papel decorada - Capa acabamento: com material metalizado - Folha de adesivos - Folhas: pautadas - Índice: decorado - Número de matérias: 1 matéria - Parte interna da capa decorada - Formato: 200mm x 275mm - Gramatura: 56 g/m² - Número de folhas: 80 folhas.', 52.68, 52.68, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-824h9-mdyzk7mf4b2f3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23997999918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
