INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294430304', 'Kit Mochila Rodinhas Lancheira Estojo Mickey Mouse Escolar Infantil', 'Ficha técnica mochila: Marca: Disney Medidas: AxLxP: 44x32x18 cm Capacidade: 25 Litros Peso: 1,990 kg Material: Poliéster e EVA Ficha técnica lancheira: Medidas: AxLxP: 25x22x11 cm Capacidade: 6 Litros Peso: 270g Material: Poliéster e pvc Ficha técnica estojo: Medidas: AxLxP: 24x16x8 cm Capacidade: 3 Litros Peso: 270g Material: Poliéster e pvc Características: Kit de mochila infantil personalizada do personagem Mickey Mouse. A mochila é confeccionada em material têxtil com estampa completa, reforçando o visual divertido e característico do personagem. Na parte frontal, o segundo bolso apresenta o Mickey em alto relevo, com os braços abertos, criando um efeito tridimensional que torna o design ainda mais encantador. Mochila: Modelo com rodinhas e puxador ajustável em duas alturas. Bolsos laterais em tela, perfeitos para itens de fácil acesso. Alças acolchoadas, oferecendo conforto ao usar nas costas. Compartimento traseiro para guardar as alças, mantendo-as protegidas e limpas enquanto utiliza a função com rodinhas. Estojo: Compartimento amplo com múltiplas divisórias para lápis, canetas e outros materiais Zíper principal com costuras reforçadas para maior durabilidade. Estampa frente em bordado com nome da personagem. Puxador emborrachado com acabamento especial. Lancheira: Função térmica, preservando a temperatura dos alimentos. Compartimento principal amplo com zíper e acabamento resistente. Elástico interno para fixar garrafa. Detalhes no logo em bordados. Acompanha uma alça transversal, facilitando o transporte. Cuidados de conservação: Evite carregar excesso de peso. Não embale objetos com cantos vivos ou cortantes, para não danificar o produto. Para limpeza, utilize apenas pano úmido ou esponja macia com sabão neutro. Não exponha ao sol para secar. Não utilize produtos químicos na higienização. Conserve em local seco e arejado.*Garantia de 3 meses para defeitos de fabricação.*', 599.9, 549.9, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfikmv05wwzpf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608971773%2F23294430304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
