INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44127791054', 'MANETE DE FREIO TRASEIRO COMETA HONDA LEAD 110 POLIDO', 'Manete de Freio Traseiro Cometa para Honda Lead 110 – Acabamento Polido O manete de freio traseiro Cometa é a reposição ideal para sua Honda Lead 110, garantindo segurança, conforto e funcionamento suave do sistema de frenagem. Produzido com material resistente e acabamento polido, mantém o padrão visual e a qualidade da peça original. Compatibilidade Honda Lead 110 – todos os anos (Freio traseiro a tambor) Características do Produto Marca: Cometa Modelo: Manete de Freio Traseiro Acabamento: Polido Construção resistente e durável Encaixe perfeito no padrão original Ação macia e precisa Instalação rápida, sem adaptações Benefícios Maior segurança e controle na frenagem traseira Excelente ergonomia para o piloto Durabilidade superior Substituição direta da peça original desgastada ou quebrada Atenção Verifique o modelo exato da sua moto antes da compra Recomendamos instalação por profissional especializado', 19.9, 19.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-8261g-mj61mtrrwxdza8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F44127791054', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
