INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097678681', 'Mini Cama Infantil com Proteção Lateral Branco Branco', 'A Mini Cama é o produto ideal para os bebês maiores, sendo muito utilizada na transição entre berço e cama de solteiro. A maioria das crianças acaba fazendo essa transição em algum momento entre 1 ano e meio e 3 anos e meio. Apresenta design moderno, com cantos arredondados e barra de proteção lateral, muito seguro, é um produto desenvolvido em 100% MDF e com acabamento em Pintura UV e Lacca PU, qualidade que também aparece no design, auxiliando na decoração do quarto de seus filhos. Tamanho de Colchão: 1500 x 700 mm Estilo: Moderno Garantia: 03 Meses Altura (cm): 72 Acabamento: Pintura UV Largura (cm): 75 Possui Baú: Não Possui Pés: Sim Tipo de Cama: Mini Cama Possui Portas: Não Altura dos Pés: 11 Possui Gavetas: Não Possui Rodízio: Não Suporta Até (kg): 40 Profundidade (cm): 156 Tipo de Estrado: Fixo Acompanha Dossel: Não Escala de Brilho: Brilhante Material dos Pés: Madeira Maciça Acompanha Colchão: Não Origem do Produto: Nacional Acabamento dos Pés: Verniz Ambiente Principal: Quarto Infantil Material da Gaveta: MDF Material Principal: MDF Necessita Montagem: Sim Possui Prateleiras: Não Material do Estrado: Madeira Sapatas Niveladoras: Sim Acabamento da Gaveta: Pintura Acompanha Cama Auxiliar: Não Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Escala de Brilho da Gaveta: Brilhante Altura do Estrado até o Chão: 26 Peso Suportado por cada Cama: 50 Tipo de Madeira Maciça dos Pés: Pinus Acompanha Suporte para Mosquiteiro: Não Permite a Utilização de Cama Auxiliar: Não Marca: VJ Móveis Cor Flex: Não Tonalidade: Branco Cor: Branco Cor do Produto: Branco Itens Inclusos: 1 Cama e Manual de montagem. Tipo do Produto: Mini Cama Cor Predominante: Branco Linha ou Coleção: Infantil Tamanho do Colchão Indicado (L x C): 150cm x 70cm', 347.73, 347.73, NULL, 'Mom & Baby > Nursery > Storage & Organization', 'https://cf.shopee.com.br/file/sg-11134201-822y0-mo5rx2b4nytgd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21097678681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
