INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399263228', 'Aperitivo Aperol', 'Aperol é um aperitivo italiano icônico, com sabor levemente amargo e notas cítricas marcantes. Criado em 1919, possui baixo teor alcoólico (11%) e é perfeito para momentos de convívio com amigos e colegas. Aperol Spritz é um drink clássico feito com espumante, Aperol e água com gás, guarnecido com uma fatia de laranja. Harmonize com azeitonas, bruschetta, dadinho de tapioca ou snack de arroz.', 67.79, 67.79, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-8258g-mqnem0k221vk31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554783%2F22399263228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
