INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999194097', 'Cabo de Áudio Ugreen 3.5mm para 2Rca Macho/Macho 3 Metros', 'Cabo de Áudio Ugreen 3.5mm para 2Rca Macho/Macho 3 Metros Cabo de Áudio Auxiliar Conector Banhado a Ouro Núcleo Cobre Estanhado Plug and Play Transmissão Superior Conecte seus dispositivos de áudio com facilidade: O cabo de áudio Ugreen 3.5mm para 2Rca Macho/Macho é perfeito para conectar smartphones, tablets, laptops, MP3 players e outros dispositivos com saída de áudio de 3.5mm a sistemas de som, amplificadores, receivers e muito mais; Qualidade de som superior: Desfrute de uma experiência de áudio imersiva com a qualidade de som excepcional proporcionada por este cabo. Com conectores banhados a ouro e blindagem de alta densidade, você terá uma transmissão de sinal estável e livre de interferências; Design durável e flexível: O cabo possui uma construção durável, com revestimento em PVC resistente, garantindo uma longa vida útil. Além disso, sua flexibilidade permite uma fácil instalação e organização dos cabos; Comprimento ideal: Com 3 metros de comprimento, este cabo oferece flexibilidade para posicionar seus dispositivos de áudio onde você preferir, sem comprometer a qualidade do som; Versatilidade e compatibilidade: Compatível com uma ampla gama de dispositivos, este cabo é perfeito para uso doméstico, em estúdios de gravação, festas, eventos e muito mais. Desfrute de uma conexão de áudio estável e de alta qualidade em qualquer lugar. Garantia 90 dias', 83.96, 83.96, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134201-7rcdd-lr4y7dlxzg3v3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F21999194097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
