INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9255104050', 'Isca Artificial De Pesca Sougayilang 12g 10cm', 'Isca Artificial Sapo Sapinho Pecunaré Imediata Isca Artificial Sapo Sapo Sapo Antichoque Sapinho Pecunaré Envio Imediato Promoção Relâmpago Frete Grátis Descrição do produto Isca Artificial Sapo Sapo Antichoque Sapinho Pavão Baixo Artificial Iscas de iscas de silicone feitas com silicone para grandes peixes predadores de pesca. Entre eles: reboques, baixo pavão, pazu, baixo preto, entre outros. Muito utilizada em amortecimento, rios ou lagoas, além de ser ideal para pesca em locais com bastante troncos, galvanizados e vegetação fechados como mato, Guapé, regia, etc. Garanta o sucesso de sua viagem de pesca levando a isca certa. Pesqueiros preferidos e mais usados pelos grandes pescadores, podendo ser usado em algumas pescarias com os peixes acima. É muito especial, tendo um anti-risco com dois ganchos afiados que garantem fiscais precisos. Especificações do: Recomendado para os seguintes peixes: Black Bass, Pacú, Traíra e Trairão, Baixo Pavão e outros peixes que investem sobre iscas de movimento. Comprimento: 10 cm. Largura: 4cm Peso Aproximado: 12 gramas. Isca de superfície Gancho: Duplo Cores Disponíveis: amarelo, verde, azul, amarelo claro, verde escuro Itens INCLUSOS: Unidade DE ISCA ARTIFICIAL SAPO FROG ANTI ENROSCO 4cm * 01 ISCA ARTIFICIAL UNIDADE SAPO FROG ANTI ENROSCO 4cm', 30.0, 30.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/aeba112a88c7f67da87f15ca64f501d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F234488046%2F9255104050', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597182825', 'Kit Tela Difusor Ar Gol Parati Saveiro G3 99 2000 2001 2002 2003 2004 2005 Preto', '*Leia com ATENÇÃO todas as informações do anúncio e compre somente na certeza. Verifique o modelo, ano, ou qualquer dúvida nos contate no campo de perguntas antes de finalizar a compra. O custo por eventual devolução será por conta do comprador! * Produto 1° Linha (NÃO É ORIGINAL) -DESCRIÇÃO: Kit Telas Difusor de Ar -COMPATÍVEL: Volkswagen - Gol / Parati (G3) 1999 a 2005 Volkswagen - Saveiro (G3) 2000 a 2005 -ITENS INCLUSOS: 04 - Telas Difusores de Ar -ESPECIFICAÇÕES TÉCNICAS: Cor Preta Sem Lado Específico Aplicação: Central / Lateral Material Resistente Ótimo Acabamento -OBSERVAÇÕES: * Anúncio referente ao KIT (4 Peças)! * Recomendamos que os produtos sejam instalados por profissionais especializados. * Não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. * Imagem meramente ilustrativa. * Garantia de 90 dias. * Não vendemos para PESSOA JURÍDICA fora do ESTADO DE SÃO PAULO. *Caro Cliente! Caso precise devolver o produto, independente do motivo, se atente ao prazo oferecido pela Plataforma. Não encerre por conta própria seu pedido de devolução até que o mesmo se resolva! Após o vencimento/encerramento, não poderá mais usufruir dessa cortesia e os custos serão por sua conta.', 49.65, 45.68, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpfe9tx1mqfp70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F22597182825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
