INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48601194361', 'Kit Praia Infantil Balde + Toalha Surf | Toalha Surf Estampa HD Modelo Importado | Balde Fundo do Mar KENDY | QUEEN SHOP', 'Mergulhe na diversão com o Kit Praia Fundo do Mar + Toalha Surf, uma combinação perfeita para acompanhar as brincadeiras das crianças nos dias de sol! O Balde Fundo do Mar é cheio de cores e detalhes encantadores, com estampas sortidas inspiradas no oceano (golfinho, cavalo-marinho, tartaruga, caranguejo e muito mais). Produzido em polipropileno resistente, vem com tampa peneira, pá, rastelo e forminhas divertidas para brincar na areia. A Toalha Surf completa o kit com muito estilo e conforto! Com estampa de pranchas de surfe na praia, é leve, macia e tem o tamanho ideal para as crianças (120 cm x 60 cm). 🌊 Itens inclusos: • 1 Balde Fundo do Mar (18 cm de altura x 21 cm de largura) • 1 Toalha Infantil Surf (120 cm x 60 cm) • 1 Tampa peneira • 1 Pá e 1 rastelo • 2 forminhas temáticas de areia ✨ Destaques: • Tema oceano e surfe – alegre e colorido • Balde fabricado em polipropileno resistente • Toalha macia e de secagem rápida • Ideal para praia, piscina e parque • Envio sortido de modelos da linha Fundo do Mar • Indicado para crianças a partir de 2 anos', 79.9, 43.9, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgxwj55pxr0g9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1007842724%2F48601194361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
