INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20317781439', 'Carcaça Inferior Do Painel Cromo Forte Titan 150 2004 2005 2006 2007 2008 Preto', 'A Cromo Forte possui uma linha completa de plásticos para que você possa realizar a substituição por um excelente custo x benefício. A linha de painéis contém todos os componentes compatíveis com as principais motos do mercado brasileiro, fabricados nos moldes do original. Especificações: - Fabricada em termoplástico de alta resistência; - Resistente aos raios Ultra Violeta; - Design personalizado e mais resistente; - Mesmo molde do modelo original, não necessita adaptações; - Cor: Preto; - ABS 100% virgem. Aplicação: - Titan 150 2004; - Titan 150 2005; - Titan 150 2006; - Titan 150 2007; - Titan 150 2008. - Antes de finalizar a compra, certifique -se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação. - Para realizar a instalação, leve sua moto à uma oficina especializada. A loja não se responsabiliza por danos causados pela má instalação do produto.', 84.11, 44.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Panel and Speedometer', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lfgzwvomp397d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F20317781439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22839410958', 'ANGELINA PURPURINA 7 - A DESTEMIDA', 'Neste volume, Angelina faz novas amizades, investiga uma casa abandonada e desmascara até fantasmas. Aventuras não faltam na vida dessa garotinha! Durante minhas férias, conheci uma menina chamada Marinete. Nós duas aprontamos uma pegadinha com meus irmãos, como eles sempre fazem comigo. De volta à escola, entrei na competição de quem pega mais tampinhas para a reciclagem e EU, Angelina Purpurina, quero ganhar, claro. Nesta nova aventura, Angelina vai nos contar suas emoções nas férias em um camping, a disputa acirrada na escolha numa campanha de arrecadação de tampinhas de garrafa e uma história de Halloween! As aventuras de Angelina Purpurina sempre trazem histórias engraçadas, de uma protagonista simpática que sabe como lidar com os irmãos mais velhos. Angelina Purpurina é uma série com livros que podem ser lidos fora da ordem e vai encantar os jovens leitores.', 31.4, 31.4, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7qvd2-lfq4cju48jwl54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F22839410958', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
