INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198786262', 'Kit 2 Chupetas Coleção Fundo do Mar 6m+ Neutra - MAM', 'Kit 2 Chupetas Coleção Fundo do Mar 6m+ Neutra - MAM As Chupetas Mam Original Coleção Fundo do Mar vem em um estojo que permite esteriliza-las no micro-ondas em 3 minutos. Também pode ser usado para armazenamento e transporte. "O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO." Principais Características: - Tamanho do Bico Nº2 (6+ Meses) - Embalagem dupla: contém 2 (duas) unidades - Livre de BPA e BPS - Acompanha caixa para esterelização e transporte - Leia atentamente as instruções de uso no rótulo do produto. Especificações Técnicas: - Conteúdo da Embalagem: 2 Chupetas Mam + Caixinha para Esterilização - Material/Composição: Polipropileno e Silicone - Garantia: 30 Dias (Contra Defeito de Fabricação Pelo Fabricante) - Produto Certificado pelo INMETRO CE-PUR/IQB 000265 NBR 10334 – OCP 006 - Referência do Fabricante: CH23322 - EAN: 9001616691157 - Marca: MAM Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante', 62.0, 62.0, NULL, 'Mom & Baby > Feeding Essentials > Pacifiers', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-md2bdsn5ctogd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F624228750%2F23198786262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
