INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42305081363', 'Livro Dreamy and cozy', 'Inspirado no fenômeno dos livros de colorir para relaxamento do TikTok, o livro DREAMY & COZY é perfeito para quem ama transformar momentos simples em uma verdadeira experiência calmante._x000D_ Impressas em papel de alta gramatura, para garantir a melhor qualidade de pintura, as 48 páginas com 23 ilustrações exclusivas e uma página para você testar cores e texturas retratam momentos cotidianos e aconchegantes, permitindo que você explore sua criatividade ao máximo, seja colorindo com lápis de cor ou marcadores._x000D_ Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Ciranda Cultural _x000D_ Ilustrador: Luana Chinaglia_x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 24.00 x A 24.00 x E 0.50_x000D_ ISBN: 9786526121979_x000D_ Coleção: Comfy & cozy books_x000D_ Linha Editorial: Ciranda Cultural - Lab_x000D_ Faixa Etária: Sem definição_x000D_ Assuntos (tags): Colorir, Relaxar, Diversão, Pintar, Pintura_x000D_ BISAC: Jogos e Atividades / Jogos e Atividades / Livros de Colorir_x000D_ Linha de Produto: Comfy and cozy books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 24.9, 24.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7rath-mb5ffqyxctjkf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42305081363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10413507339', 'Livro - Tangram para crianças - Capa comum - Ciranda Cultural', 'Com o Tangram você pode montar inúmeras imagens usando as sete peças geométricas. Ele estimula a criatividade e melhor a noção espacial, entre outras coisas. Vamos brincar? Editora: Ciranda Cultural Edição: 1, 2021 Autor: Ciranda Cultural Idioma: Português Páginas: 96 Dimensões: L 13.20 x A 20.00 x E 0.50 ISBN: 9786555007633', 14.9, 14.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/dad455804a3e082a5f88eb3b89442069', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10413507339', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094221986', 'Livro de Colorir | Só para Princesas', 'Todos os sonhos secretos das princesas estão ilustrados nesse livro, prontos para serem coloridos e, quem sabe, colocados em prática! 34 Páginas 22 x 28 cm', 14.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-mc2unxa24y7tde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23094221986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5092624310', 'Livro - Contos de Fadas de Andersen Vol. II - Capa comum - Principis', 'Os Contos de Fadas de Andersen reúnem as melhores histórias do escritor Hans Christian Andersen, frutos de sua imaginação e de narrativas que ouvia quando criança. Este segundo volume contém uma conversa profunda entre um boneco de neve e um cão sobre a passagem do inverno, além de um dos contos mais famosos do autor: O Patinho Feio. Andersen incluía em suas histórias muitos elementos da natureza, objetos falantes e confrontos entre personagens que ansiavam por direitos iguais, espelhando-se em sua infância pobre. Sua linguagem acessível conquistou o público infantil, tornando-o um dos pioneiros na literatura infantojuvenil. Editora: Principis Edição: 1, 2020 Autor: Hans Christian Andersen Idioma: Português Páginas: 176 Dimensões: L 16.00 x A 23.00 x E 1.00 ISBN: 9786555520200', 24.9, 24.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/bfcd9a69747a925f0c89480a8f51145d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F5092624310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42850359486', 'Livro Principis Papa Francisco: O legado e seu exemplo de vida', '“CONSTRUAMOS PONTES, NÃO MUROS.” Neste livro inspirador, acompanhamos a jornada extraordinária de Jorge Mario Bergoglio – de menino argentino no bairro de Flores ao pontífice que conquistou o mundo com sua simplicidade, compaixão e coragem moral. Papa Francisco, O legado e seu exemplo de vida, apresenta um retrato profundo e acessível de um líder que desafiou tradições, defendeu os pobres e rompeu barreiras com palavras e gestos poderosos. Com linguagem clara e cuidadosa organização, o livro aborda a infância, a vocação, a atuação como arcebispo, a eleição ao papado e os principais temas de seu pontificado, como misericórdia, inclusão, justiça social e paz._x000D_ Este livro é um tributo à luz que Francisco lançou sobre um mundo dividido e um chamado a manter esse legado vivo._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2025_x000D_ Autor: Walter Bukunovicky_x000D_ Idioma: Português_x000D_ Páginas: 96_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.60_x000D_ ISBN: 9786550972615_x000D_ Coleção: Não se aplica_x000D_ Linha Editorial: Principis - Literatura cristã_x000D_ Faixa Etária: + 14 anos_x000D_ Assuntos (tags): Religiosidade, Fé., Deus, Reflexão, Cura, Mensagem, Cristianismo , Igreja, Catolicismo_x000D_ BISAC: Religião / Religião / Biografia Bíblica_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca_x000D_ Material: Papel', 24.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rffv-m9km6wspcgpd9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42850359486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
