INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40160673702', 'VidFlora em Pó Fibras e Vitaminas Flora Intestinal c/ Ameixa e Mamão', 'O VidFlora é um suplemento alimentar em pó desenvolvido para auxiliar no funcionamento intestinal. Sua fórmula combina fibras alimentares com vitaminas essenciais e minerais, proporcionando benefícios para a saúde digestiva e o bem-estar geral. Benefícios: ✅ Auxilia no funcionamento do intestino ✅ Contribui para o metabolismo energético ✅ Rico em fibras alimentares ✅ Contém vitaminas B2, B6, B9 e C ✅ Fonte de magnésio ✅ Sabor agradável de mamão e ameixa ℹ️ Ficha Técnica: ✅ Produto: Suplemento alimentar de fibras e vitaminas em pó ✅ Sabor: Mamão e Ameixa ✅ Peso líquido: 200g ✅ Ingredientes: Polidextrose, ameixa desidratada em pó, mamão desidratado em pó, frutooligossacarídeos, riboflavina (vitamina B2), nicotinamida (vitamina B3), cloridrato de piridoxina (vitamina B6), ácido fólico (vitamina B9), dimalato de magnésio, ácido ascórbico (vitamina C), edulcorante sucralose, acidulante ácido cítrico (INS 330), antiumectante fosfato tricálcico (INS 341iii), aromatizante e corante ✅ Sugestão de uso: Adicione 2 dosadores a 200ml de água filtrada e mexa até completa dissolução ✅ Não contém glúten ✅ Marca: Videira 7 ✅ Embalagem: Pote plástico com tampa rosqueável', 111.76, 69.88, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdwp-mcqmfuxvkptj71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F40160673702', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
