INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497734036', 'Buzina Original Gauss Volkswagen Polo Sedan 2003 A 2015', '## Buzina Gauss Volkswagen Polo e Polo Sedan: A Voz do Seu Carro! Dirija com segurança e confiança com a Buzina Gauss, a escolha inteligente para o seu Volkswagen! A Importância da Buzina: A buzina é um item de segurança essencial em qualquer veículo. Ela permite alertar outros motoristas, pedestres e ciclistas sobre a sua presença, prevenindo acidentes e garantindo a sua segurança e a de todos ao seu redor. Por Que Escolher a Buzina Gauss? A Gauss é uma marca reconhecida pela qualidade e durabilidade de seus produtos automotivos. Com a Buzina Gauss, você tem a garantia de um som potente e claro, que não te deixará na mão quando você mais precisar. Confie na tradição e excelência da Gauss para equipar o seu carro! Compatibilidade: Esta buzina é compatível com os seguintes veículos Volkswagen: Polo (2006 a 2012) com motores EA111, EA111 VHT e EA113 Polo Sedan (2004 a 2012) com motores EA111, EA111 VHT e EA113 Especificações Técnicas: Voltagem: 12V Forma: Caracol Códigos Originais Equivalentes: VOLKSWAGEN ORIGINAL 6Q0.951.182B e 6Q0.951.107 Não perca tempo! Adquira agora a sua Buzina Gauss e garanta a segurança e a tranquilidade que você e seu Volkswagen merecem!', 134.99, 134.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5krmijz1p519c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F20497734036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993169725', 'Par Buzina Caracol Jeep Compass 2017-2020 Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Par Buzina Caracol Jeep Compass 2017-2020 Gauss A principal função da buzina é alertar no trânsito sobre alguma condição adversa sendo utilizada para evitar uma colisão no trânsito, em ocasiões de desatenção de outro motorista.Trata-se de um item obrigatório no veículo, que pode render multa para o motorista, caso não esteja funcionando regularmente. A Buzina Gauss Jeep Compass Caracol combina eficiência com durabilidade, para que você possa ter o melhor desempenho do seu veículo As buzinas da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Compatibilidade com os seguintes veículos: Jeep Compass 2017 Jeep Compass 2018 Jeep Compass 2019 Jeep Compass 2020 Especificações Técnicas do Veículo: Veículo: Compass Montadora: Jeep Ano: 2017 a 2020 Especificação Técnica - Buzina: Cod Produto: Gb1054 Modelo: Par Buzina Caracol Voltagem: 12 Nivel Sonoro: 110 Quantidade De Conectores: 2 Quantidade Buzinas: 2 Quandidade De Cornetas: 2 Origem: Brasil 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 71.45, 71.45, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5khilsifdxs26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23993169725', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
