INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694276744', '40~200 PORTA FORMINHA BAILARINA FESTCOLOR (CHOCO)', 'Deixe a mesa da sua festa ainda mais encantadora com o Porta Forminha Bailarina Da Festcolor! O kit contém 40 unidades com estampas delicadas de sapatilhas, cisnes e elementos do universo do ballet, em tons suaves de rosa e branco. Ideal para acomodar docinhos como brigadeiros e beijinhos com charme e elegância. Produzido em papel de alta qualidade, é perfeito para compor a decoração de festas infantis com o tema Bailarina. Um toque gracioso que vai encantar todos os convidados!', 19.85, 19.85, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mct5v5o2vda926', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F22694276744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
