INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13614404446', 'Creme Dental Oral-B Gengiva Detox Deep Clean 102g', 'O novo creme dental Oral-B Gengiva Detox limpa profundamente entre dentes e gengiva. Milhões de bactérias se acumulam em um espaço onde cremes regulares não atuam, nos espaços entre dentes e gengiva. Oral-B traz para você a nova Gengiva Detox, com microespuma que limpa profundamente, prevenindo problemas de gengiva. * Elimina bactérias em lugares de difícil alcance. * Gengiva mais saudável, clinicamente comprovado. * Sensação refrescante depois da escovação. * Para uso diário. * Bactérias que formam placa. *Imagens Meramente Ilsutrativas.', 34.89, 33.19, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbnd-lq6155oyj86y32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F13614404446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
