INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497795030', 'Bancada Ilha Cozinha Painel Gourmet Imperatriz Ripado 200cm Freijó - Nesher', 'Transforme sua cozinha em um espaço gourmet de luxo com a Bancada Ilha Imperatriz Ripado Nesher! Com impressionantes 200cm de largura e feita 100% em MDF, esta ilha é a peça central que faltava. Seu design ripado frontal, uma tendência de alto padrão, confere uma elegância incomparável e textura sofisticada ao ambiente. Ideal para cozinhas de conceito aberto, ela funciona perfeitamente como balcão, passa-pratos ou mesa rápida, delimitando o espaço com charme. BANCADA ILHA COZINHA IMPERATRIZ 200CM - FREIJÓ - NESHER Marca: Nesher Linha/Modelo: Cozinha Imperatriz Dimensões(Cm): Bancada Ilha Cozinha Imperatriz 200cm Comprimento(Profundidade): 35,5 cm Largura: 200 cm Altura: 100 cm Tipo de Estrutura do Móvel: - 100% MDF Estilo do Móvel: - Estilo Ripado Tipo de Pintura: - Pintura em UV (Ultravioleta) Tipo de Acabamento da Pintura: - Semi Brilho Tipo Acabamento: - Acabamento Ripado Alto Padrão Tipo de Formato Tampo: - Tampo Retangular Tipo das Quinas do Tampo: - Canto Reto Montagem do Produto: - Necessita Montagem, Acompanha Manual de Instalação e Montagem, Necessita de Ferramentas, Desmontável Sistema de Montagem: - Inclui kit de instalação Garantia: - 3 meses Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 838.91, 796.97, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-821ei-mh27wd0lfgui0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F21497795030', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293281826', 'Kit 3 und Carmed Fini Amora Claro 10g', 'Kit 3 und Carmed Fini Minhocas Amora Claro 10g O Carmed Fini Amoras com Cor é um hidratante labial que combina a proteção dos lábios com um toque de cor. Formulado com ingredientes que proporcionam hidratação e conforto, este produto oferece uma aplicação suave e uma textura agradável. A cor "Amoras" adiciona um leve tom aos lábios, realçando o visual com um efeito natural e sofisticado.', 80.22, 80.22, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rdvu-m0c10ukkuj511f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23293281826', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
