INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899549426', 'Ventilador Aquecedor Elétrico de Ambiente 1500w 2 em 1 - 220v', 'Aquecedor Elétrico 2 em 1 Nagano 1500W - Nagano Aqueça com Conforto e Segurança! Desfrute de conforto e segurança em seu ambiente com o Aquecedor Elétrico 2 em 1 Nagano. Este aquecedor versátil possui um design moderno e compacto, permitindo o uso conveniente no chão, mesas ou prateleiras, proporcionando calor onde você mais precisa em sua casa ou escritório. Características Principais: Controle de Intensidade de Calor: Ajuste o nível de calor conforme sua necessidade para um ambiente perfeitamente aquecido. Sistema de Segurança Avançado: Desliga automaticamente em caso de superaquecimento, garantindo sua tranquilidade durante o uso. Fácil de Usar: Com controle de temperatura e lâmpada indicadora que mostra quando o aparelho está ligado, oferece praticidade no dia a dia. Versatilidade em Uso: Pode ser utilizado como aquecedor ou ventilador, oferecendo conforto em todas as estações. Seja nos dias mais frios ou durante qualquer estação, o Aquecedor Elétrico 2 em 1 Nagano proporciona um ambiente aconchegante e agradável. Aproveite a praticidade e eficiência deste produto para criar um espaço confortável em sua casa ou escritório. Não deixe o frio atrapalhar seu bem-estar, aqueça-se com o melhor da tecnologia em aquecimento elétrico! Potência: 1500W Frequência: 60Hz Modelo: NAEM Ideal para ambientes de até 15m²', 100.8, 100.8, NULL, 'Home Appliances > Large Household Appliances > Heaters', 'https://cf.shopee.com.br/file/sg-11134201-7repd-m1wtbmn76nqf4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F19899549426', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599544404', 'Máquina de Costura Overlock - 150w - 60hz - TMCO150R - 110V', 'Máquina de Costura Overlock Industrial 150w 60hz - TMCO150 é um tipo de máquina de costura semi-industrial que efetua simultaneamente a costura e o chuleio (acabamento das bordas para que não se desfiem). São utilizados pelo menos dois grupos de fios, sendo um alimentado pela agulha e outro pelo looper. VELOCIDADE MÁXIMA DE COSTURA:3000RPM COMPRIMENTO MÁXIMO DO PONTO: 1.5-3.2MM COMPRIMENTO DO PONTO OVERLOQUE: 2.5-4.5MM ESPESSURA MÁXIMA DE COSTURA: 4MM DIMENSÃO DO PRODUTO (INCLUINDO O RESERVATÓRIO): 25X21X27CM POTÊNCIA DO MOTOR: 150W ITENS INCLUSO: Motor; Pedal; Porta Fios; Fita Métrica; Jogo de Agulhas Reserva; Pinça; Carvão Reserva; Correia Reserva; Reservatório de Óleo; Chave de boca; Chave de fenda; Cabo de alimentação; Manual de instruções.', 632.8, 632.8, NULL, 'Home Appliances > Small Household Appliances > Sewing Machines & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7reo9-m1wvv6vjgymce1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F21599544404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
