INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192773295', 'Suporte de Carenagem Dianteiro Xre 190 2016 á 2024 Peças Acessórios De Moto Para Reposição Pro Tork', 'O Suporte de Carenagem Dianteiro, também conhecido como Aranha, é uma peça de reposição fabricada pela Pro Tork em plástico injetado de alta resistência, oferecendo a melhor relação custo/benefício do mercado. Especificações: - Peça de reposição; - Fabricado em plástico; - Marca: Pro Tork. Aplicações: - XRE 190 2016 À 2024. Instalação: - Recomendamos que a instalação seja feita em uma oficina especializada; - A loja não se responsabiliza pela má instalação do produto. Observação: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 84.11, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rbl5-lptcyryska1q10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23192773295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18848235449', 'Suporte Bau Bauleto Moto Yamaha Fazer 150 Factor 125 Protork', 'Bagageiros são acessórios extremamente úteis em motocicletas: para uma maior segurança e para transportar bagagens, equipamentos e outras cargas. Por isso a Pro Tork desenvolveu uma linha completa deste item pensando em você! O Bagageiro Pro Tork modelo Sansão FACTOR / FAZER oferece mais agilidade na instalação, pois com seu sistema de fixação que é acoplado na alça original dispensa a remoção da rabeta! A utilização de bagageiros Pro Tork em motocicletas tem muitas vantagens, incluindo: - Conforto e praticidade: carregar a bagagem na moto ao invés de carregar nas costas é muito mais confortável, especialmente em viagens longas! - Segurança: uma carga bem presa no bagageiro é muito mais segura do que carregar solta na moto ou nas costas! - Capacidade de transporte: o bagageiro aumenta a capacidade de carga da moto, permitindo que o piloto transporte mais itens. Especificações: - Fabricado em Aço Maciço; - Cor: Cromado e Preto; - Pintura Eletrotástica; - Marca: Pro Tork; - Carga máxima suportada: 6kg. Aplicações: - Fazer 150 2017; - Fazer 150 2018; - Fazer 150 2019; - Fazer 150 2020; - Fazer 150 2021; - Fazer 150 2022. - Factor 125 2017; - Factor 125 2018; - Factor 125 2019; - Factor 125 2020; - Factor 125 2021; - Factor 125 2022. Observações: É importante lembrar que a carga no bagageiro deve ser bem distribuída e bem fixada para garantir a segurança na pilotagem da moto. É recomendado também verificar a capacidade de carga do bagageiro e a capacidade de carga total da motocicleta antes de carregar o bagageiro para evitar sobrecarga. A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada ou por defeitos causados por mal uso. - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 199.89, 119.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lfi7umvn3y63cf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F18848235449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23414632715', 'Escapamento Escape Moto V3 Pro Tork Compatível Com Fan 125 KS 2014 a 2015', 'O Escapamento V3 traz em seu DNA o que há de melhor no mundo, desde o design norte-americano até a tecnologia japonesa junto com a criatividade tupiniquim. Produzido em alumínio escovado que confere leveza e resistência ao calor extremo produzido pelos motores em altíssimas rotações. Especificações: - Modelo: V3; - Material: Alumínio; - Marca: Pro Tork; - Segue todas as normas reguladoras de fabricação; Aplicação: - Fan 125 KS 2014; - Fan 125 KS 2015. - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação. - Para realizar a instalação, leve sua moto à uma oficina especializada. Nós não nos responsabilizamos por danos causados pela má instalação do produto.', 384.1, 319.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/sg-11134201-22120-vgpr0hkgqllveb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23414632715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22219984946', 'Protetor Motor Mata Cachorro Barra Dupla Compatível Com Moto Dafra Speed 150 2008 A 2015 Pro Tork', 'O Protetor de Motor Barra Dupla Pro Tork é fabricado em matéria-prima de alta qualidade, garantindo mais resistência e segurança. Protege a moto em caso de quedas, e também o condutor em pequenas colisões frontais. Especificações: - Modelo: Barra Dupla; - Marca: Pro Tork; - Fabricado em aço; - Perfeito ajuste na moto, não necessita de adaptação. Aplicação: - Dafra Speed 150 2008; - Dafra Speed 150 2009; - Dafra Speed 150 2010; - Dafra Speed 150 2011; - Dafra Speed 150 2012; - Dafra Speed 150 2013; - Dafra Speed 150 2014; - Dafra Speed 150 2015. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada. A Sportbay não se responsabiliza pela má instalação do produto. Sportbay - Seu Esporte, Nossa Paixão.', 105.16, 105.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134201-820mf-mqxr7cksxudjb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22219984946', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
