INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093045374', 'Carrinho de Mão Reforçado G-20 Desmontável 60L - ESFERA', 'Loja do Mecânico - O que você precisa, nós temos! O Carrinho de Mão Reforçado G-20 Desmontável 60L – ESFERA é a escolha perfeita para quem busca praticidade, resistência e versatilidade nas tarefas do dia a dia. Indicado para trabalhos de construção civil, jardinagem e transporte de materiais em geral, ele oferece excelente desempenho tanto em ambientes domésticos quanto profissionais. Fabricado com estrutura em aço e caçamba em chapa de aço com pintura eletrostática, o modelo garante alta durabilidade. O design ergonômico e a facilidade de montagem tornam o produto funcional e confortável no uso contínuo. Além disso, o modelo G-20 PCI é desmontável, facilitando o transporte e o armazenamento, e acompanha manual de instruções para montagem rápida e descomplicada. Características - Pneu com câmara de ar - Roda fabricada totalmente em aço Especificações Técnicas: - Marca: ESFERA - Capacidade de carga: 120 kg - Capacidade da caçamba: 60 L - Pintura eletrostática na cor cinza - Peso: 12,288 kg - EAN: 7898228291033 Conteúdo da Embalagem - 01 Carrinho de Mão Importante - Garantia de 6 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 396.99, 396.99, NULL, 'Home & Living > Tools & Home Improvement > Trollies', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-lvj7fhkzoeqb07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F23093045374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
