INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298010648', 'Hidratante Corporal Glycare Loção 120ml', 'Glycare Loção promove uma hidratação intensiva da pele, melhorando seu aspecto, textura e uniformidade, sendo indicado para peles secas, extrassecas e áreas ásperas/rugosas como cotovelo, joelho e calcanhar. Contém ácido glicólico em Matriz Nano 3D que aumenta a renovação celular e ativos hidratantes, como a Manteiga de Karité, que promovem um alto grau de hidratação e reparação com ação prolongada, conferindo maciez e suavidade à pele. Glycare Loção aumenta a hidratação e a renovação celular, uniformiza o tom da pele, mantém a barreira cutânea, melhora o espessamento da pele, aumenta a maciez e melhora da textura da pele além de possuir boa espalhabilidade.', 119.9, 119.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-824gf-mf21co7ricr334', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F23298010648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
