INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209669813', 'Piraquê Água e Gergelim Biscoito Salgado', 'O Biscoito Piraquê Água e Gergelim é perfeito para quem busca crocância e sabor em um só produto. Ideal para um lanche rápido, acompanhado de um café ou chá, ou para surpreender em um café da tarde. * Crocante e saboroso * Com gergelim nutritivo * Ideal para lanches a qualquer hora do dia Contém Glúten. Alérgicos: Contém derivados de cevada, de soja e de trigo. Pode conter aveia, centeio e leite. Conservar em ambiente fresco, seco, sem exposição ao sol e livre de odores.', 5.99, 5.99, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-825ai-mqnelbwwix370d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58209669813', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097702106', 'Ração Quatree Supreme Senior +7 Cães Raças Pequenas 10kg', 'Descrição: Ração Quatree Supreme Cães Sênior +7 Raças Pequenas Frango e Salmão - 10,1kg - Indicado para cães; - Para cães de raças pequenas; - Saúde da pele e pelagem; - Melhora a flora intestinal; - Alta digestibilidade. Ração Quatree Supreme Sênior +7 Raças Pequenas é um alimento Super Premium formulado com conservantes 100% naturais e livre de transgênicos, garantindo fácil digestão e absorção dos nutrientes. A combinação de proteínas selecionadas e ingredientes naturais e funcionais garante mais saúde e longevidade para o seu cão. Quatree Supreme Sênior +7 contém DHA importante para a saúde do cérebro e melhora do estado cognitivo. Além disso, possui níveis reduzidos de sódio e fósforo para a manutenção dos rins e do coração, auxilia no equilíbrio da flora intestinal com as fibras naturais prebióticas (MOS e FOS), polpa de beterraba e extrato de yucca que asseguram ótima digestibilidade. Sem contar que é ótimo para a pele e pelagem pois contém Ômega 3 e 6, além da maçã e chá verde com potente ação antioxidante que reforça as defesas naturais do organismo. Modo de usar Fornecer diariamente o alimento Quatree Supreme Sênior +7 Raças Pequenas dividido em duas porções. As quantidades indicadas na tabela são uma referência, podendo variar conforme a raça, idade e atividade do cão ou de acordo com a orientação do médico veterinário. Quantidade Diária Peso Atividade Física Moderada Atividade Física Alta 2kg 45g 52g 4kg 75g 90g 6kg 100g 120g 8kg 125g 150g 10kg 148g 180g 12kg 170g 205g 14kg 190g 225g Um copo de 250ml equivale a aproximadamente 118g de Quatree Supreme Sênior +7 Raças Pequenas.', 294.38, 161.05, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134207-81zug-ml4wr2b192x0da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009890604%2F23097702106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
