INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48459665841', 'Creme de Pentear Cachos Kids 500ml bn.Cachos', 'O Creme de Pentear bn.CACHOS Kids foi desenvolvido especialmente para cuidar dos cabelos das crianças com suavidade e eficiência. Ideal para cachos 2ABC, 3ABC e 4ABC, ele proporciona definição duradoura, brilho intenso e controle do frizz, deixando os fios macios, soltinhos e fáceis de pentear. Sua fórmula é enriquecida com D-Pantenol, Aloe Vera e Óleo de Algodão, ativos que hidratam profundamente, nutrem os fios e ajudam a manter a saúde capilar desde cedo, sem pesar. ✨ Benefícios: Define os cachos com leveza Reduz o frizz e facilita o desembaraço Proporciona brilho e maciez Hidratação suave para uso diário Indicado para todas as curvaturas infantis Ativos principais: D-Pantenol: hidratação e fortalecimento Aloe Vera: nutrição e suavidade Óleo de Algodão: maciez e proteção Modo de uso: Aplique uma quantidade adequada nos cabelos úmidos ou secos, espalhando uniformemente. Desembarace com pente de dentes largos ou com os dedos. Finalize como desejar. Perfeito para a rotina capilar dos pequenos, garantindo cachos definidos, hidratados e cheios de vida todos os dias! ????', 42.99, 39.39, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-820lg-mnltg1h9el8l51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F48459665841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
