INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20546531038', 'Torneira eletrônica de parede BC/CR - Essence Lorenzetti', 'Produto: Torneira eletrônica de parede 5500 watts Branco cromado - Essence Marca: Lorenzetti Voltagem: 220V Descrição: A Torneira eletrônica de parede Essence BC/CR da Lorenzetti possui comando eletrônico, permitindo a escolha gradual da temperatura mesmo durante o uso, e conta com bica móvel e arejador articulável com jato aerado que facilita as atividades domésticas. Com design moderno, a Torneira Eletrônica Essence valoriza e dá um toque de sofisticação à cozinha ou área gourmet. Características: • Comando eletrônico que permite a escolha gradual da temperatura; • Bica móvel com arejador articulável; • Resistência tipo refil, fácil substituição; • Registro com 1/4 de volta, segurança e facilidade no manuseio; • Resistência Loren Ultra que garante alta performance e longa duração; • Compatível com DR. Especificações: Cor: Branco Cromado Potência: 4600 watts (127) 5500 watts (220) Fios (mm²): 6 (127V) 4 (220V) Disjuntor (A): 40 (127V) 32 (220V) Pressão de Funcionamento: 20 a 400kPa (2 a 40 m.c.a.) Grau de Proteção: IP 24 Sistema de Aterramento: Sim Comando Eletrônico de Temperaturas: Sim Compatível com "DR": Sim. Peso: 0.75 Kg', 356.8, 319.9, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/sg-11134201-82595-mqvh4u27eo0276', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F20546531038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
