INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492097401', 'Brastoy Blocos Magnéticos de Montar Brinquedo Infantil Brinquedo 65/130 Peças', 'Produto Certificado pelo INMETRO para garantir a segurança que os pequenos merecem. Monte diferentes formas e crie os objetos com os acessórios que acompanham o kit. Esse conjunto de blocos de brinquedos com ímãs transparentes abrange muitas formas, pode ser combinado em muitos padrões e desenvolve a imaginação, a criatividade, as habilidades motoras, as habilidades sociais e a mente das crianças. Alta transparência: Diferentes cores aleatórias de blocos magnéticos com alta transparência. A luz atravessa os blocos e projeta uma linda sombra colorida no chão. Os blocos magnéticos são perfeitos para uso em família, no jardim de infância, em creches, na pré-escola, em escolas de ensino fundamental etc. Presentes perfeitos para brinquedos de aprendizado: Os brinquedos de peças magnéticas são um presente de aniversário perfeito, presente de Natal ou qualquer outra ocasião para meninos e meninas com mais de 3 anos de idade. As crianças vão se divertir com essas peças magnéticas de construção 3D sozinhas ou com seus colegas. Deixe que os blocos magnéticos tragam alegria e diversão para seus filhos e que eles explorem a beleza dos blocos magnéticos.', 299.0, 141.01, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgbn2km8h1xcf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F497594085%2F22492097401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
