INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8199770632', 'DIARIO DE UM BANANA 17 - VERGARA E RIBA', 'Greg Heffley está descobrindo que conquistar fama e glória não é nada fácil. Como assistente da banda Fräwda Xeia, liderada por seu irmão Rodrick, Greg aprende que noites intermináveis, cachês inexistentes e brigas entre integrantes do grupo fazem parte do estilo de vida de um roqueiro. Será que ele conseguirá ajudar a Fräwda Xeia a se tornar uma lenda do rock and roll? Ou passar muito tempo com o irmão e sua banda vai ser, na real, uma Fräwda Megaxeia?', 67.4, 67.4, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra2c-m4rvbdnedy57c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F8199770632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28340263378', 'Aparador Buffet Gold Marmorizado 4 Portas Pés Madeira Maciça', 'Transforme sua decoração com o Buffet Gold Marmorizado 4 Portas! Com design moderno, tampo com pintura marmorizada e pés de madeira maciça, une elegância e funcionalidade. Ideal para organizar objetos com estilo, conta com 1 prateleira interna e amplo espaço. Perfeito para sua sala de jantar ou cantinho do café. Modelo: Buffet Gold Marmorizado 4 Portas; Dimensões: 160 cm (L) x 81 cm (A) x 37,2 cm (P); Material da estrutura: MDP de 12 mm e 15 mm com pés de madeira maciça; Marmorizado feito em pintura. Quantidade de portas: 04 (dobradiças metálicas); Quantidade de gavetas: Não se aplica; Com puxador: Não se aplica; Quantidade prateleiras: 01, interna ao lado direito; Peso suportado: até 29 kg distribuídos; Requer montagem: Sim (kit montagem incluso); Embalagem do envio: Papelão e plástico. Tonalidade das Cores: Mel: Fosco; Off White: Brilho; Preto: Fosco; Efeito Marmore Branco: Brilho; Efeito Marmore Preto: Brilho. Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 393.99, 366.42, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-mdokfmblgbx17d', 'https://shope.ee