INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53254041627', 'Arame De Solda Mig Para Uso Sem Gás 0,8mm 1kg', 'Arame de Solda 1kg 0.8mm Uso sem Gás Descrição do Produto: O Arame de Solda 0.8mm da Start é ideal para soldagem sem gás, oferecendo praticidade e eficiência em diversos projetos de soldagem. Fabricado com material de alta qualidade, este arame proporciona uma soldagem consistente e durável, sendo adequado para profissionais e amadores que buscam um excelente acabamento em suas soldagens. Ficha Técnica: - Peso: 1kg - Diâmetro: 0.8mm - Marca: Start - Uso: Sem Gás Vantagens: - Praticidade: Dispensa o uso de gás, facilitando o processo de soldagem. - Alta Qualidade: Material resistente, garantindo soldagens duradouras. - Versatilidade: Adequado para diversas aplicações de soldagem. - Consistência: Proporciona soldagens uniformes e de alta qualidade. Usos Recomendados: - Reparos domésticos e industriais. - Projetos de soldagem automotiva. - Manutenção e fabricação de estruturas metálicas. - Soldagem em locais onde o uso de gás não é viável. EAN: 7908822401209 SKU: 24033', 79.9, 79.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mizz2u7q2j9i71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1499568354%2F53254041627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
