INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597668369', 'Kit Adoçante Zero-Cal Com 50% De Desconto Na Segunda Unidade', 'Kit Adoçante Zero-Cal (Promoção): Zero Caloria, Praticidade e Economia O Kit Adoçante Zero-Cal com 50% de Desconto na Segunda Unidade é ideal para quem busca doçura intensa sem adicionar calorias, com excelente custo-benefício. Contém Ciclamato e Sacarina (em algumas versões) ou Stevia /Sucralose. O adoçante é seguro para diabéticos e dietas de emagrecimento. O formato líquido (ou envelopes) facilita a dosagem. O kit promocional garante o uso prolongado e economia familiar. Uso diário prático. Livre de glúten (em algumas versões). Zero Caloria e Promoção Econômica: Zero Caloria: Ideal para dietas de restrição calórica e diabéticos.50% Desconto na 2ª Unidade: Excelente custo-benefício e economia. Uso Versátil: Pode ser usado em bebidas quentes e frias. Uso Diário: Alternativa saudável e saborosa. Use a quantidade de gotas/envelopes necessária para adoçar. Consulte um médico se for diabético. A doçura intensa e a economia que você busca, com a segurança de Zero-Cal.', 44.86, 44.86, NULL, 'Food & Beverages > Cooking Essentials > Sweetener', 'https://cf.shopee.com.br/file/sg-11134201-8261q-ml5jvpq3bfv122', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23597668369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
