INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692914682', 'Scarpin Sapato Boneca Stessy Salto Grosso Bico Quadrado Strass Elegante Confortável Dias Das Mães', 'SCARPIN BONECA COM STRASS Um scarpin boneca é uma peça de calçado que combina elementos clássicos e com um toque moderno. Inspirado nos estilos dos anos 1950 e 1960, este tipo de scarpin apresenta um salto baixo que proporciona conforto durante todo o dia, uma biqueira arredondada e levemente quadrada O design retro adiciona um charme nostálgico e feminino ao calçado, enquanto materiais modernos e técnicas de fabricação garantem conforto e durabilidade. Esses scarpins são versáteis, podendo ser usados para completar looks, retrô ou até mesmo adicionar um toque de elegância a produções contemporâneas. Este scarpin pode ser adaptado para diferentes ocasiões, desde eventos formais até encontros casuais. Tamanho / Medida do pé 34 / 23,5cm 35 / 24,0cm 36 / 24,5cm 37 / 25,0cm 38 / 26,5cm 39 / 27,0cm FORMA NORMAL - Pedir seu tamanho normal de uso! Especificações Técnicas: - SOLADO: Microgel - SALTO: Bloco - ALTURA DO SALTO: 5 CM - PALMILHA: Com espuma macia. - MATERIAL EXTERNO: Napa Sintética e verniz - PESO MÉDIO: 500 gramas Envio: Imediato', 116.9, 59.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ljd0j45qux86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410637624%2F23692914682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
