INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22402206711', 'Aparador com Espelho Multimóveis Cantinho do Café 2 Portas FG3611 Preto', 'O Aparador Cantinho do Café com Espelho 2 Portas Multimóveis é produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade, facilidade na limpeza, além de um acabamento superior. Com 2 portas, possui um excelente espaço interno para organizar louças, bebidas e demais objetos (a prateleira interna suporta 8 Kg e o tampo 9 Kg). Os detalhes com espelhos nas portas deixam o móvel mais requintado, criando um ambiente moderno e charmoso. Os espelhos são de vidro (o que evita que a imagem fique distorcida) e lapidados, ou seja, passam por um processo para que as bordas não fiquem cortantes, o que garante maior segurança. Os amantes de café poderão deixar seu cantinho mais prático e aconchegante para curtir os melhores momentos com os amigos e família, saboreando um delicioso cafezinho. Conteúdo da Embalagem: 1 (um) aparador 1 (um) kit com 2 espelhos Dimensões do produto montado: Altura: 70cm | Largura: 63cm | Profundidade: 32cm *Você pode consultar as medidas internas na imagem técnica do produto. Cores Disponíveis: Branco - Preto Texturizado - Rustic *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 399.99, 299.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-yxt91jfi44iv66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F22402206711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21064305677', 'Cozinha Completa de Canto Veneza GW Multimóveis MP2055 com Armário e Balcão Branca', 'A Cozinha Completa de Canto Veneza Multimóveis MP2055 com Armário e Balcão tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 120 cm), com 1 gaveta e 2 portas. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Para deixar sua cozinha mais bonita e organizada, possui vidro reflecta e compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 2 (um) paneleiros 62cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo com portas de vidro 120cm 1 (um) armário aéreo 70cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 120cm Dimensões do produto montado: Altura: 203cm | Largura: 152 x 304cm | Profundidade: 32cm (aéreos e paneleiro) - 53cm (balcão com tampo e paneleiro) *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Branco - Preto Acetinado Texturizado *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem..', 3299.9, 2219.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvdx-li0f6zuxljuib1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F21064305677', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
