INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297458409', 'Flange Bomba Combustível Ford Fiesta 2006 a 2014 - 180709 - T030031', 'Flange Bomba Combustível Ford Fiesta 2006 a 2014 180709 T030031 MOTOR 1.0/1.6 FLEX (BOSCH) Tubo Engate Rápido Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 42.5, 42.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-lmx70ifelq3d44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21297458409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
