INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202428883', 'Combo Pringles Importada Philly Cheese Crisps Sanduíche De Carne Com Queijo158g 2 unidades', 'O salgadinho Pringles® vem na sua icônica lata, sinônimo de crocância e sabor único. Com batatas perfeitamente empilhadas, é a escolha prática para qualquer momento: no intervalo do dia, para relaxar ou compartilhar com os amigos. Além do clássico Original, é possível experimentar também sabores diferenciados como Ranch Fresh, Creme e Cebola e Ribs Hot. E o melhor: as latas em tamanho mega são perfeitas para dividir e tornar qualquer ocasião ainda mais saborosa. Composição do kit:2 Pringles Importada Philly Cheese Crisps 158g', 63.99, 57.2, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mpsdkrfqtzpq8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638330698%2F58202428883', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599254484', 'Cereal Sucrilhos® Less Sugar Kellogg´S® 170g Menos Açúcar', 'Sucrilhos® 60% menos açúcares da Kellogg''s® é feito a partir do grão de milho e com menos adição de açúcares, é crocante e delicioso a cada colherada. Contém 4 vitaminas do complexo B, vitamina D e ferro, que podem contribuir para um adequado desempenho físico e energético, quando associados a uma alimentação equilibrada e à prática de atividade física. Desfrute do seu sabor de cereal matinal favorito para vencer com garra e energia! Há diversas opções para compor os lanches, como as frutas que podem fornecer fibras, vitaminas e minerais, o leite ou iogurte que fornecem proteínas e cálcio e os cereais como os pães e biscoitos que fornecem carboidratos, dão energia e são alternativas interessantes e deliciosas para fazer parte deste momento, especialmente no Café da Manhã.', 13.99, 12.9, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Cereal, Granola & Oats', 'https://cf.shopee.com.br/file/sg-11134201-7rd5h-lv28pu7vqjp9c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638330698%2F20599254484', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492976294', 'Interruptor Ré Tucson 2005 2006 2007 2008 2009 2010 2011 - 9134 - 44102', 'Interruptor Ré Tucson 2005 2006 2007 2008 2009 2010 2011 (Rosca - M14 x 1,5) (Bipolar) (Ponta Esfera) Utilizado para indicar que na alavanca de câmbio foi selecionada a marcha ré. Quando acionado mecanicamente pela alavanca do câmbio, uma haste no interior da caixa de cambio aciona uma mola metálica presente no interruptor. Esta ação fecha o contato elétrico que por sua vez, envia um sinal elétrico para as luzes de ré acendam.', 117.96, 117.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd4i-lufhmgzcn8pb53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492976294', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392971400', 'Sensor Pressão Oleo Original Peugeot 206 207 208 307 308 C3 - 64292 - 3396', 'Sensor Pressão Oleo Original Peugeot 206 207 208 307 308 C3 MOTOR: 1.4 8V / 1.5 8V / 1.6 16V / 1.8 16V / 2.0 16V TODOS A PARTIR DE 1998 Exceto motor 1.0 16v Indicar anomalia na pressão do óleo lubrificante. O interruptor de pressão do óleo é normalmente localizado no bloco do motor próximo a bomba de óleo, a pressão gerada pela bomba passa pelo interruptor acionando uma mola interna do mesmo fechando assim contato elétrico, enviando um sinal para o painel de instrumentos. Se a pressão for maior do que a especificada o interruptor libera a passagem do óleo de volta para o cárter. Vida Útil: Substituir a cada 40.000 Km (consultar manual do veículo)', 126.19, 126.19, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd48-lufcp9zbjgf6e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23392971400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499029093', 'Cabo Embreagem Fiat Uno 1984 a 1989 - 100316 - 3302', 'Cabo Embreagem Fiat Uno 1984 a 1989 100316 3302 MOTOR 1.3/1.5 (633mm) O processo se inicia quando o pedal de embreagem é pressionado, esse movimento é transmitido pelo cabo, ou varão de embreagem, até o garfo do rolamento, que pressionará a mola membrana, ou alavancas, do platô. Isso fará com que o disco de embreagem seja liberado e, dessa maneira, o torque do motor deixa de ser transmitido ao câmbio. Nesse momento, é criada uma diferença de rotação entre o motor do veículo e seu sistema de transmissão.', 39.97, 39.97, NULL, 'Automobiles > Automobile Spare Parts > Drivetrain, Transmission & Clutches', 'https://cf.shopee.com.br/file/sg-11134201-7reop-m8ggh4oyf5iad4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21499029093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599383318', 'Aparador Buffet Sala Melodia Com Pés Madeira Maciça', 'Este elegante aparador é a adição perfeita para qualquer sala de estar ou sala de jantar. Com um design moderno e sofisticado, este móvel é ideal para armazenar louças, talheres e outros itens essenciais, enquanto adiciona um toque de luxo ao ambiente. Seu acabamento em ouro dá um toque de elegância, tornando-o uma peça de destaque em qualquer espaço. Modelo: Aparador Buffet Melodia; Largura: 160 cm; Altura: 79 cm; Profundidade: 40 cm; Material da estrutura: MDP e MDF 37 mm, 25 mm e 15 mm e pés de madeira maciça; Quantidade de portas: 04; Material da dobradiça: metálicas; Quantidade de gavetas: 02; Material da corrediça: Telescópicas; Medidas internas da gaveta: 9,5 cm x 34,5 cm 31,5 cm; Com puxador: sim, alumínio; Com prateleira: 02; Peso suportado: até 30 kg distribuídos; Tonalidade das Cores: Nature: Fosco; Preto: Fosco; Cinamomo: Fosco; Off White: Brilho; Freijo: Fosco; Verde Pistache: Fosco. Embalagem do envio: Papelão e plástico; Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 899.99, 837.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdyw-lzt8u499unu458', 'htt