INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19198030101', 'CHUMBINHO RIFLE DIABOLO PROMAX 14.5GR 125UN. 5.5MM', 'Produto de uso exclusivo em práticas esportivas (airsoft, carabina de pressão,brinquedos de bolinha) A marca RIFLE é uma empresa que há 30 anos fabrica as melhores munições para Armas de Pressão e Ar comprimido do Brasil. Reconhecida por produzir Chumbos que estão entre os quatro melhores do mundo, usados também por atletas olímpicos e campeões mundiais, aprovados pelas melhores fabricantes de armas do mundo. Símbolo de qualidade e excelência. O Chumbinho modelo PROMAX da linha DIABOLO da Rifle é um lançamento de 2020. Oque mais se destaca nele sem dúvidas é o fator de agrupamento. Apesar de ser considerado um Chumbinho de entrada ele conquistou o respeito dos atiradores. Escolher uma munição de qualidade é essencial para seu desempenho na prática do Tiro Esportivo. Atendendo o alto padrão de qualidade esse Chumbinho da Rifle não possui rebarbas, opção perfeita para sua Arma de Pressão. Especificações Técnicas: - Marca: Rifle - Calibre: 5.5mm (.22) - Modelo: Promax - Linha: Diabolo - Material: Chumbo - Quantidade: 125 unidades - Peso: 0.94 gramas - Gramatura: 14.5 grains - Comprimento: 6,6mm Itens Inclusos: - 01 Lata de Chumbinho Rifle Diabolo Promax 14.5gr 125un. 5.5mm', 41.67, 41.67, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rcck-m6676c1rbfjf73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404617501%2F19198030101', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
