INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23301807200', 'Tênis Olympikus Wellness 2 Masculino - Preto', 'O Produto Nome: Tenis Olympikus Wellness 2 Masculino Gênero: Masculino Indicado para: Dia a Dia Cabedal: Em material sintético e tecidos diferenciados. Forro em poliéster com espuma. Vem com a confortável palmilha Feetpad. Tecnologia: EVAsense Definição da Tecnologia: EVAsense em EVA que gera alto nivel de maciez e maior sensação de conforto. FeetPad: Palmilha em PU com memoria elástica que proporciona maior conforto aos pés. Todo conforto e maciez que uma palmilha pode oferecer. Solado: Design diferenciado com borracha EVA Garantia do Fabricante: Contra defeito de fabricação Marca: Olympikus Origem: Nacional Tenis Olympikus Wellness 2 Masculino O Olympikus Wellnes é o tênis ideal para quem busca conforto, amortecimento e estilo no seu dia a dia. O seu solado possui a tecnologia de amortecimento Eleva+ que explora o limite de expansa?O do EVA, extremamente leve, proporcionando maxima resposta, mantendo conforto e durabilidade. Já o cabedal é feito em tecido poliester dublado com espuma, com textura trazendo um visual clean. Possui ainda logo em relevo, puxador em fita no traseiro para auxiliar no calce e forro de poliéster com espuma. Sua palmilha é anatomica, composta por tecido poliester e EVA, com aplicacao grafica. TECNOLOGIA: ELEVA + - Tecnologia exclusiva Olympikus, que explora o limite de expansão do EVA para alcançar máxima resposta, proporcionando o efeito trampolim, ou seja, absorvendo o impacto da passada e transformando essa energia em impulsão. Este EVA é leve e de baixa densidade, garantindo menor deformação e mantendo o conforto e a durabilidade.', 219.9, 219.9, NULL, 'Sports & Outdoors > Sports Footwear > Hiking Shoes', 'https://cf.shopee.com.br/file/sg-11134201-22100-cqiz6qv3h1ivc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F354869565%2F23301807200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57800668091', 'Ração Golden Seleção Natural para Gatos Filhotes 3kg', 'Ração GoldeN Seleção Natural gatos filhotes frango e arroz 3,0k Pet: Gatos Idade: Filhotes Porte de Raça: todos Condição: todos Sabor: Frango e Arroz Tamanho de grão: adequado para gatos filhotes de todos os portes Quais os beneficios da Ração GoldeN Seleção Natural gatos filhotes frango e arroz? A Ração Seleção Natural gatos filhotes sabor frango e arroz é um alimento premium especial com uma ótima seleção de ingredientes em sua mistura garantindo um ótimo sabor. A Ração Seleção Natural para gatos filhotes vem no sabor frango e arroz garantindo uma ótima experiencia devido a sua alta palatabilidade para gatos, alem de equilibrio necessário para gatos exigentes, possui uma formulação que contem a combinação do complexo de 6 vegetais para uma melhor nutrição. Sua composição auxilia na redução do odor das fezes, possui adição de taurina, DHA e proteinas para um melhor desenvolvimento do filhote, alem do equilibrio de minerais para auxiliar no ph urinário. Selo I''m Green A linha GoldeN Seleção Natural pensando no meio ambiente utiliza derivados de cana de açucar, auxiliando na baixo consumo de produtos foceis para produção de suas embalagens. Por que a Ração GoldeN Seleção Natural gatos filhotes frango e arroz é um alimento Premium Especial? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendendo os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração GoldeN Seleção Natural gatos filhotes frango e arroz foi produzida atendendo todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Quais os tamanhos das embalagens disponiveis de Ração GoldeN Seleção Natural gatos filhotes frango e arroz? Nas lojas da Poli-Pet você encontra a Ração GoldeN Seleção Natural gatos filhotes frango e arroz apresentações: 1,0kg, 3,0kg e 10,1kg. Composição: Ingredientes da Ração GoldeN Seleção Natural gatos filhotes frango e arroz. Farinha de vísceras de frango, proteína isolada de suíno, proteína isolada de soja, quirera de arroz, gordura de frango, gordura suína, óleo de peixe, complexo de vegetais – 5,0% (polpa de beterraba branca, cenoura, beterraba, salsa, brócolis e espinafre), aditivo acidificante, antioxidantes BHA e BHT (0,012%), cloreto de potássio, DL-metionina, extrato de yucca (0,05%), hidrolisado de frango, levedura seca de cervejaria, mananoligossacarídeos (0,2%), bentonita, taurina, vitamina A, vitamina B12, vitamina C, vitamina D3, vitamina E, vitamina K3, ácido fólico, ácido pantotênico, biotina, cloreto de colina, niacina, piridoxina, riboflavina, tiamina, cobre aminoácido quelato, ferro aminoácido quelato, iodeto de potássio, manganês aminoácido quelato, selênio metionina, sulfato de cobre, sulfato de ferro, sulfato de manganês, sulfato de zinco, zinco aminoácido quelato.', 117.44, 96.77, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-821g9-mgjqd15boob3a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F57800668091', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
