INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697679756', 'Vareta Nível Óleo Renault Duster 2012 a 2024 - 1334311 - NV546', 'Vareta Nível Óleo Renault Duster 2012 a 2024 1334311 NV546 1.6 16V A vareta de nível de óleo do motor também chamada de indicador de nível do óleo, é utilizada para indicar a quantidade de óleo existente no cárter do motor, o nível de óleo precisa estar entre a marca mínima e máxima da vareta, se o nível estiver baixo pode causar perca de torque, podendo causar sérios danos ao motor, se o nível estiver acima do máximo podem ocorrer vazamentos nas juntas e nos retentores pois não irão suportar a pressão interna.', 97.87, 97.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rdyl-ly51x1qznwzbe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22697679756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22291239242', 'Parafuso para Madeira 4,8X50 Phillips Caixa com 200 Unidades', 'Seu perfil de rosca permite uma aplicação com menor deslocamento do material, minimizando o risco de trincar ou expandir a madeira, evitando um potencial dano. Este modelo também reduz o torque necessário para o aperto, realizando a montagem mais confortável. Com metal resistente, suporta grande tensão ou peso sem entortar ou danificar sua espiral.', 64.9, 56.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lo1gx779fpos3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22291239242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23596883495', 'Bebedouro Cadence BEB110 Aguô 2 Temperaturas Natural / Gelada Bivolt', 'Bebedouro Cadence BEB110 Aguô 2 Temperaturas Natural / Gelada Sinta o frescor da hidratação instantânea com o Bebedouro Cadence BEB110 Aguo. Este aparelho é a solução perfeita para manter-se hidratado o dia todo, com água gelada ao seu alcance. Seu design elegante e compacto se encaixa perfeitamente em qualquer ambiente, seja em casa ou no escritório. Com uma capacidade de resfriamento eficaz e fácil de usar, o BEB110 Aguo garante que você tenha água gelada sempre pronta para saciar sua sede. Não apenas um bebedouro, mas um companheiro indispensável para manter-se hidratado e revigorado durante todo o dia. Experimente a praticidade e o frescor de um gole gelado de água sempre que quiser com o Bebedouro Cadence BEB110 Aguo, o toque perfeito para sua rotina de bem-estar. Esteja pronto para dar ao seu corpo a hidratação que ele merece, sem a inconveniência de garrafas ou geladeira. O BEB110 Aguo oferece a conveniência que você precisa para manter-se saudável e hidratado com facilidade. Com sua tecnologia de resfriamento eficaz e economia de energia, ele é uma escolha inteligente para quem busca praticidade e qualidade. Não perca mais tempo esperando a água gelar, desfrute do frescor instantâneo sempre que desejar. Adquira o Bebedouro Cadence BEB110 Aguo e transforme a maneira como você se mantém hidratado - um investimento no seu bem-estar que você não pode deixar passar. Tipo: Mesa Tipo de água: Gelada e natural Torneira: 1 Bandeja de água removível: Sim Pé anti-derrapante: Não Voltagem: Bivolt Potência elétrica (W): 65 Consumo (kWh): 0,065 Peso (kg): 2.4 Referência: BEB110 Dimensões (AxLxP): 39x29x31cm Itens Inclusos: 1 Bebedouro Cadence BEB110 Aguo Manual do Produto Informações importantes: Imagens meramente ilustrativas. Objetos que ambientam as fotos não acompanham o produto. As tonalidades das cores dos produtos podem sofrer alterações de acordo com a calibração do seu monitor. Garantia Fabricante: 12 meses', 530.9, 530.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-7rbmu-llmfgrspufh622', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889942432%2F23596883495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298214758', 'Kit Com 100 Escapula Sem Bucha Jomarca', 'A Escápula Sem Bucha da Jomarca é uma peça essencial para o uso em diversos tipos de construção e projetos de marcenaria. Este modelo é altamente eficiente e durável, projetado para oferecer qualidade e resistência. Vem em uma embalagem com 100 unidades, proporcionando um custo-benefício significativo para quem precisa de uma grande quantidade de peças. Benefícios: - Alta Durabilidade: Fabricada com materiais de alta qualidade, garante maior resistência e vida útil. - Praticidade: Embalagem com 100 peças, ideal para quem precisa de um grande volume de escápulas. - Versatilidade: Ideal para montagem de móveis, revestimentos e outras aplicações que exigem fixação e acabamento preciso. Dados Técnicos: Marca: Jomarca Quantidade: 100 peças Material: Aço Tipo: Escápula sem bucha Garantia: 3 meses de garantia', 51.9, 35.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcf4-m6dxzccn8ytw8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23298214758', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
