INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296019356', 'Modelador de Cachos By Juliette Mondial Verde Oliva 70W Bivolt - MC-JU-02', 'O Modelador de Cachos da Linha by Juliette Qu4tro Elementos traz um revestimento especial enriquecido com infusão de Cerâmica, Titânio, Tourmaline e Nano Silver. Esses 4 elementos, juntos, protegem seus fios e garantem uma aparência mais saudável aos cabelos, com brilho intenso, maciez e sem frizz. Saiba mais sobre o Modelador de Cachos MC-JU-02: REVESTIMENTO ESPECIAL COM QU4TRO ELEMENTOS: Cerâmica: Garante uma melhor distribuição do calor e contribui para uma modelagem rápida e mais saudável. Titânio: Tecnologia que age na umidade dos cabelos e reduz o tempo de modelagem, além de eliminar o efeito frizz. Tourmaline: Fonte natural de íons negativos, que eliminam o frizz e garantem mais brilho. Nano Silver: Partículas de prata que ajudam a inibir a ação de bactérias, contribuindo para a proteção dos fios e do couro cabeludo. TUBO COM DIÂMETRO DE 28mm: O modelador é ideal para fazer ondas e cachos mais largos. TUBO MAIS LONGO: Indicado para todos os comprimentos de cabelos, inclusive os mais compridos. PAINEL DIGITAL COM CONTROLE DE TEMPERATURA: São 5 opções de 120°C a 200°C, para uma modelagem perfeita e adequada aos diferentes tipos de cabelo. BIVOLT: Pode ser utilizada em ambas voltagens: 127V e 220V. Liberdade de usar sua prancha em qualquer lugar! CABO GIRATÓRIO DE 2,5 METROS: O cabo-plugue tem 2,5m de comprimento e gira 360°, garantindo mais autonomia de movimento. UM ANO DE GARANTIA MONDIAL: A Mondial é a escolha de milhões de consumidores. Mondial, a escolha inteligente!', 229.9, 229.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-8261v-ml6jey3fuz2n75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F991382718%2F23296019356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
