INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52902036772', 'Condicionador Only Haircare Via Aroma - 250ml', 'Cuidado que transforma, com a pureza que você merece. O Condicionador Only Haircare foi criado para quem busca resultados profissionais sem abrir mão de escolhas conscientes. 100% vegano, cruelty-free e livre de parabenos, silicones e petrolatos, ele entrega hidratação intensa, brilho e maciez usando apenas ingredientes que respeitam você e o meio ambiente. Com uma fórmula natural e segura, ele desembaraça, nutre e revitaliza os fios, deixando o cabelo mais forte, saudável e cheio de vida. Tudo isso aliado ao toque especial da aromaterapia, que transforma seu momento de autocuidado em uma experiência de bem-estar. Vegano | Cruelty-Free | Sem ingredientes agressivos Tratamento eficaz para todos os tipos de cabelo Maciez, força e brilho com leveza Only Haircare – beleza consciente que você sente no toque.', 33.9, 33.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-82253-mhgbuegnw83ne7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545693995%2F52902036772', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
