INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297354103', 'Barraca Iglu Verde 2 Pessoas - Mor', '• A Barraca Iglu da Mor ganhou mais uma cor! Agora além da tradicional Iglu Azul, você poderá optar pela Iglu Eco que é na cor Verde. • As Barracas Iglu são super fáceis de montar devido a sua estrutura em varetas de fibra de vidro interligadas. • São confeccionadas em poliéster e a costura entre o piso e o dormitório é invertida, evitando vazamentos de água para o interior da barraca. O piso é confeccionado em polietileno (ráfia) reforçado. • Além disso, a Iglu Verde possui mosquiteiro na porta e no teto, local para pendurar lanterna dentro da barraca e proteção contra vazamentos! Este produto é próprio para 2 pessoas. Especificações - Observações: Os objetos que ambientam as imagens não acompanham o produto! - Material: Poliéster - Cor predominante: Verde - Capacidade: 2 pessoas - Informações importantes: A barraca não protege 100% da chuva. - Garantia: 90 Dias - Altura: 1,00 Metros - Largura: 1,45 Metros - Comprimento: 2,05 Metros - Peso: 1,51 Kilogramas', 197.12, 191.21, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-7rcez-lrysqiw8cfm895', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F23297354103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
