INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997881163', 'Tapete Para Sala Sarja Junco 3,00x4,00 São Carlos', 'Informações Técnicas: 100% Polipropileno Altura aproximada dos fios: 3mm Contém antiderrapante: Não Proteção: Ultravioleta Imagem meramente ilustrativa Regras de Utilização: - Recomenda-se alterar a posição do tapete no ambiente a cada três meses, para assegurar o uso homogêneo da superfície, - Lavagem à mão, Temperatura máxima: 40ºC; - Não alvejar, Não branquear; - Não secar em tambor; - Secagem por gotejamento na horizontal; - Não passar; - Não limpar a seco; - Limpeza a úmido profissional: processo normal,', 2219.99, 2219.99, NULL, 'Home & Living > Decoration > Carpets & Rugs', 'https://cf.shopee.com.br/file/sg-11134201-7ra25-m4syghb4k7e365', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778935801%2F18997881163', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393887389', 'Roupa Intima Tena Dermacare Pants Com 8 P/m Severa', '**Produto Original** TENA Pants Dermacare é uma roupa íntima descartável e unissex de rápida absorção, que proporciona ao usuário ativo facilidade e praticidade de uso, discrição e segurança. Produto com elásticos em volta da cintura que garante um ajuste perfeito ao corpo. Além da proteção da pele que ajuda na prevenção de irritações, permitindo que a mesma esteja sempre saudável e seca. É indicado para perdas de urina severa. A excepcional segurança deve-se à tecnologia antivazamento que absorve rapidamente mesmo grandes quantidades de urina mantendo-a longe da pele de forma que, mesmo sentado ou deitado durante muito tempo, o usuário permanece seco e confortável, reduzindo significativamente o risco de infecções cutâneas. Um produto hipoalergênico com tecido respirável e macio. Proteção e cuidado para a pele todos os dias.', 47.65, 47.65, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7reok-m82agarf54g00e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F22393887389', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393590040', 'Bolsa de Praia Jacki Design Grande com Fecho em Zíper e Alça de Corda Charmosa - Estilo Náutico', 'A Bolsa de Praia Jacki Design, possui fecho em zíper e amplo espaço interno. Feita de tecido de nylon, a alça em corda dá um charme especial. Esta bolsa é perfeita tanto para o dia a dia quanto para levar à praia ou piscina. Arrase em qualquer lugar! CUIDADOS GERAIS: Limpe a bolsa com um pano úmido. Caso necessário, use sabão neutro ou álcool para higienizar o local. Deixe secar na sombra. ATENÇÃO: Para preservar a vida útil do produto, recomendamos não deixar a bolsa de molho, não levar a máquina de lavar e também não utilizar produtos químicos.'' Medidas: Comprimento: 52cmx Largura: 12cm x Altura: 36cm Material: Nylon POR QUE VOCÊ NÃO PODE DEIXAR DE COMPRAR NOSSO PRODUTO? Adquirindo diretamente conosco, você vai ter a certeza de estar comprando um produto original da marca Jacki Design. E isso é muito importante, para não se frustrar caso adquira um produto falsificado ou de péssima qualidade. Os produtos são de ótima qualidade, e com detalhes pensando em facilitar e organizar o seu dia-a-dia. Embalamos com todo cuidado e enviamos rapidamente pra você! E estaremos sempre a disposição para te atender da melhor forma possível. 3 meses de garantia', 59.9, 55.0, NULL, 'Women Bags > Crossbody & Shoulder Bags', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj8ui4v4kwzq01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F530578890%2F22393590040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699549564', 'Armário Multiuso 4 Portas com Pés NT 4040 Notável Móveis', 'O Armário Multiuso 4 Portas com Pés NT 4040 Notável Móveis, é a solução perfeita para quem busca praticidade e organização em casa, com um amplo nicho aberto e quatro prateleiras internas estrategicamente distribuídas, este móvel oferece generoso espaço para armazenar e organizar seus pertences de maneira eficiente. Seja no quarto ou na área de serviço, o Multiuso NT 4040 é a escolha ideal para maximizar o espaço. Características: 4 Portas 4 Prateleiras internas Estrutura em MDP de 12mm Nicho aberto espaçoso Possui pés Puxadores em abs Dimensões: Altura: 178,6 cm Largura: 93,4 cm Profundidade: 35,1 cm Peso: 41,18 kg Garantia do fornecedor de 3 meses.', 479.9, 419.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md66t8nn03y904', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F21699549564', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22433986740', 'COLORAÇÃO ITALLIAN COLOR LOURO CLARO COBRE INTENSO 8.44 60G', 'O Louro Claro Cobre Intenso 8.44 é uma coloração permanente desenvolvida para proporcionar um tom vibrante e duradouro, ideal para quem busca uma transformação capilar com um toque de intensidade. Indicado para uso profissional, este produto atende tanto a cabelos naturais quanto a aqueles com alto percentual de fios brancos, garantindo uma cobertura uniforme e eficaz. Para aplicar a coloração, é necessário misturar 60g do produto com 90ml de Itallian Oxi, escolhendo entre 20, 30 ou 40 volumes conforme o diagnóstico profissional. Nos cabelos com muitos fios brancos, a pausa recomendada é de 40 minutos, enquanto nos cabelos naturais, o tempo é de 35 minutos. No caso de retoque de raiz, a mistura deve agir por 25 minutos na raiz, com mais 10 minutos para comprimento e pontas. Os benefícios do Louro Claro Cobre Intenso 8.44 incluem uma cobertura completa dos fios brancos e um resultado vibrante, graças à sua fórmula com amônia e componentes como fenilenodiaminas e resorcinol. A coloração é projetada para ser usada em conjunto com o oxidante Itallian Oxi, respeitando a proporção de 1 + 1,5, o que assegura um resultado satisfatório e duradouro. É essencial seguir as precauções de segurança ao utilizar este produto. Realize a prova de toque antes da aplicação para evitar reações alérgicas. O produto contém substâncias que podem causar irritação na pele e não deve ser usado em sobrancelhas, cílios ou em couro cabeludo irritado. O uso de luvas adequadas é obrigatório, e o produto não é recomendado para gestantes e crianças. Em caso de contato com os olhos, lave imediatamente com água em abundância e procure assistência médica se necessário. O Louro Claro Cobre Intenso 8.44 é uma escolha profissional para quem busca uma coloração de cabelo impactante e de longa duração, com a segurança e eficácia que só um produto de qualidade pode oferecer.', 34.5, 30.02, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/br-11134207-820lm-mnn9s64802dc62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969993035%2F22433986740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16081298151', 'Kit De Acabamento Registro Chuveiro 1/2 ou 3/4 Polegadas Metal Pressão Gaveta Padrão Deca Banheiro', 'Kit de Acabamento Modelo C31 – Cruzeta e Canopla Cromada O Kit de Acabamento C31 é a escolha ideal para quem busca durabilidade, funcionalidade e um acabamento elegante em registros hidráulicos. Fabricado com materiais de alta qualidade, este kit conta com cruzeta 100% em metal cromado, garantindo resistência e um visual moderno. A canopla em ABS cromado complementa o conjunto com leveza e bom acabamento. Atenção: Este kit não acompanha o registro, apenas a cruzeta e a canopla. Compatibilidade: Indicado para registros de pressão modelo 1416 e registros de gaveta modelo 1509 Compatível com bitolas de ½” e ¾” Adapta-se a mecanismos padrão Deca e similares Não compatível com registros das marcas Docol e Fabrimar Especificações Técnicas: Cruzeta em metal cromado de alta durabilidade Canopla em ABS cromado Acompanha 2 parafusos de fixação universal Compatível com todas as medidas dos modelos 1416 e 1509 Simples, resistente e com ótimo acabamento. Ideal para quem valoriza qualidade nos mínimos detalhes.', 29.9, 19.89, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6e0roj3dnjbf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450610050%2F16081298151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17331205241', 'Suplemento Vitamínico Para Cachorro Nutrifull Dog 120 ml', '"A LeluPets nasceu de uma paixão e dedicação de aproximadamente 20 anos de experiência nessa área tão incrível. Desde o início de nossa história, já são mais de 100 mil clientes atendidos. Estamos aqui determinados em fazer a diferença, democratizando e simplificando o cuidado com o seu pet para oferecer a melhor experiência para você e seu amiguinho. Mantemos nossas orelhas em pé, atentos às novidades do mundo pet para trazê-las até você. Nós somos apaixonados por pets! O seu pet é também da nossa família! Suplemento Vitamínico Organnact Para Cachorro Nutrifull Dog 120 ml O Nutrifull Dog é um suplemento vitamínico, mineral e aminoácido para cães, indicado para auxiliar na manutenção da boa qualidade da nutrição oferecida diariamente. Nossos pets precisam de uma quantidade especial de substâncias para manter o organismo em ordem e saudável e alguns nutrientes devem ser repostos para complementar a alimentação adequada. Conte com Nutrifull Dog para deixar seu amiguinho mais forte e ativo e ainda beneficiar o seu pelo e pele! - Indicado para cães - Aumenta a energia - Fortalece os ossos e dentes - Auxilia a regeneração dos órgãos - Contém ácido fólico e minerais - Conta com vitaminas do complexo B - Equilibra os líquidos no organismo - Auxilia na regeneração muscular - Proporciona mais disposição e saúde ao pet - Com seringa dosadora - Embalagem de 120ml. *Consulte sempre o Médico Veterinário de sua confiança para o uso apropriado deste produto. Leia a bula ou informações descritas na embalagem."', 193.9, 193.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7qvei-lfjmpu5edvd9b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F17331205241', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18697457556', 'óculos De Natação Adulto Essential Vollo', 'Obtenha muito mais praticidade e conforto durante os treinos de natação com os Óculos Essential Preto Vollo! Com incrível design à prova d''água, os óculos de natação Essential garantem maior proteção e visibilidade durante o mergulho, evitando a entrada indesejada de água durante a prática esportiva. Por possuir narigueira autoajustável o óculos proporciona ao atleta excepcional conforto e flexibilidade durante todo seu uso, atestando muito mais segurança para a realização dos exercícios e confiança para permanecer por mais tempo embaixo d?água. Diferenciais : Óculos inteiriço com narigueira autoajustável Vedação em PVC Qualidade confiável e duradoura Mais liberdade para o desempenho aquático Material flexível que não machuca Especificações : Adulto Composição das ventosas e narizeira: PVC Composição das lentes: PS Composição da tira: TPE Conteúdo da Embalagem: 01 un. Óculos de Natação Adulto Essential Vollo Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 28.0, 28.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-lmynfuvg69fdc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F18697457556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203764960', 'Manta Infantil Microfibra Bene Casa Azul', 'Manta Infantil Microfibra com cobertura macia e confortável. Esse tipo de manta é especialmente projetado para ser usado em camas de crianças, berços ou mesmo no carrinho do bebê. São leves, mas ao mesmo tempo quentes, o que ajuda a manter o bebê aquecido durante o sono. Elas também são fáceis de lavar e secar, tornando-as uma escolha prática para os pais. Medidas: 70cm x 1,00m Gramatura: 180g/m Composição: 100% poliéster.', 74.99, 39.99, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/sg-11134201-824ht-mpxz56fp74lc7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58203764960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
