INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203596640', 'Regata Feminina em Visco Maquinetada Rovitex Preto', 'Regata Feminina Rovitex, confeccionada em visco maquinetada, ideal para dias quentes com muito conforto e estilo. Possui decote redondo e acabamento das cavas em malha canelada, que garante um toque moderno e melhor ajuste ao corpo. Conta com estampa rotativa, trazendo exclusividade a cada peça. A barra tem acabamento com costura dupla, oferecendo maior durabilidade. Uma peça versátil e estilosa para compor diversos looks casuais.', 79.99, 79.99, NULL, 'Women Clothes > Tops > Tanks & Camisoles', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mr1ppn7a7s3k65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58203596640', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998033122', 'Mamadeira Buba Easy Flow Bico Tamanho 2 Elefante 270ml', 'Mamadeira Buba Easy Flow Bico Tamanho 2 Elefante 270ml A Mamadeira Buba de 270ml é ideal para bebês a partir de 2 meses, proporcionando uma alimentação confortável e segura. Com um bico ultrasoft tamanho 2, ela é desenvolvida para se assemelhar ao seio materno, facilitando a transição entre a amamentação e a mamadeira. O bico é flexível e macio, garantindo uma pega confortável para o bebê, enquanto o sistema anticólica reduz a entrada de ar durante a sucção, prevenindo a formação de gases e desconfortos. Feita com materiais de alta qualidade, a mamadeira é livre de BPA e 0% bisfenol A, assegurando a saúde do seu bebê em cada uso. Esta mamadeira é fácil de montar e limpar, garantindo praticidade no dia a dia dos pais. Com um design ergonômico, ela é fácil de segurar, tanto para os pais quanto para o bebê. O frasco transparente permite visualizar a quantidade de líquido, facilitando o controle da alimentação. Com esta mamadeira, os momentos de alimentação se tornam mais tranquilos e seguros, proporcionando o melhor para o seu bebê desde os primeiros meses de vida. Uma escolha inteligente e confiável para o cuidado e bem-estar do seu pequeno. Informações Adicionais: Tamanho: Único Cores: Azul Referência: 17253 Marca: Buba', 49.9, 49.9, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/sg-11134201-7rfi2-m312yn63k6d5f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23998033122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693553607', 'Capacete Liberty 3 New Personalizado Coringa Arlequina', 'Capacete Adesivado ( Sem verniz ) New Tree Este capacete aberto oferece conforto e sensação de liberdade a cada quilômetro percorrido. Graças ao seu desenho, você terá um amplo campo de visão e audição, o que lhe permitirá manter-se atento a fatores externos. Visual clara e sem inconvenientes Com sua viseira simple você desfrutará de passeios agradáveis na moto, pois evitará o ingreso de qualquer elemento do ambiente que possa prejudicá-lo. Rigidez e durabilidade É fabricado com materiais de alta qualidade que absorvem energia e proporcionam grande dureza. Em caso de impacto o golpe se concentrará num só ponto, para amortecer o movimento e evitar contusões. Suavidade em sua caminhada Seu material interno de Nylon é acolchoado e elástico, permitindo maior absorção de impacto quando o capacete para. Sinta conforto e segurança ao longo do seu percorrido!', 204.9, 204.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3knbjcgsk6wd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012518791%2F23693553607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
