INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6057229446', 'Buzina 12v Universal Moto Suzuki Ae 50 / Ae 100 / Rmx 125 / Rmx 250 / Dr 400 / Dr 350', 'EMPRESA: J&J MOTORCYCLES Veja Algumas das Vantagens de Comprar Conosco: • Rapidez no Envio • Ótimo Atendimento • Compra Totalmente Segura ......................................................................................................................................................... PRODUTO: Buzina 12V Universal Moto ......................................................................................................................................................... DESCRIÇÃO: • Buzina Universal Para Motos • 12 Volts • Fabricada em Metal • Fabricante: Smart Fox • Marca: Suzuki • Modelo: Todos • Ano: Todos • Produto Paralelo Compatível Com Diversas Motos: Honda / Yamaha / Suzuki / Dafra e Outras Marcas • Ótima Qualidade • Excelente Acabamento • Nas Cores: Preto Obs: NÃO NOS RESPONSABILIZAMOS POR ERROS NA INSTALAÇÃO E MANUSEIO DO PRODUTO. PARA A SUA SEGURANÇA PROCURE UM PROFISSIONAL ESPECIALIZADO!', 19.9, 19.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/f573566cc5bc75d16f590d0112e39086', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F307813655%2F6057229446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994856195', 'Club 6 Voyage Desodorante Colônia 95ml', 'A perfumaria masculina mais exclusiva de Eudora agora em embalagem ainda mais única esofisticada, mas sem alterar sua fragrância Voyage. O Club 6 Voyage Desodorante Colônia é ideal para te fazer conhecer novos lugares. Com uma fragrância que te leva para o Caribe sem que você saia de casa, este produto é ideal para homens que querem ir além do cotidiano. Inspirado em homens que sempre almejam novas experiências, este desodorante colônia é marcante e inesquecível da embalagem até a última gota. Feito para homens elegantes, poderosos e que gostam de marcar presença, Club 6 Voyage Eudora traz uma experiência sensorial inigualável: Por onde passa, a presença é notada! Com sua perfumação inconfundível, Club 6 Voyage traz um oriental amadeirado com acorde Maridaje: Notas de Rum macerado no carvalho por anos, chocolate e café. Club 6 Voyage Desodorante Colônia é para o homem que está sempre em busca de experiências exclusivas, que sabe aonde quer chegar e que é reconhecido em todos os lugares que passa. Família Olfativa: Oriental Amadeirado Club 6, para ele que é exclusivo. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 154.9, 154.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-825zv-mkwh3kx9o7b5bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F22994856195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203936322', 'Eudora Soul Máscara de Cílios Turbo 5g', 'A Máscara de Cílios SOUL Turbo chegou para revolucionar sua maquiagem, entregando 7 benefícios incríveis em um único produto para um olhar de impacto. Com alta performance, esta máscara vegana e oftalmologicamente testada garante volume 20x maior* E definição 15x maior*, Com longa duração. Conheça as características que farão você se apaixonar: Promove alongamento e curvatura poderosa.Fórmula enriquecida com Pantenol para cílios mais fortes e saudáveis.Pincel com cerdas ultrafinas que evita a formação de grumos.Duração incrível de até 11h. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. *Eficácia comprovada em teste comparativo com máscara incolor (controle) e após 20 passadas. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 44.9, 44.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-8261f-mjyknvcch0cna5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58203936322', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
