INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594671421', 'Kit 02 Fronhas 200 Fios 50x70cm Vida Bela Kacyumara Tintos', 'Fronhas 50x70 Kacyumara – Toque suave, conforto e elegância em cada detalhe As Fronhas 50x70 Kacyumara combinam qualidade superior, design sofisticado e conforto absoluto. Confeccionadas com tecidos nobres e acabamento de alto padrão, garantem toque macio, durabilidade e um caimento perfeito para compor sua cama com elegância e bem-estar. Disponíveis em diferentes versões de tecido, cada linha oferece uma experiência única: 200 fios 100% algodão: frescor natural, toque leve e resistência, ideais para o uso diário. 300 fios 100% algodão egípcio: acabamento acetinado (satinée) com brilho suave e toque extremamente macio, trazendo sensação de luxo e sofisticação. 300 fios fibra de bambu: toque sedoso, brilho delicado e propriedades antibacterianas naturais, que proporcionam conforto térmico e suavidade incomparável. Todas as fronhas possuem acabamento refinado, costuras reforçadas e fechamento seguro, garantindo maior durabilidade e praticidade no dia a dia. Além disso, os tecidos utilizados são respiráveis, antialérgicos e de fácil manutenção, preservando a beleza e a qualidade mesmo após diversas lavagens. Composição: 100% Algodão (200 fios) 100% Algodão Egípcio (300 fios) 100% Viscose de Bambu (300 fios Bamboo) Dimensões: 50 cm x 70 cm (padrão nacional) As Fronhas 50x70 Kacyumara são o complemento ideal para seu enxoval, unindo conforto, praticidade e a excelência que só a Kacyumara oferece.', 109.9, 109.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-821gg-mgo3mlkkf7ka69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F22594671421', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
