INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499260507', 'Polo Feminina Regular Texturizada', 'Polo manga curta confeccionada em malha texturizada diferenciada, que oferece conforto e estilo ao visual. Apresenta ombro levemente deslocado, adicionando um toque moderno e despojado à peça. A modelagem regular proporciona caimento soltinho ao corpo, equilibrando conforto e elegância para diversas ocasiões.Detalhes da peça:Malha de algodãoModelagem regularManga curtaGola poloDecote VTecido texturizado', 239.99, 149.99, NULL, 'Women Clothes > Tops > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-8261w-mj5ptdnsor9db4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F23499260507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799283718', 'Vestido Curto Reto Em Peach Touch', 'Vestido curto em tecido peach touch, que garante toque macio e confortável. Possui alças finas, decote careca e costas retas. A modelagem reta tem caimento soltinho no corpo, proporcionando leveza e liberdade de movimento.Detalhes da peça:Em peach touchModelagem retaComprimento curtoDecote retoAlças finas', 199.99, 169.99, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-8261g-mj70f1wwq2o3b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1024179833%2F22799283718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201212366', 'Bolsa Feminina Republic Vix 4732235', 'Bolsa Feminina Republic Vix 4732235 A Bolsa Feminina Republic Vix 4732235 possui duas alças de mão largas e uma alça removível ajustável para uso transversal. Na parte frontal, há um bolso com zíper para fácil acesso a itens pequenos. O tecido é leve, resistente à água e de fácil manutenção, ideal para viagens curtas ou para o uso diário em atividades esportivas. O formato espaçoso permite carregar roupas, calçados e acessórios com conforto. CUIDADOS: -Guarde em um local seco e arejado evitando locais úmidos. - Evite colocar excesso de peso no produto para não forçar os zíperes e costuras. - Proteja os objetos cortantes e/ou pontiagudos evitando o contato direto com o produto. - Evitar altas temperaturas. - Cores claras poderão manchar quando em contato com outros objetos ou roupas de cores pigmentadas. DICAS DE LIMPEZA: - Para a limpeza utilize apenas pano úmido com sabão neutro. - Não mergulhar na água e não utilizar componentes químicos, solventes ou alvejantes. - Não deixar de molho e secar a sombra.', 164.4, 164.4, NULL, 'Travel & Luggage > Travel Bags > Others', 'https://cf.shopee.com.br/file/sg-11134201-82288-mhm84ribgnwk1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F58201212366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250146837', 'Smartphone Motorola Razr 60 Ultra - 1TB 32GB (16GB RAM+16GB Ram Boost) Snapdragon 8 Elite', 'O Motorola Razr 60 Ultra é a combinação perfeita de inovação e estilo, projetado para aqueles que buscam um smartphone que se destaca em todos os aspectos. Com um impressionante armazenamento interno de 1 TB e 16 GB de RAM, este dispositivo é ideal para gamers e usuários exigentes que necessitam de desempenho superior. O processador Snapdragon 8 Elite, com velocidade de até 4,3 GHz, garante que você possa executar aplicativos pesados e jogos com facilidade. A tela dobrável de 7 polegadas oferece uma experiência visual imersiva, enquanto a tela externa de 4 polegadas permite acesso rápido a notificações e funções essenciais. Ambas as telas utilizam tecnologia HDR10+ e LTPO, proporcionando cores vibrantes e uma taxa de atualização de 165 Hz para uma navegação suave. A qualidade de imagem é complementada pela câmera traseira de 50 MP, que captura fotos impressionantes em qualquer condição de luz. Com uma bateria de 4700 mAh, o Razr 60 Ultra garante que você permaneça conectado durante todo o dia. Além disso, a resistência à água e poeira (classificação IP48) e a presença de reconhecimento facial e leitor de impressão digital oferecem segurança e durabilidade. Este smartphone é a escolha ideal para quem valoriza tecnologia de ponta e design sofisticado.', 8999.0, 6999.0, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mht7cil1umti5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1627665738%2F58250146837', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898098855', 'Estante C/04 Prateleiras 118x60x33cm Yon', 'Sobre o Produto Estante C/04 Prateleiras 118x60x33cm Yon BP A - Est.Preta Descrição do Produto: A estante Yon YOEO1164 combina elegância e funcionalidade, perfeita para ambientes modernos e com estilo. Sua estrutura em tubos de aço com soldas a laser garante robustez e durabilidade, além de um excelente acabamento. Com design de linhas limpas e atemporal, oferece versatilidade para diversos usos, permitindo a criação de composições únicas e personalizadas, perfeita para organizar e exibir objetos decorativos com sofisticação e praticidade. A linha Yon é uma fusão elegante entre o estilo industrial e o contemporâneo. Com linhas limpas, materiais robustos e detalhes sofisticados, essa coleção é perfeita para quem busca um ambiente moderno e funcional. Os móveis desta linha oferecem uma versatilidade notável, adaptando-se a diversos ambientes e necessidades, permitindo a criação de composições únicas e personalizadas. sendo a escolha ideal para quem busca qualidade e estilo em um só lugar. Itens Inclusos: 1 Estante Dimensões dos Produtos (Comp. X Prof. X Alt.): Estante YOEO1164: 60 x 33 x 118cm Informações Logísticas (Comp. X Prof. X Alt.): 01 Vol.: 117,5 x 34,5 x 8,5cm - 10,552kg Total Vol.: 1 - Peso Líq. Total: 9,863kg - Peso Total: 10,552kg Garantia: 6 Meses contra defeitos de fabricação. Informações Técnicas / Características: • Cor do Produto: BP A - Est.Preta • Material: Mdp • Acabamento: BP • Escala de Brilho: Fosco • Fita de Borda: Pvc • Material da Estrutura / Pés: Aço • Acabamento Estrutura: Epóxi-Pó • Possui Prateleiras: 4 • Peso Máximo por Prateleira: 10kg • Possui Pés: 2 • Pés Niveladores: Sim • Formato: Retangular • Ambiente Principal: Escritório • Estilo: Industrial • Suporta Até (kg): 40kg • Recomendações de Uso, Manutenção e Limpeza: Para a limpeza, utilize flanela seca ou pano macio levemente umedecido em água. Utilize um pano seco em seguida. Evite contato com produtos químicos (solventes, thinner, acetona, etc) e não utilize nenhum tipo de esponja de aço. • Necessita de Montagem: Sim / Acompanha Manual de Montagem • Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem. • Observações: Não acompanha acessórios decorativos. Imagens meramente ilustrativas.', 285.15, 255.17, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-823qs-moy0d23n7eh870', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F378940206%2F22898098855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497543398', 'Kit 10 Lâmpadas Super Bulbo Alta Potência Led 20w 6500k - Elgin', 'Kit10 Lâmpadas As lâmpadas Super Bulbo LED de 20W da Elgin são próprias para a substituição das lâmpadas incandescentes ou fluorescentes compactas. Com baixo consumo de energia, economiza até 85% de energia, longa vida útil. Equivale a uma lâmpada incandescente comum de 100W e fluorescente eletrônica de 29W. Produz luz brilhante e suave, próprios para iluminação residencial e comercial. CARACTERÍSTICAS TÉCNICAS IMAGEM ILUSTRATIVA Modelo Lâmpada Alta Potência LED 20W Potência 20W Tensão Bivolt Cor Branca Fria - 6500k Temperatura de Cor 6.500K Fluxo Luminoso 1600 lm Eficiência Energética 80 lm/W Base E27 Ângulo de Abertura 240° Índice de Reprodução de Cor >80 Fator de Depreciação 70% Vida Mediana 25.000 horas Benefícios: Não emite UV. Não emite IR. Baixa geração de calor Não altera a cor dos objetos Aplicações: Estacionamentos Galpões Lojas Shoppings IMAGEM ILUSTRATIVA', 112.9, 67.8, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-821e9-mh8z5cirke8b4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1257849357%2F22497543398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
