INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40158599594', 'Jogo de Assadeiras Brasil em Alumínio Antiaderente Grafite Com 3 Peças - Tramontina', 'O Jogo de Assadeiras Brasil em Alumínio Antiaderente Grafite Com 3 Peças - Tramontina, é composto por três assadeiras de tamanhos e funções diferentes, produzidas em alumínio, ele é um jogo que conta com espessura que proporciona cozimento rápido e uniforme dos alimentos. Seu revestimento interno e externo é em Starflon Max, antiaderente que evita que os alimentos grudem e que torna as assadeiras fáceis de limpar. Além de todas essas características, as peças ainda podem ir à máquina de lavar louças, facilitando suas tarefas na cozinha. Escolha Tramontina e deixe seu dia a dia muito mais prático e cheio de sabor! Descrição do Produto: • Corpo de alumínio com espessura que proporciona cozimento rápido e uniforme. • Revestimento interno e externo de antiaderente Starflon Max que não gruda, é fácil de limpar, mais durável e não é prejudicial à saúde, pois é livre de PFOA. • Podem ir à máquina de lavar louças facilitando seu dia a dia. Acompanha na Embalagem: • 01 Assadeira Funda 28cm - 3,3L Brasil (20051/028). • 01 Assadeira Redonda 24cm - 2,1L Brasil (20057/024). • 01 Assadeira Para Pizza 30cm - 1L Brasil (20059/630). Cód. de Fábrica: 20051/028 + 20057/024 + 20059/630. Marca: Tramontina.', 154.55, 149.9, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/sg-11134201-7rdyx-mc7ygs8p3dll9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F40158599594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
