INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194359271', 'Lixeira Retrátil 1,4l Branco', 'Lixeira Retrátil 1,4l Branco A Lixeira Retrátil 1,4L Plasvale possui tampa retrátil. Seu design sofisticado, desempenha seu papel sem perder a elegância. Ideal qualquer ambiente da sua casa. Fabricada em material resistente, garante organização e praticidade no seu dia a dia! Dimensões: 14,5x21,5cm (Diâmetro x Altura)Peso: 0,124 KgMaterial: plástico Polipropileno. A Plasvale é uma empresa de utilidade doméstica que trabalha com amor na criação, qualidade, sustentabilidade e tecnologia de seus produtos. Nosso objetivo é estar presente nos lares e tornar a vida de nossos clientes mais fácil, prática e feliz. Características Gerais do Produto: - Capacidade: 1,4 Litros - Material: Plástico Polipropileno (PP) - Dimensões: 14,0 cm (C) x 14,0 cm (L) x 21,50 cm (A) Garantia: - 90 dias após o recebimento do produto', 19.9, 19.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-824hc-mdw69rizrgn487', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23194359271', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
