INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698422592', 'Fantasia Sereia Bebê Com Cauda Escamada E Laço', 'A Fantasia Sereia Bebê é puro encanto e delicadeza! Com design inspirado no universo mágico do fundo do mar, ela proporciona um visual divertido e fofo para as pequenas sereias brilharem em qualquer ocasião especial. Essa fantasia é ideal para bebês e crianças pequenas em festas temáticas, ensaios fotográficos e comemorações especiais como o mesversário. A cauda com escamas simuladas traz movimento e autenticidade, enquanto os tons verde-água e lilás conferem leveza e magia ao visual. A modelagem é confortável e prática, com alças reforçadas e tecido maleável que se ajusta ao corpo da criança sem apertar. Diferenciais: - Cauda escamada aplicada nas costas com acabamento furta-cor - Saia com babados e camadas fluidas de tule leve - Laço delicado no busto com detalhe perolado Disponível em tamanhos para bebês: P - 1 Ano M - 2 Anos. Genero: Menina PERSONAGEM: Sereia Bebê Descrição: Fantasia Sereia Bebê Codigo do Produto: 911726 Tamanhos: P - 1 Ano / M - 2 Anos Itens Inclusos: Vestido', 139.99, 139.99, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rep7-m8xff9uqv2xz7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410794727%2F22698422592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
