INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399017112', 'Vestido Infantil Menina Ombro Com Laço Colorittá Bege', 'O Vestido Colorittá é a escolha certa para um visual elegante. Feito em tecido linho rústico, ele possui recortes franzidos para proporcionar uma modelagem soltinha e detalhe de manga assimétrica, que traz um maxi laço na alça, ideal para garantir um toque de sofisticação. Perfeito para ocasiões especiais ou momentos que pedem um visual mais arrumado, esse vestido encantador vai ganhar o coração das meninas. Aposte!Detalhes da peça: • Feito em tecido linho rústico • Modelagem soltinha • Possui mangas assimétricas • Possui detalhe de maxi laço na alça • Ideal para ocasiões especiais e momentos que pedem um look arrumado', 199.9, 79.96, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mr1tn48fepl0f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23399017112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57452643571', 'Sensor Inteligente de Presença Articulado 360 ou Portas e Janelas Zigbee ou Wi-Fi 2.4 GHz Branco Avant Neo', 'Sensor de Porta e Janela Zigbee Neo Avant Automação Residencial O Sensor de Porta e Janela Zigbee Neo Avant oferece monitoramento preciso e segurança avançada para sua casa. Com protocolo Zigbee, ele otimiza sua rede Wi-Fi, garantindo uma conexão estável e eficiente para integrar entradas de forma inteligente ao seu ecossistema. Características: - Comando de voz com Alexa ou Google Assistente - Controle completo via app Neo Smart (Android e iOS) - Conexão Zigbee - Programar Horários automáticos - Criação de cenas inteligentes - Acabamento Premium branco - Não sobrecarrega Wi-Fi - Instalação articulada prática - Sensor de alta precisão Material: Policarbonato Tamanho do Item: 71x25x20mm | 36x10x17mm Peso do produto: 0.043 kg ESPECIFICAÇÕES TÉCNICAS Alimentação: 2 Pilhas AAA (Não incluso) Comunicação: Zigbee 3.0 Índice de proteção: IP20 Compatibilidade: Tuya e Smartlife Requer hub Zigbee para funcionar Ambientes ideais para utilização: Ideal para portas, janelas, gavetas, cofres e armários residenciais ou comerciais. Dica: Utilize este sensor em cenas inteligentes para criar alertas de segurança ou acender luzes automaticamente ao abrir uma porta. Garantia: Garantia Oficial da Marca de 12 meses para defeitos de fabricação Sobre a Marca: Neo Avant: inovação em cada detalhe para sua automação residencial. Oferecemos soluções completas em iluminação, Interruptores, Tomadas, sensores, câmeras, fechaduras e hubs inteligentes. Tecnologia de ponta e alta qualidade para transformar a sua rotina e valorizar sua casa.', 171.29, 119.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > House Alarms', 'https://cf.shopee.com.br/file/sg-11134201-823qd-moucc2cs3nyk1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297519240%2F57452643571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
