INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994341248', 'Caixa De Som Acústica Amplificada Ativa 800W 15 Polegadas ProBass ELEVATE 115" 800w USB Bluetooth', 'Caixa Amplificada ProBass ELEVATE 115" 800w USB Bluetooth A Pro Bass Elevate 115 é a escolha ideal para quem busca potência, versatilidade e qualidade sonora em um único equipamento. Com um woofer de 15 polegadas, esta caixa proporciona graves profundos e agudos nítidos, sendo perfeita para eventos, apresentações ao vivo, igrejas, palestras, DJs, bares e festas em geral. Equipada com conectividade Bluetooth e tecnologia TWS, permite emparelhamento com outra caixa Elevate 115 para uma experiência estéreo sem necessidade de cabos. Conta ainda com entradas P10, XLR, RCA e auxiliar P2, oferecendo compatibilidade com uma ampla variedade de dispositivos. CARACTERÍSTICAS Potência RMS:180 W Potência de pico: 2000 W Alto-falante: 15" (woofer) Driver: 1" (tweeter de titânio) Impedância: 4 ohms Resposta de frequência: 60 Hz – 35 kHz Entradas e Conectividade 2 entradas P10 (microfone/instrumento) 2 entradas XLR 1 entrada RCA (Line In) 1 saída RCA (Line Out) 1 entrada auxiliar P2 Conexão Bluetooth Tecnologia TWS (conexão estéreo sem fio entre duas caixas) Recursos e Controles Equalizador digital integrado Controle de volume geral Controle de graves (Low) e agudos (High) Controle de Echo Função Talk Over (prioridade de microfone) Display LCD Alimentação Bivolt automático (110–220 V) Dimensões e Peso: Altura: 75 cm Largura: 50 cm Profundidade: 40 cm Peso: 13,3 kg ACOMPANHA: 1X Caixa Amplificada ProBass ELEVATE 115" 800w USB Bluetooth Cor:Preto 1X Controle remoto 1X Suporte para pedestal *IMAGENS ILUSTRATIVAS* *GARANTIA 03 MESES*', 1247.99, 1123.2, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/br-11134207-820m1-mq94a9ktryf524', 'https://shope.