INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193909932', 'Tênis Olympikus Feminino Acqua Corrida', 'Treine com o estilo e o conforto do tênis Olympikus Acqua, a escolha perfeita para quem valoriza praticidade no cotidiano. Este modelo conta com a tecnologia EVASENSE da Olympikus, que utiliza EVA para proporcionar a máxima suavidade e conforto absoluto em todas as suas atividades diárias. O cabedal é feito com tecido jacquard com padrão geométrico tendo o logo da Olympikus em material laminado em high frequency, dando um toque único ao cabedal. O forro em tecido poliéster com espuma, o atacador em tecido poliéster texturizado garantem um calce fácil e confortável. A palmilha plana, feita de tecido poliéster e EVA, possui uma aplicação gráfica que complementa o design. Não perca a oportunidade de experimentar o conforto e o estilo do tênis Acqua, adquira já o seu!', 289.89, 189.88, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zvz-mmj2te5odgclb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F23193909932', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22895919912', 'Cabo Santo Angelo Direct Angel TX 4,57m P10xP10 Guitarra Baixo Violão 10974', 'Cabo Santo Angelo Direct Angel TX 4,57m P10xP10 Guitarra Baixo Violão 10974 O Cabo Santo Angelo Direct Angel TX 4,57m é um cabo de áudio de alta qualidade projetado para guitarras, baixos e violões. Com um comprimento de 4,57m, é ideal para apresentações ao vivo e gravações em estúdio. Possui conectores P10 em ambas as extremidades, garantindo conexões seguras e livres de interferências. Com o número de série 10974, este cabo é um produto autêntico da marca Santo Angelo, reconhecida por sua durabilidade e qualidade sonora excepcional. Sua estrutura em cobre sem oxigênio oferece uma transmissão de sinal limpa e clara, proporcionando um som cristalino e de alta fidelidade. Transmissão de sinal com mais eficiência;Revestimento de maior resistência mecânica e diferentes características de construção que ressaltam o melhor desempenho em média frequência;O design arrojado das capas traz maior praticidade e mobilidade para quem adquire os cabos desta linha;Fabricado com liga de cobre OFHC (Isento de Oxigênio);Bitola de 0.30 mm² / AWG (G30T);ESPECIFICAÇÕES: Marca: Santo Angelo;Tamanho: 15ft / 4,57M;Linha: Textil;Modelo: P10 ANGEL L TX 15FT;Aplicação: Guitarra; Montado com conectores P10 x P10 90° usinados em latão (CLA) niquelados e blindados com termocontratil. *Garantia de 1 ano de garantia* *Imagens Ilustrativa*', 94.81, 85.33, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7qvf8-lhnvj0rrqnjs45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F22895919912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
