INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397683432', 'Par Lanterna Traseira Saveiro G4 2006 2007 2008 2009 2010 2011 2012 2013 Bicolor Lente Estriada', 'Par Lanterna Traseira Volkswagen Saveiro G4 2006 2007 2008 2009 2010 2011 2012 2013 Bicolor Características: Produto novo de ótima qualidade; Feito sob medida, encaixe perfeito; Não acompanha lâmpadas e soquetes. Especificações técnicas: Cor: bicolor; Cor da carcaça: preto; Freio rubi, ré e pisca fumê; Suporta lâmpadas até 55 watts; Lente estriada em acrílico resistente. Compatível com os modelos: Saveiro G4 2006 a 2013. Serve com adaptação para os modelos: Saveiro G3 2000 a 2005; Saveiro G2 Bola 1998 a 1999. Garantia: 90 dias. Dica: Dê um novo visual para o seu carro, aqui você encontra os melhores produtos com os melhores preços. Importante: NÃO somos responsáveis pela má instalação ou mau uso do produto, para evitar transtornos procure por um profissional especializado.', 286.66, 258.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lv513vkkb5xmf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242764769%2F19397683432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699251724', 'BARBIE DREAMTOPIA O MUNDO DOS SONHOS O MUNDO DOS SONHOS', 'BARBIE DREAMTOPIA O MUNDO DOS SONHOS O MUNDO DOS SONHOS Antes de dormir, Barbie leu uma história muito especial para sua irmã caçula, com fadas e princesas. Então, Chelsea sonhou a noite inteira com aquele mundo cheio de magia e personagens especiais. Enquanto se diverte pintando os lindos desenhos deste livro, descubra o desfecho dessa história fabulosa. . Informações Adicionais Autor: CIRANDA, CULTURAL Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: BARBIE DREAMTOPIA O MUNDO DOS SONHOS O MUNDO DOS SONHOS Idioma: INDEFINIDO Páginas: 16 Edição: 1 ISBN-13: 9788538077886 ISBN-10: 8538077880', 19.19, 14.49, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-lvb2didlv1ox62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F19699251724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
