INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20197968724', 'Serra Tico Tico Industrial 650W JV0600K 110V Makita', 'Código Fornecedor: JV0600K-110V Marca: Makita Itens que acompanham: Chave allen Lâmina de serra Maleta A Serra Tico-Tico JV0600K da Makita é a ferramenta ideal para marceneiros profissionais. Com potência de 650W e velocidade variável de 500 a 3.100 golpes por minuto, ela permite realizar uma ampla variedade de cortes em madeira, metal e outros materiais. A serra possui dupla isolação, o que garante segurança ao operador. Além disso, ela é adaptável a coletor/aspirador de pó, o que ajuda a manter o ambiente de trabalho limpo. Especificações técnicas: Potência: 650W Golpes por minuto: 500 - 3.100 Comprimento do golpe: 23mm Capacidades Madeira: 90 mm Aço: 10 mm Dimensões(C x L x A) : 236 x 77 x 199mm Peso: 2,4 Kg Emissão de vibrações: 10,5m/s² Incerteza K: 1,5m/s² Tecnologias: Dupla isolação Velocidade variável Adaptável a coletor/aspirador de pó Corte orbital Encaixe T Segmentos: Diversos e Marcenaria Aplicações: Alumínio Diversos Madeira Metal Plástico Garantia: 12 meses', 1401.9, 1401.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-m1enlltc1ut60e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F20197968724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998021098', 'Lustre Led Pendente Infinito Luxo Design Moderno Bivolt 45w Brinovar', 'LUSTRE PENDENTE INFINITO BRINOVAR Dê um toque de sofisticação e modernidade ao seu espaço com o Lustre Infinito Pendente. Sua estrutura deslumbrante e design inovador criam um ambiente onde o luxo e a funcionalidade se encontram. Faça do seu lar um verdadeiro espetáculo de luz e beleza, que impressiona e acolhe. ESPECIFICAÇÕES TÉCNICAS: Marca: Brinovar Modelo: Pendente Infinito/Clave Sol Material: Estrutura em alumínio e iluminação em LED Indicação: Ambiente Interno Instalação: Teto Potência Total: 45w Temperatura da Iluminação: Branco frio, morno/neutro e quente 3000 à 6000k Intensidade da Iluminação e Brilho: Ajustável pelo controle remoto Sistema: Energia Elétrica Voltagem: Bivolt Medidas do lustre: 31cm (C) x 75cm (L) x 4cm (A) Cabo ajustável de até 1.20m Com Controle Fácil Ajuste LED integrado Garantia: 90 dias ITENS INCLUSOS: Lustre Infinito Controle Remoto Parafusos e Buchas para Instalação', 461.0, 330.53, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2qmnn3cllad8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1029852536%2F23998021098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254083957', 'Eudora Instance Rosa Absoluta Creme Desodorante Corporal 400ml', 'Este cuidado corporal é a escolha ideal para quem busca nutrição profunda, firmeza e um toque de sofisticação, transformando o autocuidado em um momento de pura sensualidade. Este item, que possui 95% de ingredientes de origem natural e é vegano, proporciona uma experiência luxuosa inspirada na elegância da Rosa. Conheça as características desse produto que vão fazer você se apaixonar: Promove sensação de firmeza e vitalidade graças ao poder do Hydracolageno (Colágeno Vegetal).Oferece toque aveludado com textura cremosa ultra macia.Possui rápida absorção, não deixando a pele pegajosa.Garante perfumação intensa, um floral moderno e sofisticado na fusão elegante da Rosa com a suculência da Lichia. Sua formulação conta com glicerina vegetal e a luxuosa manteiga de karité, garantindo nutrição e maciez que duram o dia todo. O resultado é uma pele ultra macia, desodorizada, com aspecto revigorado e envolta por uma fragrância sofisticada. Além disso, o frasco do produto é feito de plástico reciclado, reforçando o compromisso com o futuro. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 59.99, 59.99, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8261d-mjymh84enrb753', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58254083957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204089552', 'Eudora La Piel Tâmaras Egípcias Hidratante Desodorante 400ml', 'O Hidratante Desodorante Corporal La Piel Multirreparação da Pele Tâmaras Egípcias promove uma multirreparação à pele: Traz força à sua camada externa, restaura a barreira cutânea e a protege dos danos diários. Pele profundamente hidratada por 48 horas. O hidratante desodorante corporal é enriquecido com Extrato de Tâmaras Egípcias e ingredientes hidratantes e nutritivos. Reúne Biocolágeno, Niacinamida e Pantenol, aumentando a produção de colágeno natural e firmando a pele com 14 dias de uso. Sem falar no cheiro delicioso das notas Orientais Gourmand deste produto! Para potencializar o seu tratamento, combine qualquer hidratante corporal de La Piel ao Sérum Booster de Biocolágeno, para melhorar a firmeza, a elasticidade e dobrar a sua hidratação. Dermatologicamente testado Vegano Livre de sulfato, parabenos e óleo mineral Embalagem com 10% de plástico PCR. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. Chega mais para conhecer a linha La Piel e se apaixonar por todos os produtos. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 67.9, 67.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8262o-mjymew7gz3euca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58204089552', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
