INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253326870', 'Eudora Booster Proaging Siàge Hair-Plastia 100ml', 'O Booster Proaging Siàge Hair-Plastia reforça a estrutura do fio de dentro para fora, adiando o envelhecimento e garantindo um cabelo mais forte e com 5x menos quebra. ﻿ Sua fórmula rica em Vitaminas do Complexo B, promete hidratação profunda, fios encorpados e com vida por muito mais tempo. Além de benefícios como: -Reforçar a estrutura do fio, adiando o envelhecimento; -5x menos quebra​; -Proteção térmica; -Controla o frizz; -Pontas reestruturadas; -Age nas áreas danificadas. O Booster Proaging Siàge Hair-Plastia pode ser usado como finalizador ou na máscara capilar, agindo de dentro para fora e corrigindo as lesões do cabelo. SOBRE A LINHA Desenvolvido com Inteligência Artificial e Bio Hialurônico, Siàge Hair-Plastia é tecnologia para o seu melhor cabelo, todos os dias. A Inteligência Artificial combinou milhares de dados e estudou o comportamento das pessoas para atender com precisão as necessidades das consumidoras. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 55.0, 45.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261a-mjijqqq90ttw6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58253326870', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
