INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49954330097', 'Tênis Qix 90''s Slim Original Lançamento Básico Confortável Sintético Masculino Feminino', 'Fabricado em materiais sintéticos de alta qualidade, o Qix 90''s Slim estreia a nossa linha Green Series, que tem o intuito de reduzir o impacto ambiental e promover o bem-estar animal. Pensado para uso no dia a dia e para iniciantes nas pistas de skate, o Qix 90’s Slim vem com solado de borracha natural blaqueado (costura dupla), o que garante mais durabilidade e resistência. O modelo conta ainda com detalhes de frequência em alto relevo, que garantem estilo e beleza para o seu look. Indicado: Dia a dia, casual, noite, lazer, skate iniciante, street. Material do cabedal: sintético. Tipo de ajuste: Cadarço. Palmilha: E.V.A. antibacteriano (evita bactérias e fungos). Solado: Borracha natural, blaqueado (costura dupla no solado) garantindo assim maior durabilidade e resistência que só a Qix pode oferecer. Forma: Normal. Peso: 800g (aprox.) *Fotos reais do produto, feitas por nossa equipe.', 299.9, 269.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj7bi6p1vlkyce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976841479%2F49954330097', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698369404', 'Rolamento Roda Dianteira Hyundai Azera 3.3 V6 24V (06-11) / Kia Opirus (04-10) - IR14587', 'Especificações Técnicas: • Marca: IRB Automotive • Cód. da montadora: 51720-3A200 • Posição: Roda Dianteira • Veículos com ABS: Sim • Tipo de rolamento: Duplo • Cód. de similares: 713 6266 20 / ALR-4587 / BH 4587 / R184.60 / FW87 Medidas: • Diâmetro Interno: 45 mm • Diâmetro Externo: 87 mm • Espessura: 41/39 mm Aplicações: - Hyundai Azera 3.3 V6 24V (2006 – 2011) - Kia Opirus lançados a partir de 2004 Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. IRB é uma marca brasileira que fornece peças automotivas voltada ao segmento de reposição para todo Brasil. Atendendo frotas de veículos nacionais e importados! Não esqueça de verificar ano, modelo e se o veículo é com ABS ou não! Na dúvida, verifique a compatibilidade pelo código da peça do seu veículo ou mande mensagem para verificarmos a aplicação do produto para você. Evite erros na compra!', 174.9, 154.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m827wrjpohzl67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F23698369404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
