INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41715210616', 'NIVEA SUN Protetor Solar Facial Beauty Expert Controle de Oleosidade FPS 60 50g', 'O que é? NIVEA SUN Facial Beauty Expert Controle de Oleosidade FPS 60 é um protetor solar de muito alta proteção que ajuda a controlar a oleosidade da pele e não obstrui os poros. Para que serve? Desenvolvido especialmente para a pele delicada do rosto, este protetor solar oferece proteção por dentro* e por fora contra os raios UVA/UVB. Além de ajudar a proteger contra os efeitos causados pela luz visível, protege também contra o envelhecimento prematuro da pele causado pelo sol. Com uma fórmula de textura leve, não pegajosa, proporciona efeito matte instantâneo e duradouro, não deixando a pele com aspecto pesado e oleoso. *Contém Licochalcona A, um antioxidante que atua a nível celular e auxilia na redução do estresse oxidativo da pele induzido pela exposição à luz visível e à poluição. Benefícios e diferenciais: - O FPS 60 garante muito alta proteção solar - Efeito matte instantâneo e duradouro - Proteção por dentro* e por fora - Não obstrui os poros - Dermatologicamente e oftalmologicamente testado - Previne o envelhecimento da pele - Textura leve - Controla a oleosidade - Poderoso efeito antioxidante natural - Com antioxidante*', 73.9, 73.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meebqrpwt24h5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F41715210616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9886117574', 'NIVEA Sabonete em Barra Erva Doce & Óleos 125g', 'O que é? NIVEA Sabonete em Barra Erva Doce é um produto que contém todos os cuidados que sua pele precisa para se manter hidratada, perfumada e fresca até mesmo depois do banho. Para que serve? Enriquecido com o poder dos óleos vegetais, NIVEA Sabonete em Barra Erva Doce garante uma limpeza suave e hidratante para todos os tipos de pele. Sua fragrância encantadora de erva-doce proporciona uma sensação de frescor e bem-estar, enquanto o toque especial da glicerina nutre a pele e ajuda a garantir uma experiência revigorante no seu ritual de banho. Produto dermatologicamente testado e recomendado para uso diário. Benefícios e diferenciais - Com hidratante - Fragrância deliciosa de erva-doce. - Com glicerina - Espuma cremosa - Dermatologicamente testado Como usar o Sabonete em Barra NIVEA Erva Doce? Massageie suavemente na pele molhada até formar espuma. Enxágue com água em abundância. Uma unidade de embalagem contém 125g"', 4.2, 4.2, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meedgoyyk5qa19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F9886117574', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
