INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48050160801', 'Hit Protein 900g Adaptogen - Whey Protein', 'HIT PROTEIN® é um Suplemento Proteico que contém Whey Concentrado e Peptídeos de Colágeno Hidrolisado, combina qualidade nutricional com o sabor marcante que é a assinatura da Adaptogen Science®. Cada dose oferece 20g de proteína para apoiar o ganho de massa magra, a recuperação muscular e a manutenção de uma dieta equilibrada, com ótimo custo-benefício e um sabor que conquista desde o primeiro gole. Com fórmula sem adição de açúcares e livre de glúten, é uma escolha versátil para diferentes rotinas e perfis alimentares. HIT PROTEIN® foi desenvolvido para quem valoriza o essencial: sabor, qualidade e uma nutrição que entrega desempenho real, além de um ótimo custo-benefício. Com conceito “High Impact Tasty”, HIT é mais do que um nome é uma proposta: oferecer alto impacto nutricional, intensidade na experiência e um sabor que se destaca em cada dose. HIT Protein Adaptogen é um suplemento proteico desenvolvido para quem busca performance, praticidade e sabor excepcional. Um Blend Proteico Combinando Whey Protein Concentrado e Peptídeos de Colágeno Hidrolisado, oferece uma fórmula completa, ideal para apoiar o ganho de massa magra, a recuperação muscular e o cuidado com articulações e pele. Sem adição de açúcares e com sabores desenvolvidos pela tecnologia exclusiva Tasty, HIT Protein entrega uma experiência única a cada dose. INGREDIENTES: Proteína de soro do leite concentrada, peptídeos de colágeno hidrolisado, cacau em pó, flocos de chocolate maltado, aroma sintético idêntico ao natural de chocolate maltado, cloreto de potássio, estabilizante goma xantana, edulcorantes: sucralose e acessulfame de potássio. ALÉRGICOS: CONTÉM LACTOSE. CONTÉM GLÚTEN. SUGESTÃO DE USO: Misture 2 dosadores (35 g) a 200 ml de água gelada ou sua bebida de preferência. Recomenda-se tomar uma porção após atividade física.', 149.9, 124.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg8ojw1kjqbpb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389266749%2F48050160801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
