INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24464190803', 'dr.g red blemish bakuchiol porejet cream 50ml', 'Dra.g mancha vermelha bakuchiol porejet creme 50ml envio da coreia 💜Creme calmante e forte de elasticidade dos poros que visa poros, tez, e textura calmante e forte. 💜O nascimento do Bakuchiol PDRN, um ingrediente patenteado proprietário hipoalergênico e altamente eficaz que cuida de tudo, desde os poros até a elasticidade da pele! 💜A tecnologia de direção dupla penetra até a 20a camada de pele em apenas 3 segundos, proporcionando efeitos de melhoria da pele rápida e poderosa! 💜Exosomes duplos duplos de 2600 vezes menores que os poros, que são 2600 vezes menores que os poros, entregam rapidamente ingredientes ativos uma vez do lado de fora da pele e uma vez por dentro. [COMO Usar] Depois de lavar o rosto de manhã e à noite, pegue uma quantidade adequada, espalhe suavemente ao longo da textura da pele e dê leves batidinhas para absorver. [Capacidade Do produto] 50ml #Korean Cosméticos #K-Beleza #good Produto com produto #good Preço -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 💖Três promessas de koksara.kbeauty 1.Confeccionamos desinfecção três vezes por semana.√ 2.Vendemos 100% genuíno.√ 3.Tempo de carregamento: Todo o tempo [24/7].√', 225.0, 194.0, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134207-7rccn-lrxwuqcfysc3e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F457864097%2F24464190803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7369759940', 'Sandália Infantil Plugt Menino Confortável Divertido Monstros Preto Azul Divertido Original', 'Essa Sandália Plugt Mini Bizz Monstro Preto é muito divertida. Ela tem um monstrinho simpático em cada pé, e um deles tem a boca bem sorridente que até da pra ver o pézinho da criança atravez dela. A sandália é bem leve, com material de toque macio e super fácil de limpar. O fechamento trazeiro é de contato facilitanto o ajuste do calce e o solado é antiderrapante, garantindo o conforto e a segurança da garotada. Comprimento da Palmilha em CM: (medida do dedão ao calcanhar) 19/20 - 13,3 cm 21/22 - 14,6 cm 23/24 - 16 cm 25/26 - 17,3 cm -------------------------------------------------------------------------------------- SOBRE NÓS: A Plugt é uma empresa especialista em fabricação de calçados infantis injetados. O material que utilizamos é o PVC Microexpandido que além de leve, confortável, FÁCIL DE LAVAR, ainda é RECICLÁVEL (o que conseguimos fazer desde o processo produtivo até após o uso - um processo amigo do meio ambiente). Sempre nos inspiramos no poder da imaginação das crianças para criar produtos divertidos e coloridos assim como a Plugt é! Ah, e sem deixar de lado o conforto, a praticidade de calce e a facilidade em lavar que as mamães amam! Fabricamos calçados do 19/20 até o 41/42', 89.9, 69.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln73iyhwwu6ced', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F284865829%2F7369759940', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
