INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43359463585', 'Kit 54 Deck Modular Plástico de encaixe lateral 33x33 - Box, Varanda, Quintal, Piscina', 'Kit com 54 Peças de Deck Modular – Cobre até 6,0 m² Descrição O Kit com 54 peças de Deck Modular é a escolha ideal para quem deseja transformar grandes áreas com agilidade e eficiência. É resistente, bonito e de fácil instalação, proporcionando um acabamento sofisticado sem a necessidade de obras. Ficha técnica Medida de cada peça: 33 cm x 33 cm x 1,5 cm Área total aproximada: 6,0 m² Material: PP – Polipropileno (Classe A) Capacidade: Suporta carga estática de até 2 toneladas por metro quadrado Encaixe: Macho/fêmea AMBIENTES: Onde Instalar o Deck Modular -Quintal - Varandas/ Sacadas -Saunas -Piscinas -Sacada -Jardim -playgrounds -Banheiro / Box -Áreas Úmidas e secas em geral. VANTAGENS do Deck Modular: - Possui vazão no escoamento de líquidos. - Permite fácil higienização e esterilização, inclusive com vapor. - Inalterável a agentes químicos, ácidos, sais e álcalis. - Superfície superior antiderrapante Atenção: Recomendo instalar em uma base firme e nivelada como um contra piso. *Não recomendado instalação sobre a Grama, Terra ou Brita.', 1070.0, 989.9, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mci5ngciblmab0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F386232023%2F43359463585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197738383', 'Lâmina Para Tosa Cães e Gatos Andis Ultraedge 5F Pta', 'As lâminas profissionais Ultraedge, sinônimo de avanço tecnológico, são responsáveis pela longa durabilidade do corte, pelo excelente desempenho e pelos longos intervalos entre a afiações. As lâminas têm um acabamento especial em cromo para resistir oxidações, acarretando melhora no desempenho. Compatíveis com as marcas Oster A5 , Andis, AG, AGC, WahlKM1, Km2 e Laube. ALTURA DO CORTE: 6,3 mm Marca: Andis', 410.0, 401.8, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdw4-lzgsrxxvyhwocd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F23197738383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797796911', 'Escova Pet Cachorro Gato Bass de Acrílico com Pinos de Metal Sem Bolinhas - Preta - M', 'Criada para facilitar os trabalhos em animais com pelagem lisa e primitiva. Feita em acrílico resistente, com cerdas firmes e médias, possui uma almofada central macia. Recomendada para trabalhar com filhotes e animais com peles delicadas. Pinos de metal, alta durabilidade. Se atentar aos cuidados para a vida útil da escova ser longa. Medidas: Altura: 22cm Largura: 6cm Tamanho dos pinos: 2,5cm (aproximadamente) Marca: Bass Leia atentamente sobre como cuidar e prolongar a vida útil da sua escova. - Evitar usar no pelo molhado (pingando); - Não guardar o item úmido; - Não usar produtos abrasivos para limpeza; - Nunca deixar o item de molho em qualquer líquido que seja; - Evitar utilizar para remover nós e embolos; - Não utilizar pente entre os pinos para remoção da pelagem que fica na escova, sempre remover delicadamente com as mãos; - Lembrando que em cidades mais úmidas ou com maresia a condição do aço pode ser afetada. GARANTIA DE 90 DIAS CORRIDOS CONTRA DEFEITO DE FABRICAÇÃO A CONTAR DA DATA DO RECEBIMENTO.', 138.0, 131.1, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma8u0rxuk4ft80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F20797796911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294769160', 'Vinho Tinto Chileno Reservado Sweet Red 750ml', 'Reservado Sweet White: Tropical, leve e suavemente doce De cor clara e brilhante, com um amarelo pálido e reflexos esverdeados, o Reservado Sweet White revela leveza e frescor desde o primeiro gole. Esse vinho apresenta uma aparência vibrante que convida a uma experiência refrescante e delicada. No aroma, destacam-se notas elegantes de frutas tropicais maduras, com ênfase envolvente no abacaxi, que conferem um perfil aromático doce e cativante. No paladar, o vinho é suave e equilibrado, com sabor adocicado que se harmoniza perfeitamente com sua acidez, prolongando o frescor e a presença frutada a cada gole. A linha Reservado Spritzer traduz a qualidade e o espírito casual da Concha y Toro, trazendo vinhos que combinam frescor e suavidade para diversas ocasiões. Harmonização perfeita: Acompanha sobremesas leves, como papaias em calda, cremes doces e aperitivos com frutas tropicais, realçando momentos doces e descontraídos. Uma experiência envolvente Concha y Toro Descubra a leve doçura e o frescor tropical do Reservado Sweet White, um vinho que transforma qualquer momento em celebração. Cor clara e brilhante. Amarelo claro com reflexos esverdeados que reforçam sua leveza e frescor desde a primeira prova. Aroma tropical elegante. Notas suaves de frutas tropicais maduras, com destaque envolvente para o abacaxi. Paladar doce e equilibrado. Sabor adocicado com acidez harmoniosa e notas tropicais que prolongam o sabor a cada gole. Ideal com sobremesas leves. Combina perfeitamente com papaias em calda, cremes doces e aperitivos com frutas tropicais. Qualidade Concha y Toro. A linha Reservado Sweet oferece vinhos leves, frutados e com final suavemente adocicado. Características: - Aromas de frutas tropicais e abacaxi - Harmoniza com papaias em calda, cremes doces e aperitivos com frutas tropicais Informações Técnicas: - Volume: 750 ml - Tipo de vinho: Branco - Origem: Chile', 39.9, 29.9, NULL, 'Food & Beverages > Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-822x3-mi4l6gcm718o66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1639481065%2F22294769160', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
