INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43765189685', 'Brinco de Prata 925 Coração com Zircônias e Lacinho', 'Brinco de Prata 925 Coração com Zircônias e Lacinho: Charme e Delicadeza O Brinco de Prata 925 Coração com Zircônias e Lacinho é uma peça delicada que une charme e sofisticação. Com design em formato de coração cravejado com zircônias e detalhe de lacinho, este brinco é perfeito para quem deseja trazer estilo e personalidade ao visual. Produzido em Prata 925 de alta qualidade, garante brilho duradouro e resistência, tornando-se um acessório atemporal. Especificações do Brinco Tamanho do Brinco: 8mm Peso: 0,9g Material: Prata 925 Destaques do Brinco Design em coração cravejado com zircônias, transmitindo delicadeza e brilho. Detalhe de lacinho que confere charme extra e sofisticação. Produzido em Prata 925 de alta qualidade, garantindo durabilidade e resistência. Leve e confortável, ideal para uso diário ou ocasiões especiais. Charme e Elegância para Seu Visual O Brinco de Prata 925 Coração com Zircônias e Lacinho combina delicadeza e estilo, sendo perfeito para complementar qualquer look com sofisticação e charme. Cuidados com o Brinco Evite contato com produtos químicos para preservar o brilho da prata. Guarde em local seco e seguro para evitar arranhões e oxidação. Limpe regularmente com flanela macia para manter o brilho e a beleza do brinco. Adicione Charme e Delicadeza ao Seu Estilo Inclua o Brinco de Prata 925 Coração com Zircônias e Lacinho em sua coleção e experimente um acessório sofisticado, delicado e repleto de charme para complementar seu visual.', 59.7, 47.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mdw4998elgcj6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F43765189685', NULL, NULL, '2026-07-28T02: