INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6790373283', 'prata 925 corrente + pingente cruz 70cm', 'Descrio do produto: Garantia Peso Aproximado : 2,80g Malha Veneziana Tamanho 70cm corrente + 2cm pingente Gnero unisex Largura 1mm Itens inclusos * Certificado de Garantia Cuidados e manuteno * Para limpar use apenas flanela * Deve-se evitar o uso nas tarefas domsticas, pois produtos qumicos danificam a pea * Procure separar as peas na hora de guardar Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jia com durao para o resto da vida. A prata 925 um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jias tem certificado de autenticidade reconhecidos no mundo todo, voc pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dvidas, no hesite em perguntar por favor! Ser um prazer atend-lo. Acompanha certificado que garante teor 925 do produto. EQUIPE AQUAMETAIS', 209.67, 159.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-m5omwdc4xqla4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F6790373283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892520664', 'Pulseira Feminina de Prata 925 Baguete com zircônia', 'Pulseira Feminina de Prata 925 Baguete com Zircônia Adorne seu pulso com a elegância da Pulseira Feminina de Prata 925 Baguete com Zircônia. Com um tamanho ajustável de 20cm (pode ser fechado com 19cm), esta pulseira apresenta uma espessura delicada de 1mm, proporcionando um toque de sofisticação. O pingente com detalhes em baguete e zircônia, medindo 6mm, adiciona brilho e charme à sua joia. Especificações: Tamanho: 20cm (pode ser fechado com 19cm) Espessura: 1mm Tamanho do Pingente: 6mm Modelo da Pulseira: Cartier Redondo Peso: 1.7g Material: Prata 925 Design Cartier Redondo O modelo da pulseira estilo Cartier Redondo destaca a beleza dos detalhes em baguete, criando uma peça única e estilosa. Com um peso leve de 1.7g, esta pulseira é ideal para expressar sua feminilidade com elegância. Qualidade em Prata 925 Fabricada em Prata 925 de alta qualidade, garantimos durabilidade e brilho excepcionais. Cada detalhe é cuidadosamente trabalhado para oferecer uma pulseira que reflete a beleza única de quem a usa. Explore Mais na Aqua Joias Descubra mais opções em nossa coleção de pulseiras femininas. Na Aqua Joias, unimos estilo e qualidade para proporcionar joias que complementam sua personalidade.', 79.99, 63.9, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvxs08i29gfq8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23892520664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48400902381', 'Pegador para Pizza Tramontina Utility em Aço Inox', 'Servir as melhores receitas de pizza vai ficar muito mais moderno e gostoso com o Pegador para Pizza Tramontina Utility em Aço Inox. Produzido totalmente em aço inox com acabamento brilho, leva mais praticidade e bom gosto na hora de servir. Fácil de lavar, pode ser levado à máquina de lavar louças diariamente. Um item para levar beleza e elegância à sua mesa! Em aço inoxidável, altamente durável, mantém as características originais, preservando a beleza, a higiene e a durabilidade do material. Acabamento em brilho. Pode ser lavado, diariamente, na máquina de lavar louças. 90 dias de garantia legal para vícios ou defeitos de fabricação. Use apenas sabão ou detergente e uma esponja macia. Outros tipos de produto como palha de aço, poderão riscar ou prejudicar o brilho da peça. Enxágue cada item a fim de remover totalmente os resíduos dos produtos de limpeza, que, por serem abrasivos, podem danificar o inox. Sempre que possível, use água quente, pois renova o brilho da peça. Após a lavagem, enxugue imediatamente a peça, caso contrário, as substâncias químicas da água (cloro) poderão causar manchas. Evite atrito entre as peças durante o processo de lavagem e no armazenamento, para mantê-la sem riscos. Evite o contato do produto com superfícies quentes, pois elas provocam a descoloração do material. Não guarde a peça em locais úmidos. A umidade também provoca manchas.', 59.99, 39.99, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgp5y9xdkk5c46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333246733%2F48400902381', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
