INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897972379', 'Cartões de Estímulos de Alto Contraste Montessori Baby Cards To Go 0 - 3 Meses Cooper Fun - 00159', 'Esse é um daqueles jogos que além de garantir a diversão garante também o aprendizado! O jogo de Contraste Pequeno interativo Express é super divertido e colorido, são 12 cartas todas com uma linda ilustração.Objetivo do jogo além de promover diversão, e desenvolver o raciocínio lógico das crianças e sua percepção visual, o conhecimento das cores e formas. Nesta etapa, a criança enxerga tudo em Preto e Branco. No 1º mês, apenas vultos. Nos 2º e 3º meses, a definição vai tomando forma. Um jogo de ótima qualidade e todas as suas peças são fáceis de destacar, garantindo muita diversão. Você pode jogar memória, você pode usar as cartas para contar uma história, ou você pode fazer as 2 coisas ao mesmo tempo! Com 1 ano, as ilustrações oferecem texturas, traços mais detalhados e uma expressão ou onomatopéia. Os cartões podem ser usados como roteiro para uma história. Desenvolve: - Percepção Visual - Percepção Auditiva - Conhecimento Específico - Atenção e Foco - Coordenação Motora A partir de 1 ano de idade, a criança já está com a visão muito próxima da nossa, percebendo detalhes como profundidade e associação dos sons. DICAS - Não treine mais do que 5 vezes ao dia - Treine até 15 minutos por vez - Faça em uma hora em que o bebê está bem desperto Especificações: - Idade:0-3 meses - Dimensão: 3,0 x 8,0 x 8,0 cm - Peso:0.05kg Características: - Marca:COOPER FUN - Modelo:00159 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01 Jogo de Contraste - 12 cartas 24 imagens (Todas Ilustradas) jogo educativo - baby cards - cooper fun - contrastes', 20.98, 20.98, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-m1iq433htsfx92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F22897972379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
