INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997348207', 'Livro A terra dos meninos pelados', 'Raimundo era careca e tinha um olho azul e outro preto. Por essa razão, era considerado estranho pelas pessoa se quase ninguém falava com ele. Seus vizinhos o apelidaram de Raimundo Pelado. Por não ter amigos, começa a falar sozinho, cria um país imaginário chamado Tatipirun, onde as pessoas têm um olho preto e outro azul, onde não existem cabelos em suas cabeças, e onde as plantas e animais falam. Ali, ele descobre, ninguém é ofendido ,nem ferido. Todos são iguais! Com texto primoroso, A terra dos meninos pelados é um livro indicado para leitores de todas as idades._x000D_ _x000D_ Editora: Principis_x000D_ Edição: 1, 2024_x000D_ Autor: Graciliano Ramos_x000D_ Idioma: Português_x000D_ Páginas: 96_x000D_ Dimensões: L 15.50 x A 22.60 x E 0.76_x000D_ ISBN: 9786550971458_x000D_ Coleção: Clássicos da literatura brasileira_x000D_ Linha Editorial: Principis - Clássicos da literatura_x000D_ Faixa Etária: + 12 anos_x000D_ Assuntos (tags): Brasil, Literatura brasileira , Convivência, Imaginação, Criança, Amizade, Solidão, Diversidade_x000D_ BISAC: Literatura Juvenil / Fantasia_x000D_ Linha de Produto: Principis_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação brilho_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Adult''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rcd7-lrxgkvl1qoie53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22997348207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
