INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204145363', 'Controlador de Carga Solar Aitek SIGMA-CC3030 30A – 12V/24V Auto, USB 5V/2A', 'Controlador de Carga Solar Aitek SIGMA-CC3030 – Gerencie Sua Energia Solar com Eficiência! 🔋 Otimize o Uso da Energia Solar na Sua Casa ou ViagemO Controlador de Carga Solar Aitek SIGMA-CC3030 é a solução inteligente para manter suas baterias carregadas de forma segura e eficiente. Ideal para sistemas solares residenciais, campings, vans e aplicações off-grid, ele garante que você aproveite ao máximo a energia captada pelos painéis solares. ✨ Funcionalidades Principais: ⚡ Corrente de Carga: 12V / 24V automático (detecta a tensão da bateria automaticamente) 📊 Capacidade de Controle: 30A, para sistemas de média potência 🔌 Saída USB: 5V / 2A máxima, para carregar celulares, tablets e dispositivos portáteis 🖥️ Display Digital: Mostra tensão da bateria, corrente de carga e status do sistema em tempo real 🛡️ Proteções Inteligentes: Proteção contra sobrecarga, curto-circuito, inversão de polaridade e descarga excessiva ⚙️ Modos de Carga: MCU Inteligente, ajuste automático, temporizador e proteção contra raios 📏 Dimensões do Produto: Tamanho do controlador: 14 cm x 9 cm x 3 cm Peso do controlador: Aproximadamente 280g 🎯 Para Quem É Ideal?Perfeito para quem possui um sistema solar residencial, quer usar energia solar em viagens ou precisa de uma fonte de energia confiável em locais sem acesso à rede. Ideal para campistas, proprietários de vans e pequenos negócios que buscam autonomia energética.', 125.0, 38.89, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/br-11134207-81zte-mky3ltgid6gz91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1655406395%2F58204145363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
