INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794395402', 'Cinto De Segurança Retrátil Kadett / Ipanema - Dianteiro- Gt', 'Kit reposição para cinto de segurança para os bancos dianteiros Características -Material: Poliéster -Cor: Original preta -Chapa em Aço/Zinco Especificações Técnicas -Conteúdo da Embalagem -1 Kit completo para bancos Dianteiros (2 retráteis 3 pontos e 2 Fechos / lado direiro e lado esquerdo ) -Garantia 03 Meses Garantia do vendedor: 3 anos. Produto com foco em qualidade, resistência e durabilidade para uso automotivo. Benefícios do uso do cinto de segurança: Reduz o risco de ferimentos graves em acidentes de trânsito. Mantém o corpo estabilizado, evitando o impacto contra o volante ou painel. Garante segurança e conforto durante a condução. Atende às normas de segurança veicular exigidas por lei. Evita multas e pontuação na CNH por uso incorreto. Indicado para todos os veículos: carros, caminhonetes e utilitários. Fácil instalação e reposição, ideal para manutenção preventiva. Custo-benefício alto, sendo essencial para a segurança automotiva. Recomendações: - Instalar com apoio de profissional qualificado. - Garantia de 6 meses.', 247.13, 247.13, NULL, 'Fashion Accessories > Additional Accessories > Cufflinks', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-mdjl1s1x7xmkb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1604698269%2F23794395402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
