INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997178166', 'Cama Box Baú Casal Colchão de Espuma D33 Semi Ortopédico Extra Firme Orthotec Marrom 138x188x71cm', 'Melhore suas noites de sono com o lindo Colchão Orthotec. A Espuma D33 garante excelente durabilidade e conforto ao produto, por conta de sua composição. Seu tecido é 100% sintético. Com o Colchão Orthotec você está dormindo nas nuvens. MODELO: Cama Box de Casal 1,38m Orthotec MARCA: Inducol MARCA DO BOX: Prince COR: Marrom MEDIDAS: A: 71 cm L: 138 cm P: 188 cm MATERIAL DO COLCHÃO: Composto por Espuma de alta resiliência D33 e EPS em sua base que proporciona uma maior estruturação e firmeza do produto. TECIDO DO COLCHÃO: Tampo com estampa floral clean REVESTIMENTO SUPERIOR: Malha de Poliéster REVESTIMENTO LATERAL: Poliéster REVESTIMENTO INFERIOR: Poliéster ESPUMA: D33 TECIDO DO BOX: Suede MATERIAL DO BOX: 85% Eucalipto e 15% Pinus MATERIAL DOS PÉS: Plástico INF.: Altura do colchão de 30cm proporciona um design moderno e poder ser utilizado em camas tradicionais ou cama box. DIFERENCIAL: Conjunto acompanha Box com Baú PESO: 27kg PESO SUPORTADO: 130kg INSTRUÇÕES / CUIDADOS: Utilizar em local seco com passagem de ar, não dobrar, fazer giro quinzenalmente no sentido pés/cabeceira. Produto utilizável apenas de um lado. ITENS INCLUSOS: 1 Colchão de 1,38m e 1 Box com Baú de 1,38m OBS.: Cabeceira não inclusa GARANTIA: 12 Meses pelo Fabricante A Esplanada Móveis se responsabiliza pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, se a portaria do condomínio permitir, as entregas são efetuadas no piso térreo e é de responsabilidade do cliente a locomoção da mercadoria até seu apartamento ou casa. Confira as dimensões do produto e certifique-se de que estão adequadas aos elevadores, portas e corredores do local da entrega. Não fazemos a montagem, desmontagem do produto e/ou portas e janelas, transporte pela escada ou içamento pelo lado de fora do prédio. Não está incluso no serviço de entrega o deslocamento até o interior do apartamento, com ou sem elevador, ou deslocamento em locais de difícil acesso como escadarias. Caso o cliente necessite de entrega dentro das dificuldades mencionadas, deverá entrar em contato para análise e cotação do valor do serviço. Certifique-se de tudo antes de finalizar a compra, evitando assim futuros desagrados ou imprevistos com a entrega.', 1599.0, 1599.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rbl8-loocky6ylzwt9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097902002%2F23997178166', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598989762', 'Painel Ripado em EVA Flexível Autocolante Parede, Decoração e Fácil Instalação Meu Rodapé', '✨ Transforme seu ambiente sem obra e sem sujeira! O Painel Ripado Laminado EVA Autocolante Meu Rodapé é ideal para renovar paredes, cabeceiras, salas, quartos, corredores, escritórios e móveis de forma prática e moderna. Com visual ripado amadeirado e acabamento sofisticado, ajuda a deixar o ambiente mais elegante e aconchegante sem precisar de reforma. ✅ Fácil de aplicar ✅ Autocolante ✅ Material leve e flexível ✅ Instalação rápida e limpa ✅ Visual moderno amadeirado ✅ Fácil limpeza e manutenção 📌 Ideal para aplicação em: • Sala • Quarto • Cabeceira • Painel de TV • Escritório • Corredor • Hall de entrada • Apartamentos e comércios 📦 Características: • Material: EVA Laminado • Acabamento ripado amadeirado • Produto flexível e leve • Aplicação prática • Uso interno ⚠️ Importante: Recomendamos aplicação em superfícies lisas, limpas e secas. Em paredes com textura, tinta fosca ou superfícies porosas, pode ser necessário o uso de cola auxiliar para melhor adaptação da fixação. Meu Rodapé - decoração prática, moderna e sem obra 💚', 74.99, 67.5, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mieuzx3v3wuae0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401374403%2F19598989762', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
