INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251750681', 'Creme de Silicone Tutano Vegetal 150gr | Proteção, Hidratação e Resistência para Cabelos Frágeis', 'Fortaleça e proteja seus cabelos no dia a dia com o Creme de Silicone Tutano Vegetal! Indicado para cabelos frágeis e ressecados, esse creme sem enxágue desembaraça, hidrata e forma uma película protetora nos fios contra sol, vento, cloro, poluição e poeira. Sua fórmula vegetalizada é rica em aminoácidos, sais minerais e vitaminas, que aumentam a resistência da fibra capilar e reduzem pontas duplas. Benefícios: • Restaura e fortalece os fios frágeis e quebradiços • Desembaraça e proporciona hidratação de longa duração • Protege contra agressões externas como poluição, vento, sol e cloro • Nutrição intensa com ativos vegetais • Com proteção térmica e solar • Fórmula vegana, sem parabenos e sem corantes • Direção olfativa: floral frutal Fórmula segura e eficiente: • pH 3.5 – ideal para manter o equilíbrio dos fios • Sem enxágue – praticidade e proteção prolongada • Tutano vegetal e vitaminas – mais força, brilho e resistência Modo de uso: Com os cabelos limpos e úmidos, aplique uma quantidade suficiente do Creme de Silicone Tutano Vegetal na palma das mãos. Espalhe por toda a extensão dos fios e finalize como desejar. Sem enxágue. Potencialize os resultados utilizando toda a linha Tutano Vegetal.', 59.9, 59.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-822zm-mi34lmq4h53797', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F58251750681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
