INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54606700177', 'Kit Transformação e Missão | O Homem do Céu Irmão Yun e Paul Hattaway + Back to Jerusalem Eugene Bach', 'Kit Transformação e Missão | O Homem do Céu Irmão Yun e Paul Hattaway + Back to Jerusalem Eugene Bach Este kit reúne dois livros que impactam profundamente a vida espiritual do leitor: O Homem do Céu, que revela uma história real de fé, coragem e esperança em meio à perseguição, incentivando a gratidão e a oração; e Back to Jerusalem, que desafia você a identificar-se com a igreja sofredora, cultivar uma fé missionária e viver uma vida entregue ao serviço de Deus para os povos ainda sem o Evangelho. O Homem do Céu – Irmão Yun e Paul Hattaway A história real de um cristão chinês que enfrentou perseguição com fé inabalável. Uma narrativa emocionante, repleta de coragem, esperança e milagres, que desafia o leitor a valorizar a liberdade religiosa, aprofundar sua vida de oração e se comprometer com o serviço a Deus. Conheça a realidade da Igreja Perseguida na China e permita que esta jornada seja um divisor de águas em sua espiritualidade. Back to Jerusalem – Eugene Bach Mais que um livro, um treinamento espiritual que coloca o foco nos povos não alcançados. Com 30 histórias reais de missionários chineses, esta obra não oferece conforto, mas chama você à ação – identificando-se com a Igreja sofredora e aprendendo com seus sacrifícios. Prepare-se para ser desafiado a abandonar uma fé superficial e abraçar um compromisso radical com a Grande Comissão. Desafie Sua Fé e Amplie Seu Impacto Missionário Este kit exclusivo reúne duas obras inspiradoras que transformam vidas e despertam o chamado missionário: Por que este kit é essencial? Fortalece sua fé com testemunhos reais de superação. Desperta visão missionária, inspirando você a interceder e agir. Ideal para líderes, grupos de estudo e quem busca profundidade espiritual. Transforme sua jornada cristã. Adquira agora e seja parte do mover de Deus no mundo! Título:Kit Transformação e Missão | O Homem do Céu Irmão Yun e Paul Hattaway + Back to Jerusalem Eugene BachAno de Edição:2025 Páginas:480 Dimensões:21 x 14 x 3 cm Peso:0.510 kg Editora:Betânia', 65.9, 65.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-820lp-mldilcnusoav37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F54606700177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47409777014', 'Bíblia Sagrada Leia e Anote Pássaros | NVI | Letra Grande | Capa Luxo Caramelo', 'Bíblia Sagrada Leia e Anote Pássaros | NVI | Letra Grande | Capa Luxo Caramelo Esta edição da Bíblia Sagrada apresenta a Nova Versão Internacional (NVI), uma tradução desenvolvida por especialistas brasileiros e estrangeiros diretamente das línguas originais. Com capa luxo em acabamento baixo relevo e design exclusivo da editora Berith, oferece 1416 páginas em letra grande para facilitar a leitura e o estudo. A NVI foi desenvolvida ao longo de quase uma década por uma comissão técnica de estudiosos experientes, com foco na equivalência funcional que equilibra fidelidade aos textos originais com clareza na linguagem contemporânea. As folhas amareladas proporcionam menor cansaço visual e melhor opacidade, tornando a leitura mais confortável durante estudos prolongados. Tradução direta das línguas originais por comissão de especialistasLetra grande e folhas amareladas para reduzir fadiga ocularLinguagem contemporânea que supera barreiras de versões mais antigasCapa luxo caramelo com acabamento em baixo relevoDesign exclusivo desenvolvido pela equipe editorial BerithUma edição pensada para quem busca uma tradução precisa e acessível, combinando rigor acadêmico com facilidade de compreensão, ideal para leitura diária e estudos bíblicos aprofundados. Especificações da Bíblia Sagrada Leia e Anote Pássaros | NVI | Letra Grande | Capa Luxo Caramelo: Bíblia Sagrada Leia e Anote Pássaros | NVI | Letra Grande | Capa Luxo Caramelo Linguagem: NVI - Nova Versão Internacional Capa: Capa Luxo Acabamento: Baixo Relevo Borda: Dourada Índice: Não Harpa: Não Palavras de Jesus em destaque: Sim Letra: Grande Fitilho: Sim Páginas: 1416 Dimensões: 19,5 x 17,5 x 4 cm Peso: 963 g ISBN: 9786583509772 Idioma: Português Editora: Berith Família: Bíblias Indicação: Espaço para Anotações, Estudo, Família, Mães, Leitura Diária, Jovens e Adolescentes, Para levar com você, Mulheres', 159.9, 159.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-820m7-mnoq7g589urq29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F47409777014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
