INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52155026290', '52 Reflexões Como desenvolver a autoconfiança | Dale Carnegie', '52 Reflexões Como desenvolver a autoconfiança | Dale Carnegie A CONFIANÇA NÃO NASCE DE GRANDES FEITOS, MAS DE PEQUENAS AÇÕES REPETIDAS TODOS OS DIAS. Inspirado nas ideias de Dale Carnegie, este livro oferece 52 reflexões semanais para fortalecer a autoestima, vencer o medo e transformar insegurança em coragem. Cada texto é um passo rumo à liberdade interior, um convite para agir, mesmo com medo, e descobrir que a confiança é consequência da prática. Com uma linguagem clara e envolvente, Sam Buttler traduz o espírito de Carnegie para o leitor contemporâneo, mostrando que a autoconfiança é uma habilidade que se aprende e se renova com o tempo. Comece hoje. Dê o primeiro passo. A coragem virá logo depois. Autor: Dale Carnegie Editora: Principis Acabamento: Capa comum Dimensões: 16x23 Número de páginas: 96', 11.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8261h-mjrbjyzlq0w1d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F52155026290', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
