INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19999453243', 'Kit Perfume Attracione+Hidratante Shine Seduction+LipIntense', '✅PRODUTO 100% ORIGINAL Kit Magnetismo Com uma fragrância afrodisíaca, com um mix de feromônios que amplificam a exalação de estrogênio e estratetraenol, a fórmula perfeita para aumentar seu poder de atração e desejo e aguçar os sentidos masculinos. Com um simples spray nas zonas quentes do seu corpo (pescoço, pulsos e seios) você já estará preparadissima! Efeitos duram de 04-06 horas. 🔥 Desperte desejo e olhares 🔗 Estimula conexão emocional com sexo oposto 😌 Efeito anti-stress e anti-ansiedade Alto nível de feromônios que vão aumentar o seu poder de sedução e chamar atenção do sexo oposto. Com 6 horas de fixação, você sentirá a sua pele iluminada, hidratada e atraente. ✨ Efeito Glow na pele. 🧴 Hidratação profunda (Vitamina E) 🔥 Feromônios para seduzir o sexo oposto ✅ Simples e Fácil de usar. Com feromônios femininos, ácido hialurônico e vitamina E… feitos para aumentar o seu poder de atração através do beijo… Com 6 horas de pump labial, você se sentirá sensual e irresistível ao usar o Lip Intense 👄 Efeito Instantâneo que Aumenta os Lábios 🔥 Feromônios que Deixam seu beijo mais quente 💄 Simples e Fácil de usar como um batom 💦 Muita hidratação pela vitamina E', 177.0, 127.0, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9g8de45cx15bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1266325318%2F19999453243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
