INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798212443', 'Soprador Térmico 2000W Vonder Profissional Ar Quente Com Maleta Acessórios 2 Velocidades Uso Geral', 'Soprador Térmico STV 200N + Caixa Plástica VD 6002 – Vonder O kit é ideal para aplicações profissionais que exigem aquecimento controlado com praticidade no transporte. Indicado para moldagem de plásticos, remoção de tintas, encolhimento de materiais e uso em encanamento e carpintaria, oferece potência de até 2.000W e acompanha maleta resistente para organização e mobilidade no dia a dia. Disponível nas versões 127V ou 220V, permitindo escolher a voltagem correta para sua necessidade. 📦 Itens Inclusos 📌 1 Soprador térmico STV 200N 📌 1 Bocal plano 📌 1 Bocal de desvio 📌 1 Bocal de ponta 📌 1 Bocal de deflexão 📌 1 Caixa plástica VD 6002 ⚙️ Especificações Técnicas 🔌 Potência máxima: 2.000 W 🌡️ Estágios de temperatura: 50°C / 350°C / 550°C 💨 Fluxo de ar: 300 a 500 L/min 🔄 Frequência: 60 Hz 🧱 Material da caixa: Polipropileno 🏋️ Capacidade da caixa: 12 kgf ⚡ Voltagem: 127V ou 220V (não é bivolt, escolha no momento da compra) 🚀 Benefícios do Produto ✔️ Versatilidade para diversas aplicações profissionais ✔️ Controle de temperatura em 3 níveis distintos ✔️ Acompanha bocais para diferentes tipos de uso ✔️ Caixa plástica resistente para organização e transporte seguro 🚚 Envio e Garantia 📦 Produto original com envio rápido ⏱️ Postagem em até 24 horas 🔒 Compra segura e com garantia de procedência', 259.9, 249.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lb-mlxr1kqfn2me21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1363787561%2F22798212443', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098231353', 'Soprador Térmico 1500W DWT Com Maleta Plastica Para Transporte', 'Soprador Térmico 1500W DWT Com Maleta Plastica Para Transporte O Kit Soprador Térmico STD 150N 1500W + Maleta combina eficiência, segurança e organização, sendo ideal para moldagem de plásticos, remoção de tintas, artesanato e aplicação de películas. Com motor de dupla isolação e design tipo pistola, proporciona melhor ergonomia e conforto no uso. A maleta resistente facilita o transporte e armazenamento, mantendo o equipamento e seus acessórios sempre organizados. Indicado para encanadores, marceneiros, carpinteiros, pintores e fábricas de móveis, é um item essencial para diversos trabalhos profissionais. Itens Inclusos: 1 Soprador térmico STD 150N 1 Bocal plano 1 Bocal de desvio 1 Bocal de ponta 1 Bocal de deflexão 1 Maleta resistente para transporte e armazenamento Detalhes Técnicos – Soprador Térmico: Potência máxima: 1.500 W Número de estágios: 2 Temperatura: >1º estágio: 300°C >2º estágio: 550°C Fluxo de ar: >1º estágio: 280 L/min >2º estágio: 480 L/min Potência por estágio: >1º estágio: 750 W >2º estágio: 1.500 W Frequência: 60 Hz Peso aproximado: 0,956 kg Certificação: Produto certificado conforme as normas IEC 60335-1 e IEC 60335-2-45, atendendo aos requisitos de segurança do Inmetro Detalhes Técnicos – Maleta: Material: Resistente e durável Ideal para armazenamento seguro e transporte prático Por que comprar conosco? ✔ Produto original e novo ✔ Envio rápido e seguro ✔ Atendimento especializado', 206.99, 206.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcde-m6fjc9a05pfw51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F22098231353', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
