INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499671468', 'Adubo Fertilizante Forth Flores NPK +9 Nutrientes 400 gr', 'DESCRIÇÃO Este adubo é para quem ama flores, pois além de deixar as plantas alimentadas e com as folhas verdes, ajuda e muuuito a proporcionar floradas com muito mais flores e por mais tempo. Vai ter tanta flor que vai ser primavera o ano inteiro. __________________________________________________________________________________________ MODO DE APLICAÇÃO - Plantas em vasos ou jardineiras 3L ou 15x15cm = ½ colher 8L ou 20x20cm = 1 colher 25L ou 30x30cm = 3 colheres 100L ou 50x50cm ou maior = 12 colheres A cada 15 dias espalhar o adubo sobre a terra e logo em seguida regar até diluir o adubo da superfície e a água começar a sair pelos furos do vaso. - Canteiros 50g por metro quadrado A cada 30 dias espalhar sobre a terra ao redor das plantas, em seguida regar até diluir o adubo da superfície. __________________________________________________________________________________________ ATENÇÃO Não jogar o adubo nas folhas. Para o plantio das flores utilize o FORTH Plantio. Evitar aplicar nas horas mais quentes e sempre regar logo em seguida aplicação. A adubação com FORTH Flores deve ser feita somente 30 dias após o plantio.', 29.99, 23.99, NULL, 'Home & Living > Gardening > Fertilizer', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7jwb8owin9mf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464043565%2F18499671468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
