INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297805004', 'Slide Campesí Flatform CP182', 'Produto marca Campesí. O Slide Campesí Flatform da coleção Primavera/Verão 2024 é a escolha perfeita para quem busca um calçado leve, prático e estiloso para o dia a dia e está disponível na cor . Com design moderno e detalhes sofisticados, ele se adapta a diversas ocasiões. Seu destaque fica por conta das tiras macias que envolvem os pés, que conta com peças com brilhos aplicadas, adicionando um toque de glamour e elegância, tornando-o ideal para produções mais elaboradas ou para um simples passeio. Já a sola flatform de 3 cm com detalhe metalizado, confere um ar moderno e sofisticado, além de proporcionar estabilidade e leveza ao caminhar. Peso: 0,627 kg Altura da sola: 3,00 cm', 149.9, 139.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rdyw-lzs45jvdlt9eec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F21297805004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
