INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12433509093', 'Creme para Pentear Seda Infantil Tiana Juntinhos Crespos Encantados com 300ml', '• Creme para Pentear Crespos Encantados • Hidratação e brilho para os cachinhos • O Creme de pentear Seda Juntinhos é feito com ingredientes que hidratam, dá brilho e red a tirar os nós, além de deixar-los com um cheirinho delicioso! • Seda não testa em animais. • * inclusão de pelo menos 39% de plástico reciclado. • * Nossa garrafa é feita com plástico reciclado ** e é 100% reciclável Novo Seda Juntinhos traz para a hora do banho as aventuras das personagens mais amadas pelas crianças. É diversão para os pequenos e cuidado com seus cabelos, já que o Creme de pentear Seda Juntinhos é feito com ingredientes que hidratam, dá brilho e elimin a tirar os nós, além de deixar-los com um cheirinho delicioso! Como usar: Após lavar o cabelo com o shampoo e condicionador, seque levemente com uma toalha e aplique o creme da metade até as pontas, usando os dedos para ajudar a desembaraçar e penteie para alinhar.', 23.94, 20.75, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/1bff650d2434ba90e020ccd1f29ab4cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F546513063%2F12433509093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
