INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498099811', 'Protetor Ouvido Speedo Soft Earplugs Natação Mergulho Auricular Profissional Anti Ruído Tampão', 'Protetor de Ouvido Speedo - Moulded Earplug CARACTERÍSTICAS: Moldado para perfeito encaixe nos ouvidos Extremo conforto Lavável e higiênico Exclusiva caixa protetora portátil Mínima interferência na audição Produto importado 100% em silicone Não deixe que a água em seus ouvidos impeça seu desempenho aquático! O Protetor de Ouvido Moulded Earplug da Speedo é feito de silicone, se encaixando perfeitamente ao formato do seu ouvido e oferecendo total conforto. Ideal para praticantes de natação e atividades aquáticas. Fabricado 100% em silicone, é lavável, higiênico e vem com uma exclusiva caixa protetora portátil para facilitar o transporte e armazenamento. Seu design proporciona mínima interferência na audição, garantindo que você mantenha o foco em sua performance. Além de ser altamente funcional, o Protetor de Ouvido Speedo é durável e de fácil manutenção. Após o uso, basta lavar e armazenar na caixa protetora, garantindo higiene e conservação do produto. CONTÉM: 1 Par de Protetores de Ouvido Moulded Earplug Speedo Confira outros modelos em "MAIS ANÚNCIOS DO VENDEDOR". Compras acima de R$ 79,00 podem ter frete grátis (consulte o CEP). Todos os pedidos acompanham nota fiscal emitida para o CPF/CNPJ informado.', 139.93, 66.41, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m83fsphpcff515', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F21498099811', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
