INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497682086', 'Porta Sanfonada de PVC 210x105cm Bariri Cerejeira Cerejeira', 'A porta sanfonada de PVC é o produto ideal para quem tem pouco espaço e precisa de uma solução na divisão de ambientes em apartamentos e casas pequenas. Por ser retrátil, esse modelo economiza espaço na sua abertura e fechamento, possibilitando a instalação em cozinhas, banheiros, lavanderias, despensas, salas de estar, escritórios, oficinas etc. Estilo: Funcional Peso (kg): 5.21 Elétrica: Não Garantia: 03 Meses Altura (cm): 210 Largura (cm): 105 Durabilidade: 10 Possui Grade: Não Possui Vidro: Não Tipo de Porta: Sanfonada Modelo da Porta: Sanfonada Acompanha Trinco: Sim Escala de Brilho: Fosco Imune à Corrosão: Não Lado de Abertura: Definido na instalação Textura da Porta: Lisa Acompanha Batedor: Não Acompanha Batente: Sim Acompanha Puxador: 1 Origem do Produto: Nacional Tipo de Dobradiça: Simples Ambiente Principal: Cozinha Largura do Batente: 2.5 Resistência à Água: Sim Acompanha Dobradiça: Não Acompanha Fechadura: Sim Acompanha Guarnição: Não Material do Batente: PVC Necessita Instalação: Sim Resistência à Maresia: Sim Tipo de Puxador da Porta: Externo Possui Isolamento Acústico: Não Acompanha Manual de Instalação: Sim Dimensão da Maquina da Fechadura: 2 Acabamento (Construção e Acabamento): Natural Material Principal Construção e Acabamento: PVC Marca: Bariri Tonalidade: Amarelo Cor: Cerejeira Cor do Produto: Cerejeira Itens Inclusos: 1 Estrutura Sanfonada, 1 Trilho, 2 Batentes, Kit Ferragens e Manual de Instruções Linha ou Coleção: Bariri EKO Premium Tipo de Certificado: NBR 14285 Tamanho do Produto: 210cm x 105cm', 287.54, 287.54, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-820nw-mo0bzxaj9lhdbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2F