INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897977475', 'Mangueira Respiro Óleo Vw Golf 1999 a 2010 - 1352772 - TR1613', 'Mangueira Respiro Óleo Vw Golf 1999 a 2010 1352772 TR1613 RESPIRO ÓLEO AO ANTICHAMA 1.6 16v Gasolina - (Ø:36mm/16mm/10mm) (Medida: 13cmx36cm) Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 58.46, 58.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbn3-lmt19ndm78pc1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19897977475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
