INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499600876', 'Estátua Sub-Zero - Mortal Kombat - MiniCo - Iron Studios', 'Quem é Sub-Zero? Na história da franquia, dois homens assumiram a identidade de Sub-Zero, o primeiro foi Bi-Han, grande rival de Scorpion e responsável por sua morte, o segundo é seu irmão Kuai Liang, ambos membros do Lin Kuei, um clã chinês de ninjas de Outworld. Durante o torneio, Bi-Han foi morto por um vingativo Scorpion ressuscitado como espectro ninja, e o ciclo de vingança se perpetua quando Kuai Liang que também domina o elemento frio, assume o lugar de seu irmão como um segundo Sub-Zero para eliminar Scorpion.', 249.99, 249.99, NULL, 'Hobbies & Collections > Collectible Items > Statues & Sculptures', 'https://cf.shopee.com.br/file/sg-11134201-7rff1-m3v4iwgrlidq2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1191775191%2F18499600876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
