INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097451153', 'Fone de ouvido Monster XKH01 Dobrável Sem Fio Bluetooth 5.3 Gamer Preto', 'Os Fones de Ouvido Sem Fio Bluetooth Monster XKH01 são a escolha perfeita para os amantes de música e gamers. Com a versão Bluetooth 5.3, oferecem uma transmissão de alta qualidade até uma distância de 10 metros. Sua interface de carregamento é Tipo-C, garantindo uma carga rápida e eficiente. A capacidade da bateria dos fones é de 400mAh, proporcionando horas de uso contínuo. Além disso, possuem um grau de impermeabilidade IPX5, tornando-os resistentes a respingos de água, ideais para levar à academia ou usar ao ar livre. Sua função sem fio permite manuseá-los à distância, tornando-os ainda mais confortáveis de usar. Aviso: Certifique-se de carregar completamente os fones de ouvido antes de usá-los pela primeira vez! Especificações do produto: Marca: Monster Modelo: XKH01 Versão do Bluetooth: 5.3 Tipo de produto: Fones de Ouvido Bluetooth Interface de carregamento: Tipo-C Distância de transmissão Bluetooth: 10M Capacidade da bateria do fone: 400mAh Grau de impermeabilidade: IPX5 Função de controle remoto: controle sem fio Conteúdo: 1 x Fones de Ouvido Bluetooth 1 x Cabo de áudio de 3,5 mm 1 x Cabo de carregamento USB 1 x Manual de instruções', 225.0, 121.03, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltv2b6qyb1ck9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F22097451153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20424618871', 'Começando Juntos | H. Norman Wright', 'Este livro apresenta 60 leituras devocionais com o objetivo de fortalecer o alicerce do relacionamento entre os casais. Uma ajuda tanto para os que estão na fase que antecede o casamento como para aqueles que iniciam a vida a dois. A partir das palavras de sabedoria extraídas do texto bíblico, o autor demonstra como desenvolver um relacionamento agradável e duradouro. 14X21CM 224 Páginas', 33.9, 29.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/5bbf8f7ce41c76995a3663644b0acc58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20424618871', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
