INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198782530', 'Declaração de Fé | Atualizada | Preta', 'Esta Declaração de Fé é um documento eclesiástico que organiza, de forma escrita e sistemática, as crenças e práticas das Assembleias de Deus no Brasil. Nesta nova edição, todo o conteúdo original foi preservado e alvo de revisão e reestruturação, agora sistematizados em 14 capítulos apresentados de forma sintética, abrangendo todas as principais doutrinas bíblicas. 21X14 CM 264 Páginas', 41.9, 40.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdw4-mcz4tlmqqqdc9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23198782530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20518414101', 'Tire suas Dúvidas sem Tirar a Roupa | Nelson Junior', 'Olho no olho, trocar telefones, conversas até a madrugada, tirar as dúvidas, pedido de namoro, conhecer as famílias, mãos dadas, carinhos, passeios no parque, filmes no cinema, briga, término, conversas, fazer as pazes, voltar, declarações, beijos, escolher esperar, viajar juntos, pedido de noivado, planejamento financeiro, beijos, abraços, lágrimas, sorrisos, brigas, fazer as pazes, juntar dinheiro, grande dia, festa, aplausos, presentes, noite de núpcias, tirar a roupa, primeira vez, segunda, terceira, lua de mel, volta para casa, contas para pagar, alegrias, arrumar a casa, comprar animal de estimação, ter o primeiro filho, cinco anos de casados, viagens, visitas na casa dos pais, segundo filho, parque com filhos, jantar romântico, trocar presentes, felicidade, para sempre. 16X23CM 224 Páginas', 33.9, 19.67, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/7140d797ed2f48b8986537c3859b081b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20518414101', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29288064209', 'Livro Cartonado Tristeza', 'Como você está se sentindo hoje?_x000D_ As crianças passam por uma variedade de sentimentos ao longo do dia, mas nem sempre conseguem identificá-los ou expressá-los com facilidade. Este livro lhes permite identificar e explorar o sentimento de tristeza – uma das seis principais emoções vivenciadas por elas – por meio de ilustrações calorosas e uma narrativa acolhedora._x000D_ Uma coleção perfeita para estimular a empatia, a resiliência e uma percepção positiva de si mesmo._x000D_ _x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Child s Play_x000D_ Ilustrador: Paula Bowles_x000D_ Idioma: Português_x000D_ Páginas: 12_x000D_ Dimensões: L 20.30 x A 20.30 x E 1.00_x000D_ ISBN: 9788538091639_x000D_ Coleção: Primeiras emoções/First feelings_x000D_ Linha Editorial: Ciranda Cultural - Ficção infantil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Emoções, Sentimentos, Tristeza_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Temas Sociais / Emoções e Sentimentos_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Verniz de máquina_x000D_ Material: Cartonado', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7ra0x-mbgp8ckmaoivb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F29288064209', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9612547915', 'Enriquecendo-se com a Bíblia - A.W. PINK', 'Você conhece mesmo a Bíblia? Você a ama e pratica seus ensinos? Este livro é um convite ao povo leitor para apreciar, entender e aplicar a mensagem da Bíblia em sua vida. Cada um dos 10 breves capítulos deste livro, trabalha um importante tema da fé cristã e, como um pequeno manual, ajuda o leitor a obter o maior proveito e compreensão possível de sua leitura bíblica, tornando-a rica, relevante e pratica. Mas essa ajuda é oferecida com uma palavra de alerta: Só o Espírito de Deus pode convencer o leitor da verdade, da justiça e do juízo. Só o Espírito pode aplicar as verdades da Escritura e torná-las mais desejáveis do que ouro e o destilar dos favos. Então o leitor sincero deverá pedir a Deus que mande seu Espírito soprar em seu coração e despertá-lo para provar e ver a bondade de Deus, na Bíblia. 200 páginas 12x19cm 16x12cm', 22.9, 19.1, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/cc0b4704f05a2268529f0e20113de2a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F9612547915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26591828925', 'Livro Brincadeiras no jardim', 'No jardim, as crianças aproveitam o encanto da primavera e transformam o lugar em um cenário de alegria e aventura. Junte-se a elas nessa brincadeira! Editora: Brijbasi Art Press Edição: 1, 2025 Autor: Ciranda Cultural Idioma: Português Páginas: 8 Dimensões: L 16.00 x A 16.00 x E 1.80 ISBN: 9786526115817 Coleção: Explorar e brincar Linha Editorial: Ciranda Cultural - Trade Faixa Etária: + 4 anos Assuntos (tags): Jardim, Brincadeira, Amizade, Descoberta, Diversão, Natureza BISAC: Literatura Infantil / Literatura Infantil / Ciência e Natureza Linha de Produto: Livro com abas Encadernação: Lombada quadrada Acabamento: Faca especial Material: Cartonado', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-82592-meueat69zdhg12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26591828925', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41429302470', 'Ração Guabi Natural Cães Adultos Porte Mini e Pequeno 1 kg Sabor Cordeiro e Aveia', 'Ração Guabi Natural Cães Adultos Porte Mini e Pequeno - Cordeiro e Aveia (1 kg) A embalagem de 1 kg da Guabi Natural para Cães Adultos de Porte Mini e Pequeno (Sabor Cordeiro e Aveia) é a escolha de quem busca nutrição Super Premium de base natural com a máxima garantia de frescor. Ideal para cães com paladar sensível ou tutores que preferem porções menores para assegurar que o alimento mantenha todas as suas propriedades, aromas e texturas ideais até a última refeição. Esta fórmula é uma combinação nobre de carne de cordeiro — conhecida por sua alta digestibilidade e baixo potencial alergênico — com a aveia, um grão funcional que auxilia na saúde intestinal e no controle dos níveis de açúcar no sangue. Tudo isso em grãos adaptados para o tamanho da boca dos pequenos, favorecendo a mastigação correta. Por que escolher a Guabi Natural Cordeiro e Aveia 1kg? Natural e Funcional: Livre de transgênicos, corantes e aromas artificiais. O foco é a pureza e a qualidade nutricional, respeitando a biologia do seu cão. Grãos Mini: Tamanho e textura desenvolvidos especialmente para a mandíbula dos cães de porte mini e pequeno, facilitando a ingestão e auxiliando no controle do tártaro. Alta Digestibilidade: A carne de cordeiro é uma fonte de proteína leve e muito bem tolerada, tornando esta ração excelente para cães com estômagos sensíveis. Saúde Intestinal: A presença de aveia e prebióticos favorece um trânsito intestinal regular, resultando em fezes com volume e odor reduzidos. Pelagem Radiante: Rica em Ômegas 3 e 6, garantindo pelos mais macios, brilho intenso e uma pele protegida e resistente. Frescor Garantido: O formato de 1 kg é perfeito para garantir que o seu cão aproveite um alimento sempre fresco, mantendo o paladar preservado até o fim do pacote. Clique no botão de compra e leve para casa a qualidade da Guabi Natural em um formato pensado para o prazer e a saúde do seu pequeno companheiro, oferecendo uma dieta limpa, nutritiva e irresistível!', 76.97, 59.35, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-82609-mlw663wgoz5v78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F41429302470', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52956256586', 'Livro de Colorir Com 4 Canetinhas | Comfy Dinosaurs', 'Inspirado no sucesso dos livros de colorir PARA RELAXAR no TikTok, este livro é ideal para quem busca transformar momentos simples em uma experiência verdadeiramente calmante. Explore sua criatividade com lápis de cor ou marcadores, mergulhando em momentos de tranquilidade. Perfeito para todas as idades, este livro oferece uma maneira leve e prazerosa de aliviar o estresse e de se desconectar da correria diária. Livre para todos os públicos, este livro é perfeito para aliviar o estresse e se desconectar da correria do dia a dia e ainda acompanha 4 Canetinhas Marcadoras (cores variadas). 48 Páginas 24x24 cm', 19.9, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262l-mkucwftz3h1d22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F52956256586', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49205430290', 'Chinelo Aramis Trop Leave Masculino Casual Confortável Leve Macio Slide', 'Chinelo Masculino Trop Leave Aramis Modelo: ARM1122 O Chinelo Masculino Trop Leave Aramis é a escolha ideal para quem busca conforto, leveza e estilo descontraído para os momentos de lazer. Com visual inspirado no lifestyle tropical, o modelo traz personalidade sem abrir mão da praticidade, sendo perfeito para uso diário, viagens, praia ou descanso. Sua palmilha macia proporciona uma pisada confortável desde o primeiro uso, enquanto o solado resistente garante estabilidade e segurança ao caminhar. As tiras anatômicas oferecem ajuste firme aos pés, assegurando conforto mesmo durante períodos prolongados de uso. Um chinelo versátil que une bem-estar e a sofisticação casual da Aramis. Benefícios: - Conforto imediato. - Design tropical moderno. - Leveza para uso diário. - Ajuste confortável aos pés. - Estilo casual versátil. - Qualidade e padrão Aramis. Características: - Produto: Chinelo. - Marca: Aramis. - Modelo: Trop Leave. - Código do modelo: ARM1122. - Gênero: Masculino. - Estilo: Casual / Verão / Lazer. - Indicação de uso: Dia a dia, lazer, praia e descanso. - Fechamento: Calce fácil (slip-on). - Origem: Nacional. O Chinelo Masculino Trop Leave Aramis pode ser encontrado aqui na Usee Brasil Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 99.99, 64.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-820lu-mo411fpgqc5d62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F49205430290', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299153307', 'Armário De Cozinha Nala Aéreo Geladeira 1 Porta Mobilihouse Cinamomo/cinza Acetinado', 'Armário De Cozinha Nala Aéreo Geladeira 1 Porta Mobilihouse Cinamomo/cinza Acetinado O Armario de Cozinha Aereo Geladeira 1 Porta Nala e a escolha perfeita para quem busca otimizar o espaco na cozinha. Com uma porta, ele oferece praticidade e organizacao para armazenar utensilios e mantimentos, aproveitando o espaco acima da geladeira de maneira eficiente. Seu design moderno e acabamento elegante se adapta a diferentes estilos de decoracao, ajudando a manter sua cozinha mais organizada e funcional. Caracteristicas: Marca: Mobilihouse Modelo: Nala Portas: 1 Ambiente: Cozinha Estilo: Moderno Dimensoes: Altura: 30 cm Largura: 75 cm Profundidade: 27 cm Peso: 9 kg Garantia do Fabricante: 3 meses', 108.15, 108.15, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-821dt-mgo3zlc00cnca1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23299153307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6244961137', 'Vnox Corrente Elo Miami Cubano', 'Descrição do Produto: Material: Corrente de Link de aço inoxidável (sem desbotamento, sem alergia) Condição de 100% novo Cor dourada:Cor dourada Largura da largura: 3,6 mm/5mm/7 mm Medida da Medida: 45cm/50cm/55cm/60cm/70cm', 23.91, 20.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/950c09b12fa3179a38a5a8581a106ee4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F239158067%2F6244961137', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12874535829', 'Vozes Femininas nos Avivamentos | Rute Salviano Almeida', 'Existem muitos avivalistas conhecidos, porém, a maioria são homens, e as mulheres? onde estão? Muitas mulheres já fizeram parte de avivamentos históricos, mas não são tão conhecidas quanto os homens. Nesse livro, Rute Salviano Almeida contará a história de diversas mulheres que fizeram a diferença no mundo, histórias que com certeza servirão de inspiração para você. 16x23cm 368 Páginas', 67.9, 67.9, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/2a74795358e9c8a9a216fbb01ac033d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F12874535829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697760072', 'Kit - 4 X Cadeiras Iron Tolix - Preto - Semibrilho', 'Kit - 4 X Cadeiras Iron Tolix - Preto - Semibrilho Cadeira Fixa Design Tolix Metal Pelegrin PEL-1518 Preta Conhecida popularmente como ?Cadeira Francesinha?, tem grande influência no mercado europeu devido ao seu elegante design retrô. O modelo clássico idealizado pelo francês Xavier Pauchard nos anos 20 foi resultado de seu experimento pioneiro da fabricação de móveis com metal galvanizado. A cadeira com formas simples, porém funcionais fez tanto sucesso que se tornou muito popular em fábricas, escritórios, restaurantes, bem como nos cafés, bares e parques públicos da época. Hoje conhecida como ?Cadeira Tolix?, é um ícone da estética industrial, podendo ser utilizada em qualquer ambiente trazendo elegância e personalidade. Com estrutura em aço de carbono e acabamento em pintura eletrostática, pode ser utilizada em ambientes externos. Projetada com alguns furos em seu assento com a finalidade de não acumular água, facilitando sua limpeza e manutenção. A ?Cadeira Tolix? é clássica, com design vintage e pode ser combinada com outros modelos de cadeiras. Disponível em variedade de cores, permitindo um ambiente mais descontraído. Instruções De Limpeza Aplique um sabão em uma esponja úmida e limpe toda a superfície da banqueta, e logo em seguida, limpe o sabão com um pano branco úmido. Assento: Aço com Pintura Epóxi Base: Aço com Pintura Epóxi Profundidade: 47 cm Largura: 45 cm Altura Total: 86 cm Altura do Chão Até o Assento: 45 cm Profundidade Interna do Assento: 36 cm Largura Interna do Assento: 45 cm Peso Máx. Recomendado: 120 kgs Peso unitário: 6 kgs', 952.0, 952.0, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-lzrqdtohcgo23b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22697760072', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793587172', 'Combo Salgadinho Batata Frita Pringles® Creme E Cebola 109G E Cheez-It® Snap''D Nacho Explosion 45G', 'Os Salgadinhos de Batata Pringles® vêm em sua lata icônica que os mantém empilhados e crocantes. Aproveite este snack em seu sabor Original ou com os irresistíveis sabores Queijo, Creme e Cebola e Churrasco com os amigos, em uma festa ou como um aperitivo. Graças ao seu sabor delicioso e forma fácil de empilhar, cada uma das Pringles® inspira boas lembranças e diversão. Este snack é uma deliciosa opção para levar para todos os lugares. A qualidade de Pringles® permite que você descubra uma nova experiência de sabor. As latas icônicas de Pringles® preservam o sabor e a textura crocante do produto. Ao abrir uma lata, você pode relaxar e saborear cada mordida. Satisfaça seu desejo por um aperitivo com os Salgadinhos de Batata Pringles® com o sabor irresistível Original. A embalagem portátil e conveniente permite que esse snack te acompanhe em vários momentos. Seja na pausa do trabalho, jogando videogame, no lanche da tarde ou na hora de assistir ao jogo; essas são apenas algumas das ocasiões em que Pringles® está presente. Você também pode levar Pringles® em uma caminhada pela natureza, um churrasco ou comê-las enquanto assiste um filme, série ou estuda em silêncio. As latas são portáteis para que a família durante sua viagem, possa comer os deliciosos Salgadinhos de Batata Pringles® sem se perguntar quanto tempo leva para chegar ao seu destino. Pringles® pode ser apreciada a qualquer momento e pode ser compartilhada para multiplicar os diversos momentos agradáveis. Porque afinal, tudo cai melhor com Pringles®. Você, com certeza, já se pegou desejando aquele salgadinho quando bateu a fome? E pensando nisso apresentamos o Snack de Queijo Cheez-It®, uma opção deliciosamente crocante para alegrar o seu dia. Sua embalagem é prática e fácil de carregar, possibilitando que você leve o Snack de Queijo Cheez-It® da Kellogg''s® para qualquer lugar, seja na sua bolsa para o trabalho ou mesmo na mochila de viagem, ele é bem-vindo a qualquer hora. O salgadinho Batata Frita Pringles®, vem em sua icônica lata para proporcionar uma experiência incomparável. É O salgadinho que foi feito para você! Com suas batatas que encaixam perfeitamente na sua língua, e que te surpreende a cada mordida com uma crocância incomparável e um sabor único. Pringles® é autêntica, divertida e surpreendente. Suas batatas perfeitamente empilhadas, te permitem levá-las para todos os lugares. Em meio à correria do dia a dia, ele é uma pausa merecida, um momento de relaxamento que revigora e renova suas energias. Mas também ideal para dividir com a galera, e tornar todos os encontros mais especiais. O sabor Original tem uma crocância surpreendente e um sabor que fica na memória! Desfrute deste salgadinho na versão Original ou explore os sabores Queijo, Creme e Cebola, Churrasco e Cheddar e Bacon. Este snack é perfeito para qualquer ocasião.Dê um pop na sua mente com Pringles®!', 17.96, 17.96, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-824h7-mpmm2p178bnv95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638330698%2F23793587172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897312885', 'Kit Paleta de Sombras Power Glow Océane Edition + Pincel para Sombra Ocn13 (2 Produtos)', 'O Kit Paleta de Sombras Power Glow Océane Edition + Pincel para Sombra Ocn13 É Perfeito para Garantir Um Olhar Poderoso e Marcante em Qualquer Lugar! a Paleta de Sombras Power Glow Possui 4 Tons Lindos com Muita Pigmentação e Fixação. o Pincel de Maquiagem para Detalhe Chanfrado, Flat Angled Brush Ocn13, É Ideal para Aplicar Corretivo e Sombras. Suas Cerdas Macias Garantem Um Acabamento Perfeito. O Kit Paleta de Sombras Power Glow Océane Edition + Pincel para Sombra Ocn13 Contém: - 1 Pincel para Detalhe Chanfrado - Flat Angled Brush Ocn13 - 1 Paleta de Sombras – 4 Eyeshadow Palette Power Glow Océane Edition 4,5g 4 Palette Power Glow Océane Edition: Uma Paleta de Sombras com Cores Que Iluminam o Olhar É Um Item Indispensável No Nécessaire de Toda Mulher. Seu Formato Compacto É Ideal para Ser Levado com Você em Qualquer Cantinho, Na Bolsa, Na Mochila ou Na Mala de Viagem. Por Ser Pequena, Resistente, e Conter Um Espelho Embutido, Ela Também É Uma Ótima Aliada para Aqueles Retoques de Última Hora No Visual. Conheça As Cores da Paleta de Sombras Power Glow: Pearl Vanilla: O Charme e a Sutileza da Baunilha em Um Tom Cintilante Que É Perfeito para Criar Um Olhar Iluminado ou Bem Marcado. Eletric Pink: Uma Tonalidade Solar e Deslumbrante, Formulada com Pigmento Prensado. Um Furta-Cor Que Combina Bem com Os Tons Terrosos Que Acompanham a Paleta. Terracota: Para Uma Make Quente, Suave e Marcante, Essa Tonalidade Matte Que Mistura Tons de Laranja e Marrom Traz Vida e Requinte para a Make. Peach: Um Tom de Nude em Acabamento Matte, Indispensável em Qualquer Nécessaire para Garantir Uma Make Discreta, Natural e Iluminada. Pincel para Sombra Ocn13: Pincel de Detalhamento, o Flat Angled Brush Ocn13 É Ideal para Corretivos e Sombras Cremosas. O Ocn13 É Perfeito para Produzir Makes com Olhar Marcante ou Corrigir Pequenos Pontos Na Sua Pele. o Pincel de Detalhamento Océane, Possui Cerdas Longas e Chanfradas, Próprias para Alcançar Os Cantinhos e Região Abaixo Dos Olhos. Você Pode Usar o Pincel de Detalhamento Océane com Produtos Líquidos e Cremosos. o Pincel de Maquiagem, Deposita o Produto Suavemente, o Que Dá Um Toque Natural para a Maquiagem. Além Disso, Ele É Feito com Cerdas Sintéticas Macias, Que Não Incomodam Quando em Contato com o Rosto.', 149.9, 139.9, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mqhpsy951edpea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F21897312885', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492036157', 'Kit Creme Facial Diurno Cica + Esfoliante Facial (2 Produtos)', 'Creme Facial Diurno de Cica: Este Creme Hidratante de Uso Diurno É o Que Você Precisava para Reparar a Pele E/ou Controlar a Oleosidade. Composição: Possui em Sua Composição Uma Combinação da Centella Asiática com Ativos Poderosos. São Eles a Niacinamida e Ceramidas, para Uma Hidratação, e o Madecassoide, Um Derivado da Cica Que Chega Na Fórmula para Reforçar Ainda Mais Os Benefícios da Planta. Benefício Principal: Reparador - Restaura a Barreira Protetora da Pele, Hidratação Eficiente e Controle de Oleosidade. Esfoliante Facial: Formulado com Extrato de Bambu, Mel e Limão, Este Esfoliante Facial Deixará Sua Pele Macia e com Viço. Enquanto o Extrato de Bambu Possui Propriedades Calmantes, o Mel Proporciona Maior Hidratação. para Potencializar Ainda Mais Os Efeitos e Auxiliar Na Limpeza, Encontramos Ainda o Limão, Que Além de Possuir Efeito Clareador, Deixará o Rosto com Um Toque de Frescor. Indicado para Todos Os Tipos de Pele, Incluindo As Oleosas, Este Esfoliante Realizará Uma Limpeza Profunda, Ao Retirar a Sujeira, Oleosidade Acumulada e Células Mortas. O Kit Creme Facial Diurno Cica + Esfoliante Facial Contém: - 1 Creme Facial Diurno - Cica Day Cream 50g - 1 Esfoliante Facial com Extrato de Bambu - Facial Scrub 100ml', 149.9, 139.9, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-824gx-mpe5zlizg1sb6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22492036157', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394703369', 'Armário De Cozinha Compacta 180 Cm Crema Nice Madesa 02', 'Armário De Cozinha Compacta 180 Cm Crema Nice Madesa 02 Crema A Cozinha Compacta de 180 cm da linha Nice é a solução ideal para quem precisa de praticidade. Um dos grandes diferenciais dessa cozinha é o nicho aéreo, que oferece espaço para acomodar forno ou micro-ondas, otimizando ainda mais a organização e funcionalidade do ambiente. A linha Nice chega em uma versão no tom crema, tonalidade que proporciona uma sensação de aconchego e leveza. Os puxadores em tom bronze metalizado e os pés em bronze sólido são detalhes que valorizam o design trazendo um toque contemporâneo. Produzido com materiais de qualidade, o balcão conta com dobradiças metálicas nas portas e puxadores em perfil de alumínio, discretos e resistentes. As gavetas possuem corrediças que permitem abertura total, oferecendo mais praticidade. O tampo é removível, possibilitando a instalação de cuba ou pedra e o acabamento é de alta resistência, garantindo durabilidade no uso diário. Medidas totais: - 211 cm de altura - 180 cm de largura - 52 cm de profundidade nos balcões, 31 cm no aéreo e 45 cm no nicho de micro-ondas O que você recebe: - Um Armário Aéreo de 120 cm com duas portas - Um Nicho aéreo de 60 cm com espaço para forno - Um Balcão de 120 cm com três portas e uma gaveta - Um Balcão de 60 cm com uma porta Código do produto: GRNC1800027P É importante saber: - Material: MDP - Imagens meramente ilustrativas, a decoração não acompanha o produto. - A Madesa não oferece de montagem. - O produto segue com manual e todas as ferragens necessárias para a instalação. A Madesa se dedica à sustentabilidade com várias iniciativas: temos uma usina própria que gera energia para uma das fábricas. Priorizamos fornecedores responsáveis com o meio ambiente. Todo o plástico utilizado na produção é reciclado, e as sobras também são reaproveitadas. Investimos no desenvolvimento de nossos colaboradores e em ações que beneficiem a comunidade. Cor: Bege | Garantia: 3 meses contra de fabricação | Dimensões - Altura: 211 cm | Dimensões - Largura: 180 cm | Dimensões - Profundidade: 52 cm | Produto: Cozinha Compacta | Marca: Madesa | Peso aproximado: 82,5 kg | Material: MDP | Estado de Origem: RS | Conteúdo da embalagem: Uma Cozinha Compacta | Material para Filtro: MDP | Instruções/Cuidados: Utilize um pano limpo, levemente umedecido e seque em seguida a superfície. Não usar produtos químicos ou abrasivos para a limpeza. Recomendamos polir seu móvel com lustra-móveis duas a três vezes por ano. | Produto precisa de Montagem?: Sim | Inclui tampo: Sim | Peso Produto Com Embalagem (Kg): | Altura do Produto com Embalagem (cm): 51,1 | Largura Produto Com Embalagem (cm): 66,1 | Comprimento Produto Com Embalagem (cm): 125,7 | Descrição do Tamanho: 211 cm x 180 cm x 52 cm | Nome do Simples no Fornecedor: Armário de Cozinha Compacta 180 cm Crema Nice Madesa 02 | Fabricante: Madesa | RBN: Casa/Móveis/Móveis para Escritório em Casa | Quantidade de Gavetas: 1 | Quantidade de portas: 6 | Tipo de móveis de cozinha: Cozinha Completa | Materiais do corpo: MDP | Quantidade de caixas de embalagem: 6 | Bullet Point 1: Dimensões: 211 cm altura x 180 cm largura x 52 cm profundidade | Bullet Point 2: A linha Nice chega em uma nova versão no tom Crema, uma tonalidade suave que transmite aconchego e leveza | Bullet Point 3: Os puxadores em bronze metalizado e pés em bronze sólido, que acrescentam um toque contemporâneo | Bullet Point 4: Possui acabamento de alta resistência, conservando a beleza do móvel por muito mais tempo | É Frágil: Não | Quantidade de Itens: 1 | Certificação de teste externa: Sim | Modelo: GRNC1800027P | Componentes incluídos: Portas | Precisa de baterias ou pilhas: Não | da peça (part_number): GRNC1800027P | Peso do item (item_weight): ;unit=kilograms | Dimensões do item P x L x A (item_depth_width_height): depth#value=52;depth#unit=centimeters;height#value=211;height#unit=centimeters;width#value=180;width#unit=centimeters | Requer montagem (REQUIRES_ASSEMBLY): Sim | Inclui manual de montagem (INCLUDES_ASSEMBLY_MANUAL): Sim | Inclui manual de montagem: Sim | Cor: Crema', 1219.92, 1219.92, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-821db-mgo22ty4d6vfca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22394703369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399603933', 'Fita Transparente Nexcare 25MM X 1,35M 3M', 'Projetada para ter o máximo de suavidade, não interferindo nas funções normais da pele e permitindo que ela transpire para melhor conforto, a Fita Micropore Nexcare, é perfeita para a fixação de curativos, gazes, cateteres, sondas e curativos de drenos. INDICAÇÃO DE USO: Ideal para peles sensíveis, a Fita Micropore Nexcare Transparente garante proteção e discrição aos ferimentos e curativos.', 14.9, 14.9, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rcbx-m6hjmgey30y1f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F20399603933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53005021783', 'Corneta 1519 Driver Expansor Driver Alumínio Boca Quadrada', 'Perfeita para garantir melhor desempenho e muita qualidade para seu projeto de som, a Corneta Curta é indicada para ser usada junto com drivers em caixas trio, caixas acústicas e em seu som automotivo. Feita em alumínio fundido, ela garante o melhor direcionamento do som para que você possa curtir sua experiência sonora com maior performance. Características: - Material: Alumínio Fundido - Formato: Curta Quadrada - Bocal de parafuso Modelo Disponível: - Branco/ Preto Especificação Técnica: - Bocal Quadrado - Excelente acabamento - Ideal para utilizar com Driver em Caixas Trio - Diâmetro da Garganta: 2'' - Diâmetro da Boca: 19 por 15cm - Profundidade Aproximada: 15,2cm - Altura: 18,9cm - Largura: 15,1cm Garantia do vendedor: 3 meses', 152.0, 152.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjrb03faql8iac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1240617679%2F53005021783', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
