INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14240616786', 'Câmara de Ar Paco 26x1.3/8', 'Câmara de Ar Paco 26x1.3/8 A Câmara de Ar 26x1.3/8 da Paco oferece muito mais durabilidade contra furos e rasgos, garantindo muito mais qualidade aos seus treinos. Suas principais características da borracha butílica, e elevada impermeabilidade aos gases e ao ar, boas propriedades de flexão resistente ao calor, resistente ao envelhecimento provocado pelas intempéries, resistente a produtos químicos, gorduras e a substancias fortemente oxidantes. Garanta segurança e alta durabilidade para pedalar com a Câmara de ar da Paco. Seja para a reposição ou por segurança ao realizar pedais mais longos, a câmara de ar aro 26 confere garantia de qualidade, garantindo um excelente custo x benefício. Especificações da Câmara de Ar Paco 26x1.3/8 - Borracha butílica; - Válvula Schrader/ Americana: 35mm (Bico Grosso) - Alta resistência; - Qualidade Premium.', 13.55, 13.55, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-22120-ktrfoypaqvkv9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F14240616786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193876797', 'Chave de Impacto Dewalt 20V 1/2" DCF961 C/ Bateria 5Ah XR e Carregador Bivolt Profissional Original', 'DISTRIBUÍDO POR C-JAÚ FERRAMENTAS Chave De Impacto Dewalt Dcf961 1/2 + Bateria 5ah 20v + Carregador Bivolt A Chave de Impacto DCF961B foi projetada para oferecer um desempenho incomparável e durabilidade excepcional. Com um torque impressionante de 160kg, ela é ideal para profissionais que enfrentam os desafios mais exigentes. Seu design foi cuidadosamente desenvolvido para proporcionar conforto durante longas horas de uso, reduzindo a fadiga e aumentando a produtividade. Equipada com motor brushless, não só entrega um desempenho poderoso como também garante eficiência energética superior e robustez para qualquer trabalho, sabendo que ela oferece resultados consistentes e confiáveis. Ideal para aplicações que exigem o máximo desempenho e confiança. Adquira agora a sua Chave de Impacto DCF961B e leve seus projetos ao próximo nível. Características: Voltagem: 20V Encaixe: 1/2" (13mm) Velocidade: 0-1200rpm Impactos por minuto: 0-1890ipm Torque de aperto: 1627Nm Torque de reversão: 2372Nm Altura da ferramenta: 24.8 cm (9.8") Comprimento da ferramenta: 21 cm (8.4") Peso: 3kg Itens Inclusos: 01 CHAVE DE IMPACTO A BATERIA DCF961B-B3 20V S/BAT. DEWALT 01 BATERIA DE LITIO 20 VOLTS 5.0 AH DCB205 XR DEWALT 01 CARREGADOR DE BATERIAS 12-20 VOLTS DCB107 BIVOLT DEWALT', 3349.0, 3188.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m86b2dhgjbptcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F23193876797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
