INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14742295174', 'Dewalt Dcf887 20v Parafusadeira Impacto Bat 4ah Xr E Carreg.', 'Kit Inclui: Ferramenta DCF887 + 1 bateria 4ah XR + carregador DCB107 Bivolt Parafusadeira de impacto de 1/4" encaixe sextavado são ideais para executar trabalho com mais força, agilidade e perfeição. A parafusadeira permite parafusar ou tarraxar porcas e parafusos com muita facilidade e menor esforço físico. Sua aparência é bem próxima com a de uma furadeira, porém, tem funções diferentes. Possui motor sem escovas de carvão proporcionando controle da transferência de energia de forma eficiente dentro da ferramenta, permitindo que a ferramenta funcione durante mais tempo entre cargas. - XR – motor sem escovas - Menos manutenção - BL motor – Brushless maximum runtime', 1854.0, 1854.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/ce4a7c311a85f7b92937ede431773931', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F14742295174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202344388', 'Petisco Petsko Orelha Bovina Natural 2 UND', 'Petisco Petsko Orelha Bovina Natural 2 UND A Orelha Natural Petsko é a escolha ideal para quem busca um petisco saudável e saboroso para seu cão. Produzida 100% a partir de matéria-prima bovina, esta orelha natural é livre de conservantes e oferece uma opção nutritiva e segura para pets de todos os portes. Além disso, o processo de fabricação garante um produto mais limpo, com incidência mínima de pelos, proporcionando uma experiência de mastigação mais agradável e higiênica. Com um tamanho maior do que as tradicionais orelhas suínas, a Orelha Natural Petsko é perfeita para manter seu cão entretido por mais tempo, auxiliando na saúde dental ao promover a remoção de tártaro e fortalecimento das gengivas. Seja para recompensar o bom comportamento ou simplesmente mimar seu melhor amigo, este petisco é a combinação perfeita de qualidade e sabor que seu pet vai adorar.', 27.99, 17.99, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mikm08khz4sj43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464043565%2F58202344388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
