INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19497460321', 'Meios Essenciais de Graça | Paul Washer', 'Você anseia por um mover sobrenatural e extraordinário do Espírito Santo para corrigir todas as suas falhas espirituais? Embora um avivamento assim seja possível e até mesmo desejável, não é esta a forma mais comum como Deus atua no crescimento de sua igreja. No livro Meios Essenciais de Graça, Paul Washer considera os três principais meios que Deus oferece graciosamente a fim de prover crescimento em santidade para o seu povo: as Escrituras, a oração e a participação na vida e no ministério de uma igreja local. Nosso desejo pelo extraordinário não pode nos levar a negligenciar o ordinário. Pelo contrário, devemos nos dedicar aos meios comuns, porém essenciais de graça em dependência do Espírito para que assim alcancemos uma semelhança extraordinária de caráter com Cristo, uma vez que amamos o Senhor e, portanto, buscamos ser servos úteis no Reino. Detalhes do Produto: Autor: Paul Washer Editora: Trinitas Acabamento: Brochura Dimensões: 14 larg. X 21 alt. Número de páginas: 92', 26.9, 26.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rble-lmxgm282i9gaef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F19497460321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53905745020', 'Oi Deus, Sou Eu de Novo | Deive Leonardo | Capa Dura', 'Deus quer ter um encontro com você todos os dias. Ele está sempre perto e pronto para ouvir quando você diz: “Oi Deus, sou eu de novo!”. É nesse diálogo simples e sincero que você pode entregar suas alegrias, tristezas, sonhos e desafios. Este devocional reúne 365 mensagens preparadas para fortalecer sua fé, renovar seu ânimo e lembrá-lo de que só Deus pode conceder paz verdadeira, alegria duradoura e um coração restaurado. Um convite diário para estar mais perto do Senhor e viver a vida extraordinária que Ele planejou para você. Autor: Deive Leonardo Editora: Preach Acabamento: Capa dura Dimensões: 16 cm larg. x 23 cm alt. Número de páginas: 394', 66.9, 54.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8261z-mk8g1lydrd359a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F53905745020', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
