INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40605043670', 'Soprador De Ar Térmico 600w Roxo Zacs Secagem Automotiva', 'O soprador de ar térmico Zacs é compacto, leve e portátil, oferecendo praticidade e versatilidade para a limpeza do seu veículo. Com 7 metros de cabo, 1 bico e uma bolsa inclusa, ele facilita a remoção de resíduos sólidos na parte interna do carro. Na parte externa, o soprador é ideal para a secagem completa do veículo, alcançando até as áreas mais difíceis de acessar. BENEFÍCIOS: Praticidade: Seu design leve e portátil permite fácil manuseio e transporte. Eficiência: Remove resíduos de forma rápida e eficaz, tanto no interior quanto no exterior do veículo. Versatilidade: Ideal para uso em diferentes partes do carro, incluindo áreas de difícil acesso. Secagem Rápida: Acelera o processo de secagem, evitando o acúmulo de água em locais difíceis de alcançar. Economia: Reduz a necessidade de serviços externos, permitindo que você cuide da limpeza e secagem do seu veículo em casa.', 349.9, 344.89, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb59wl17nent85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557320114%2F40605043670', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
