INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497484629', 'Vodka 998ml Caixa com 12 unidades Smirnoff', 'Vodka Smirnoff 998ml caixa com 12 unidades A Vodka Smirnoff Red possui o verdadeiro sabor da vodca Gostou? Compartilhe Uma bebida forte e de alta qualidade A sua vodka Smirnoff Red 998 ml apresenta um processo de fabricação que preza pela sua pureza e sabores únicos. Filtrada por até 10 vezes, a vodca Smirnoff ainda apresenta em sua composição ingredientes como o trigo, aveia e malte, resultando em uma bebida com um teor alcoólico de 37,5 e um sabor inesquecível e único a cada gole. A tradição de uma marca Com toda a qualidade da marca Smirnoff, a sua vodca Red é perfeita para alegrar sua festa ou reunião. Seu sabor marcante a deixa ideal para ser utilizada na criação de novas bebidas e para complementar os seus drinks. Essa vodca do tipo standard apresenta o típico sabor das melhores vodcas russas. Pontos Fortes Vodca filtrada por 10 vezes Atenção Teor alcoólico de 37,5 Description Features:Produção nacional; Teor alcoólico: 37.5; Conservar em local seco e fresco; Vodka Smirnoff red 998 ml Características: Beba com Moderação. Quantidade de Garrafas:1.0 Sabor: Tradicional País: Rússia Itens Inclusos:1 Garrafa de Vodka de 998ml Observações: Imagem meramente ilustrativa Prazo de Validade: Vide Impresso na Embalagem. A venda e o consumo de bebidas alcoólicas são proibidos para menores de 18 anos. Bebida Alcoólica pode causar dependência química, e em excesso, provoca graves males à saúde.', 658.7, 658.7, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-7rd5v-lupeshwyqs7a05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443109642%2F23497484629', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697705011', 'Bicama Box para Dois Colchões Solteiro Suede Bege 88x188', 'Bicama para Dois Colchões de Solteiro - Praticidade e Estilo em um Só Produto Descrição GeralUma bicama versátil e funcional, projetada para acomodar dois colchões de solteiro com medidas padrão de&nbsp;88x188 cm, garantindo conforto e praticidade para o dia a dia. Ideal para quartos compactos ou ambientes que precisam de uma solução inteligente. Características do ProdutoCompatibilidade de Colchões: Parte Superior:&nbsp;Pode ser utilizado qualquer colchão, sem limite de altura, desde que respeite as dimensões padrão de 88x188 cm. Cama Auxiliar:&nbsp;Compatível com colchões de até&nbsp;26 cm de altura. Medidas do Produto Montado: Dimensões totais (fechada):&nbsp;99x199 cm. Altura final:&nbsp;Variável, conforme a altura do colchão utilizado. Design Inteligente: O colchão encaixa perfeitamente na estrutura da bicama, evitando deslizamentos e garantindo maior estabilidade e segurança. Além disso, o design proporciona um toque moderno e inovador ao ambiente. Montagem Fácil: Produto de fácil instalação, bastando fixar os pés para que esteja pronto para uso. Itens InclusosBicama com cama auxiliar (estrutura apenas). Não acompanha colchões. Informações AdicionaisDimensões de Transporte: Certifique-se de que o produto passa por portas, elevadores e corredores do local de entrega antes da compra. Não realizamos desmontagem de portas, içamento externo ou montagem. Entrega: A transportadora realiza entregas apenas até onde for possível por elevador. Caso seja necessário subir escadas ou içar o produto, a responsabilidade será do cliente. Imagens Ilustrativas: As fotos que incluem colchões são&nbsp;meramente ilustrativas&nbsp;para demonstrar o produto final montado. Atenção: Produto entregue desmontado. Montagem simples e prática. Foto meramente ilustrativa. Escolha a praticidade e o conforto desta bicama funcional para transformar seu espaço com estilo e eficiência! &nbsp;&nbsp; &nbsp;', 887.78, 819.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbsbm5u1k61zb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F785818771%2F22697705011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
