INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55803168800', 'Minha Bíblia Com Adesivos Brilhantes | A Vida de Jesus', 'Minha Bíblia Com Adesivos Brilhantes | A Vida de Jesus Encontre e Cole os Adesivos Brilhantes Para Completar as Cenas das Histórias BíblicasJacob Vium-OlesenConheça a trajetória mais inspiradora de todos os tempos através de uma experiência interativa e brilhante! "Minha Bíblia Com Adesivos Brilhantes | A Vida de Jesus" convida as crianças a explorarem os principais momentos da vida de Cristo, desde o nascimento até a ressurreição. Com adesivos especiais e ilustrações encantadoras, os pequenos completam cenas que celebram os ensinamentos, milagres e o amor incondicional de Jesus. Este livro oferece uma maneira única e envolvente de apresentar a história central da fé cristã. A atividade de colar os adesivos brilhantes estimula a participação ativa, tornando cada ensinamento e parábola uma lição visual e tátil memorável. O que você vai encontrar neste livro: Os principais episódios da vida de Jesus, narrados de forma acessível e cativante para crianças.Adesivos brilhantes e de alta qualidade para interagir e colorir cada cena ilustrada.Uma ferramenta educativa que transforma o aprendizado da fé em uma experiência lúdica e criativa.Este livro é ideal para: Crianças que estão conhecendo a história de Jesus e se encantam com atividades manuais.Pais, catequistas e educadores cristãos em busca de recursos interativos para o ensino religioso.Presente para ocasiões especiais como Primeira Comunhão, Páscoa, Natal ou aniversários.Adquira já "Minha Bíblia Com Adesivos Brilhantes | A Vida de Jesus" e permita que os pequenos vivenciem os passos de Cristo de forma brilhante e inesquecível. A maneira perfeita de semear a fé com alegria e criatividade!', 14.0, 14.0, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-822wg-miboewil9jif99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F55803168800', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11411377855', 'Filtro De Ar Motor Honda Civic 1.7 Jfa0428', 'FILTRO DE AR MOTOR JFA428 Obs: Na falta de Filtro Wega estaremos prosseguindo com o envio da marca Tecfil,Ambos de qualidade similar. - PORQUE DEVE-SE TROCÁ-LO REGULARMENTE? A troca regular do Filtro de Ar de Cabine garante um ambiente saudável aos ocupantes do veículo, pois evita a invasão de contaminantes como: poeiras, ácaros e outros micro-organismos nocivos que atacam as vias respiratórias do ser humano. - APLICAÇÃO : HONDA : Civic 1.7 16v 2001 a 2005 Conversão Fram CA8911 Honda 17220PLC000 Honda 17720PLC000 Japanparts FA428S Mahle LX1689 Mann C3221 Purflux A1661 Tecfil ARL1032 Vox HLP1032 Características: - MODELO : JFA428 - TIPO DE FILTRO : Filtro Ar - CONTEÚDO DA EMBALAGEM : 1 Unidade - ELEMENTO FILTRANTE: Papel - Formato : Retangular - COMPRIMENTO : 315mm - ALTURA : 53mm - LARGURA : 203mm - COR : Vermelho - ESTRUTURA DE REFORÇO: Plástico', 49.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/0970052a6d0728ff4dba35cb9e63881d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F295637446%2F11411377855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598517922', '2 Par Pastilha Freio A Disco Compativel Shimano Tektro Gts', 'Ref. 2 Pares C/ Molas Pastilha de freio a disco Semi-Metalica Serve em: SHIMANO: M355/M375/M395/M415/M416/M445/M446/M447/M475/M485/M495/M515/M525/M535/M575/C501/C601 Tektro: Orion/Auriga PRO/Auriga Comp/Auriga E-Comp/Draco/Draco WS/Aquila Resina de alta qualidade compacta, leve e durável potência de travagem sem ruido possui mais grânulos de cobre, Melhor dissipação de calor perfeito tratamento de superfície. Além de leve, pode ser usado em qualquer tipo de terreno. Descrição: Sapata (pastilha) para freio a disco modelo ds-01 Composição: pastilhas sinterizadas Principais caracterÍsticas: Suporta temperaturas mais elevadas Melhor frenagem na chuva Maior durabilidade Modelo: ds-01 Marca: gts', 18.63, 13.99, NULL, 'Sports & Outdoors > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rave-ma1o7h6mhmqhc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102597%2F23598517922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398193349', 'Manso E Humilde E Devocional No Senhor Me Refugio', 'Kit Dane C. Ortlund', 95.42, 95.42, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbkl-m64fdwjv2xrf4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23398193349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997686079', 'Creme Cerave Hidratante Pele Seca e Extra Seca Sem Perfume 50g', 'Descrição do produtoO que é o Hidratante Corporal CeraVe?O hidratante corporal CeraVe foi desenvolvido por dermatologistas para a hidratação e restauração da barreira protetora da pele, especialmente de peles secas e extrassecas. CeraVe Hidratante Corporal contém as 3 ceramidas essenciais para a pele, contém ácido hialurônico e promove hidratação o dia todo por meio da sua tecnologia MVE, de liberação prolongada. De fórmula leve, textura cremosa e de rápida absorção, deixa a pele macia e suave, sem aquela sensação pegajosa. Não tem perfume. O que é ácido hialurônico?O Ácido Hialurônico é formado pelas células da pele e tem como uma das principais funções reter a umidade. À medida que envelhecemos, a capacidade natural da pele de produzir essa substância diminui ou se esgota, o que gera o aparecimento ou aprofundamento das rugas. O que são Ceramidas?Ceramidas são lipídios que compõem a barreira cutânea. Sua principal função para a pele é reter a saída de água das células e evitar a desidratação. BenefíciosReduz o ressecamento da pele. Reduz a flacidez. Ajuda a reter a hidratação natural da pele. Liberação prolongada de ativos, para uma pele hidratada o dia todo. Restaura a barreira protetora da pele com suas 3 ceramidas, essenciais para uma pele saudável. Sem perfume, não resseca e não irrita a pele. Sem parabenos. Como usar o Hidratante Corporal CeraVe?Espalhar o Hidratante Corporal CeraVe em todo ocorpo, massageando suavemente até que o produto seja absorvido pela pele. Não esqueça das áreas mais ressecadas como pernas, cotovelos epés. Uso diário, sempre que necessário, ou conforme orientação do seu dermatologista. Não aplicar na região dos olhos. Potencialize sua hidratação aplicando CeraVe após o banho. ComposiçãoAqua/water, glycerin, cetearyl alcohol, caprylic/capric triglyceride, cetyl alcohol, ceteareth-20, petrolatum, dimethicone, phenoxyethanol, behentrimonium methosulfate, potassium phosphate, ethylhexylglycerin, sodium lauroyl lactylate, disodium edta, dipotassium phosphate, ceramide np, ceramide ap, phytosphingosine, cholesterol, xanthan gum, carbomer, sodium hyaluronate, tocopherol, ceramide eop. AdvertênciasUso externo. Não ingerir. Caso haja contato com os olhos, lave-os abundantemente. Se houver irritação, suspenda o uso imediatamente e procure orientação médica. Mantenha fora do alcance das crianças.', 69.86, 69.86, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-82624-mkshat80houaf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F19997686079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993677730', 'VITAMINA E 400UI 400MG COM 30 CÁPSULAS', 'A Vitamina E 400UI é um potente antioxidante que protege contra os danos causados pelos radicais livres. Indicada por médicos e nutricionistas, ela auxilia na imunidade, no retardamento do envelhecimento e na prevenção de doenças. Ideal para quem busca um reforço para a saúde e bem-estar.', 39.63, 39.63, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-m5t2hxo75i1j09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F23993677730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43026740494', 'Correia Poliéster Music New C Aviamento Plástico SN5CAP', 'Feita de poliéster, esta correia é projetada para durar. Ela é resistente ao desgaste e pode suportar o uso diário sem perder sua beleza ou funcionalidade. Além disso, o material de poliéster garante um conforto excepcional, permitindo que você use seu equipamento por longos períodos sem desconforto. A correia é ajustável, com comprimento variável de 85 cm a 150 cm. Também possui uma largura de 5 cm na região do ombro, proporcionando conforto e o melhor ajuste para o seu estilo.', 15.9, 15.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8226r-mhgn8m1arpjb83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F43026740494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298031112', 'Livro Espaço - Coleção Explore', 'Venha explorar o mágico, infinitoe misterioso espaço sideral comeste fantástico kit, que vem com livro pôster, estêncil e peças 3D para montar. Você vai aprender sobre corpos celestes, comoplanetas, estrelas, luas, galáxias e muito mais desse incrível Universo!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Ciranda Cultural _x000D_ Idioma: Português_x000D_ Páginas: 48_x000D_ Dimensões: L 19.50 x A 29.30 x E 5.80_x000D_ ISBN: 9786526110164_x000D_ Coleção: Explore_x000D_ Linha Editorial: Ciranda Cultural - Trade_x000D_ Faixa Etária: + 6 anos_x000D_ Assuntos (tags): Informação, Adesivos, Pôster, Box, Animais_x000D_ BISAC: Não Ficção Infantil / Ciência & Natureza / Astronomia_x000D_ Linha de Produto: Box com atividades, adesivo e estêncil_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Almofadada_x000D_ Material: Papel', 74.9, 74.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rcdo-m6co5xi500w0a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F19298031112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997567387', 'Lux Sabonete Líquido Refil Lavanda Com 200Ml', 'Lux Refil Sabonete Líquido Lavanda 200ml: Limpeza Suave, Aroma Relaxante e Economia O Refil de Sabonete Líquido Lux Lavanda de 200ml é a opção econômica e sustentável para repor o sabonete suave. Sua fórmula suave limpa delicadamente, mantendo a hidratação natural da pele. Com fragrância floral e suave de Lavanda, o Refil Lux deixa a pele macia, suave e suavemente perfumada. O refil de 200ml reduz o consumo de plástico. Uso diário seguro. Ideal para mãos e corpo. Limpeza Suave, Relaxamento e Sustentabilidade Refil: Fragrância Lavanda: Aroma floral suave, calmante e relaxante.Refil 200ml: Opção econômica e sustentável. Limpeza Suave: Limpa sem ressecar e mantém a maciez. Uso Diário: Limpeza e cuidado para mãos e corpo. Use para reabastecer a embalagem original. Aplique nas mãos, massageie e enxágue. A limpeza delicada que nutre e protege sua pele, com a fragrância de lavanda e economia.', 28.35, 28.35, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-82605-mlw468jpwgec00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F22997567387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098698899', 'LuteínaVision® - Luteína, Zeaxantina, Vitamina A, Cobre e Zinco - 30 Cápsulas - 1 Unidade', 'LuteínaVision® – Saúde ocular com luteína, zeaxantina, vitaminas e minerais Suplemento alimentar em cápsulas LuteínaVision® é um suplemento alimentar que combina luteína e zeaxantina com vitamina A, vitamina E, zinco e cobre — nutrientes que participam da proteção celular contra os radicais livres e da manutenção da saúde dos olhos. ALEGACÕES PERMITIDAS PELA ANVISA: 🟡 Vitamina A “Auxilia na visão.” “Contribui para a manutenção das mucosas.” “Auxilia no funcionamento do sistema imune.” 🟣 Vitamina E, Zinco e Cobre “Auxiliam na proteção dos danos causados pelos radicais livres.” 🔷 Zinco “Contribui para a manutenção da visão.” “Auxilia no metabolismo da vitamina A.” DESTAQUES DA FÓRMULA: 👁️ Luteína (Tagetes erecta) Carotenoide amplamente utilizado em suplementos voltados à saúde ocular. 👁️ Zeaxantina Presente na mácula da retina, naturalmente associada a dietas que promovem o cuidado visual. 🟠 Vitamina A (acetato de retinol) Essencial para a manutenção da visão e do sistema imunológico. 🛡️ Vitamina E + Zinco + Cobre Nutrientes com ação antioxidante, que contribuem para a proteção celular. COMO USAR: Ingerir 1 cápsula ao dia com 200 ml de água, preferencialmente após uma refeição, ou conforme a orientação de profissional de saúde. ⚠️ Este produto não deve ser consumido por gestantes, lactantes e crianças. INGREDIENTES: Luteína da flor de Tagetes erecta, bisglicinato de zinco, zeaxantina, DL-alfa-tocoferol (vitamina E), acetato de retinol (vitamina A), bisglicinato de cobre e antiumectante dióxido de silício. Ingredientes da cápsula: Gelatina, óxido de ferro vermelho e óxido de ferro amarelo. NÃO CONTÉM GLÚTEN. ESTE PRODUTO NÃO É UM MEDICAMENTO. MANTENHA FORA DO ALCANCE DE CRIANÇAS.', 49.9, 48.91, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbr67w567fl35f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1543591764%2F23098698899', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20397732667', 'LEITE DE COLÔNIA ORIGINAL COM 200ML', 'Leite de Colônia é indicado para: - Contribuir com a limpeza profunda dos poros da pele.', 28.86, 28.86, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd6o-lwnen9y7dcvde5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251200960%2F20397732667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13946322555', 'Ração Premier Nutrição Clínica Gatos Urinário 1,5Kg', 'A PremieR Nutrição Clínica Urinário para gatos é um alimento Super Premium para felinos com problemas de cálculo urinário. Seu uso como base da dieta, favorece a dissolução de cálculos renais e das substâncias causadoras do cálculo. Contribui para o tratamento de cálculo renal, ajuda na eliminação dos cálculos de estruvita. Sua fórmula com concentração balanceada de minerais, controle do pH urinário, proteína, fósforo e magnésio reduzidos. Ingredientes Farinha de vísceras de frango, farinha de torresmo, glúten de milho*, plasma sanguíneo desidratado de suíno, proteína isolada de soja, grão de milho*, grão de trigo, celulose, quirera de arroz, polpa desidratada de beterraba, banha refinada, gordura de frango, óleo refinado de peixe, acácia nilótica, cloreto de potássio, cloreto de sódio, cúrcuma (Curcuma longa), levedura de cervejaria inativada desidratada, sulfato de glicosamina, ácido cítrico, cloreto de amônio, bentonita, BHA (Butilhidroxianisol), BHT (Butilhidroxitolueno), DL-metionina, extrato de yucca, fosfatidilcolina, hidrolisado de fígado de suíno, L-lisina, sulfato de amônio, taurina, vitamina A, vitamina B1, vitamina B2, vitamina B3, vitamina B5, vitamina B6, vitamina B9, vitamina B12, vitamina C, cloreto de colina, vitamina D3, vitamina E, vitamina H, vitamina K3, ferro aminoácido quelato, iodato de cálcio, manganês aminoácido quelato, selenometionina hidroxi análoga, sulfato de ferro, sulfato de manganês, sulfato de zinco monohidratado, zinco aminoácido quelato.', 95.9, 95.9, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf187wy33nd3b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F13946322555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207877496', 'Camiseta Diadora Icon Masculina', 'FOOTONE DESCRIÇÃO DO PRODUTO: Performance e estilo se encontram na Camiseta Diadora Icon Masculina. Confeccionada em 100% poliéster, ela oferece leveza, respirabilidade e secagem rápida para treinos e uso diário. Seu design apresenta o logo Diadora em destaque na parte frontal, garantindo identidade esportiva marcante. Ideal para atividades físicas, momentos de lazer ou para compor looks casuais com muito estilo. CARACTERÍSTICAS: • Tecido 100% Poliéster para Alto Desempenho: A camiseta é confeccionada em poliéster de alta qualidade, material que garante leveza, respirabilidade e rápida evaporação do suor, mantendo o corpo seco e confortável durante atividades físicas ou em dias mais quentes.É a escolha certa para quem busca uma peça que une funcionalidade e estilo. • Design Esportivo com Logo em Destaque: O modelo traz o logo Diadora aplicado na parte frontal com acabamento de alta qualidade, criando um visual moderno e cheio de personalidade.O design clean e marcante reforça a identidade esportiva da marca, sendo perfeito para treinos ou para o uso casual no dia a dia. • Modelagem Regular e Gola Redonda: A camiseta possui modelagem regular desenvolvida para o corpo masculino, com gola redonda que proporciona ajuste confortável e caimento adequado.O corte anatômico permite liberdade de movimento, sendo ideal para corridas, academia, treinos funcionais ou momentos de lazer. • Versatilidade para Diferentes Ocasiões: Ideal para atividades físicas, treinos na academia, corridas ao ar livre ou para compor looks casuais com jeans, bermudas e shorts.Seu design esportivo e versátil permite transitar com naturalidade entre o treino e o dia a dia. • Acabamento Durável e Fácil Conservação: O tecido 100% poliéster mantém as cores vibrantes e a forma mesmo após múltiplas lavagens, enquanto o logo aplicado é desenvolvido para resistir ao desgaste.A camiseta é de fácil manutenção, podendo ser lavada à máquina sem perder suas características. • Marca: Diadora • Modelo: Icon • Gênero: Masculino ITENS INCLUSOS: 01 - Camiseta', 48.99, 48.99, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/br-11134201-820mh-mqyg0x1dcu12a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F396321395%2F58207877496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15296145596', 'Caixa 12un Petisco Whiskas Temptations Pelo Saudável Gatos Adultos 40g', '- Indicado para gatos adultos; - Crocantes por fora e macios por dentro; - Ajuda a manter os pelos macios e brilhantes; - Irresistível e saboroso; - Fonte de vitaminas e minerais; - Disponível em embalagem com 40 g. Toda mudança na alimentação deve ser feita de forma gradual. Visite o veterinário regularmente. Mantenha sempre água fresca à disposição do seu gato.Conservar o produto em sua embalagem original, devidamente fechada, em local seco e fresco. Composição Milho Integral Moído*, Glúten de Milho*, Farinha de Vísceras de Aves, Quirera de Arroz, Sebo Bovino, Farinha de Trigo, Óleo de Frango, Glúten de Trigo, Hidrolisado de Fígado de Frango, Vitaminas (B2, B6, Ácido Pantotênico, Biotina, Niacina), Minerais (Cloreto de Sódio – Sal Comum, Fosfato Bicálcico), B.H.T. (Hidróxido de Tolueno Butilado). *Espécies doadoras do gene: Agrobacterium tumefaciens, Bacillus thuringiensis, Streptomyces viridochromogenes, Zea mays, Sphingobium herbicidorovans, Dicossoma sp., Diabrotica firgifera, Thermoccocales spp, Bacillus substilis.', 147.0, 124.95, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lj5m1dmojbclac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F15296145596', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202883508', 'Mochila de Rodinhas Infantil Barbie Up4you Pequena', 'A Mochila de Rodinhas Infantil Barbie Up4you é ideal para acompanhar as crianças na escola com muito estilo e praticidade. Com design vibrante e estampa exclusiva da Barbie, o modelo encanta pelo visual colorido e pelo acabamento de alta qualidade, perfeito para o público infantil. Com dimensões de 41x31x15 cm e capacidade pequena, essa mochila possui aproximadamente 5,6 litros, sendo indicada para o transporte de materiais escolares leves, lancheiras ou objetos do dia a dia, além de comportar itens de até 16 polegadas. O modelo conta com bolso frontal para melhor organização, bolsos laterais em mesh ideais para garrafa e alça para costas, permitindo o uso tanto nas rodinhas quanto como mochila tradicional. O sistema de rodinhas facilita o transporte, reduzindo o peso nas costas da criança. Confeccionada em poliéster resistente, a mochila oferece durabilidade, leveza e fácil manutenção. A estampa colorida e o design temático Barbie tornam o produto ainda mais atrativo para o uso escolar e passeios. Para conservar o produto, recomenda-se a limpeza com pano úmido e sabão neutro, evitando o uso de produtos abrasivos e a lavagem em máquina.', 139.9, 139.9, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mjjvfrja8m4j5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F58202883508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697550521', 'Deixe de ser pobre - Maquinaria Editorial', 'Eduardo Feldberg sempre foi fascinado pelo modo com que as pessoas lidam e investem o próprio dinheiro. Depois de uma formação em música, ele começou a observar o universo das finanças, mas percebeu que a maioria dos conteúdos tinham a mesma fórmula: Um engravatado usando termos complicados, mais confundindo do que ajudando os que o assistiam. E também estava indignado: ‘Com o fato de que muita gente boa trabalha demais o tempo todo para, no final das contas, ter uma vida mais lascada que joelho de freira.’ Então, foi criado o ‘Primo Pobre’, canal no YouTube com mais de 1,3 milhão de seguidores, destinado para o ‘povão’, para quem cansou de não entender a própria vida financeira e quer aprender a cuidar das finanças de forma fácil e descomplicada. Porque, afinal, todo brasileiro merece a tranquilidade de pagar as contas do mês, sair para almoçar com a família em um lugar legal, e conseguir investir um pouco do dinheiro.', 51.01, 51.01, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/sg-11134201-7rd40-lvuar42e6x4o94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23697550521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592576006', 'A prisão do rei - Seguinte', 'Mare Barrow foi capturada e passa os dias presa no palácio, impotente sem seu poder, atormentada por seus erros. Ela está à mercê do garoto por quem um dia se apaixonou, um jovem dissimulado que a enganou e traiu. Agora rei, Maven continua com os planos de sua mãe, fazendo de tudo para manter o controle de Norta - e de sua prisioneira. Enquanto Mare tenta aguentar o peso sufocante das Pedras Silenciosas, o resto da Guarda Escarlate se organiza, treinando e expandindo. Com a rebelião cada vez mais forte, eles param de agir sob as sombras e se preparam para a guerra. Entre eles está Cal, um prateado em meio aos vermelhos. Incapaz de decidir a que lado dedicar sua lealdade, o príncipe exilado só tem uma certeza: Ele não vai descansar enquanto não trouxer Mare de volta.', 63.69, 63.69, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7r9by-ln7q7de4w91i2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22592576006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28886974272', 'Super Tweeter Bomber STB350 - 100 Watts RMS 8 Ohms', 'O STB350 é a evolução do já reconhecido e aprovado STB320. O produto agora conta com 100 Watts RMS, além de melhoria em todo o projeto, conferindo ao produto mais fidelidade sonora e maior resposta de frequência, reproduzindo até as frequências mais altas, com muita potência. Este produto não pode faltar no seu trio, excelente para sistemas de 3 ou 4 vias. Especificações Técnicas: • Impedância: 8 Ohms • Resposta de Frequência: 3.500 a 20.000 Hz • Potência: 100W RMS • Sensibilidade: 104 dB Conteúdo da Embalagem: • 01 Super Tweeter Bomber STB350 - 100 Watts RMS 8 Ohms • Manual de Instruções • Certificado de Garantia', 104.0, 86.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma9ybdcfy6ye99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F28886974272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293064366', 'Frieren e a Jornada para o Além - 01', 'A história depois de um grupo de heróis terem derrotado o Rei Demônio. Você acompanhará Frieren, uma elfa diferente dos seus três companheiros de viagem. Você verá o que ela viveu no mundo, o que ela sentiu depois da aventura ter terminado. E ainda, sua relação com os que ficaram e o que seria a oração para os mortos... "Essa história começa depois que a aventura termina". "Uma fantasia pós-aventura que conta o modo de viver desses heróis!"', 39.89, 39.89, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd71-lvtrglno6u1mc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22293064366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53303282856', 'Versus Vol. 02 - Grupo Editorial JBC', 'Treze mundos diferentes se conectaram e agora a humanidade de cada um deles se une para enfrentar o imensurável poder de seus inimigos naturais – demônios, alienígenas, robôs entre outros. O plano dos humanos é jogar seus rivais uns contra os outros para que se eliminem. Mas para isso, um grupo de heróis terá de enfrentar uma primeira missão suicida para atrair os gigantes devoradores de pessoas para que lutem contra os Neo-Humanos. Liderando os humanos que se prontificaram a colocar a vida em risco está Ario, o único sobrevivente do ataque contra os demônios.', 38.07, 38.07, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-81ztl-mieqqnvp22vbb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F53303282856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
