INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13301906779', 'Caneta Chave Teste De Voltagem Digital 12v A 220v AC/DC Corrente Elétrica Bivolt Construção', 'COMERCIAL VIPASA DISTRIBUIDORA Caneta Chave Teste De Voltagem Digital 12v A 220v AC/DC Corrente Elétrica Bivolt Construção Caneta Chave Teste De Voltagem/corrente Digital 12-220v Bivolt Chave Multiteste Digital 12-220V Display LCD Com Lâmpada Neon A Chave Multiteste Digital é projetada para detectar tensão em redes elétricas, sendo utilizada também para verificar a capacidade de baterias e pilhas. Possui um display LCD que indicará se o mesmo está energizado. Não nos responsabilizamos pela montagem/instalação dos produtos. Verifique com o fabricante do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Todas as informações divulgadas, bem como os benefícios e resultados do produto são de responsabilidade exclusiva do Fabricante/Fornecedor. Imagens meramente ilustrativas. COMERCIAL VIPASA DISTRIBUIDORA', 14.99, 13.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2sris46eo5xf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F13301906779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093861308', 'Kit Jogo 3 Adesivo PU Fixa Espelho Branco Cibra Profissional 400g Alta Aderência Fixação Segura', 'COMERCIAL VIPASA DISTRIBUIDORA. Kit Jogo 3 Adesivo PU Fixa Espelho Branco Cibra Profissional 400g Alta Aderência Fixação Segura Adesivo PU Fixa Espelho Branco Cartucho 400g 150030 - Cibra 🔹 Fixação forte e segura para espelhos e superfícies delicadas! 🔹 O Adesivo PU Fixa Espelho Branco 400g Cibra é um selante e adesivo de poliuretano monocomponente, ideal para fixação de espelhos e materiais delicados em superfícies como vidro, metal, madeira, concreto e cerâmica. Desenvolvido para garantir aderência superior, flexibilidade e resistência, ele é perfeito para aplicações onde a estética e a segurança são essenciais. 📌 Principais benefícios e aplicações: ✅ Fixação sem pregos e parafusos – Solução prática e segura para instalação de espelhos ✅ Alta aderência – Forte colagem em superfícies lisas e porosas ✅ Flexibilidade e resistência – Absorve vibrações e dilatações sem comprometer a fixação ✅ Não danifica espelhos – Fórmula livre de solventes que evita corrosão no verso do espelho ✅ Resistência à umidade – Indicado para banheiros, cozinhas e áreas internas úmidas ✅ Fácil aplicação – Uso prático com pistola aplicadora de cartucho 🔹 Características Técnicas: Marca: Cibra Modelo: 150030 Cor: Branco Tipo: Adesivo de Poliuretano (PU) Conteúdo: 400g Base química: Poliuretano monocomponente Tempo de secagem: 24 horas para cura total (dependendo das condições ambientais) Aplicação: Uso com pistola aplicadora de cartucho 🎯 Onde usar o Adesivo PU Fixa Espelho? ✔ Espelhos de diversos tamanhos – Fixação segura em paredes e móveis ✔ Vidros e superfícies lisas – Colagem eficiente em materiais como alumínio e aço inox ✔ Madeira e MDF – Perfeito para projetos de decoração e mobiliário ✔ Concreto e cerâmica – Aplicável em paredes e áreas de alvenaria 📦 Conteúdo da embalagem: ✅ 1 Adesivo PU Fixa Espelho Branco Cibra - Cartucho 400g 📌 Adesivo PU Fixa Espelho Branco 400g Cibra - Alta Aderência 📌 Cola PU para Espelho e Vidro Branco 400g Cibra - Fixação Segura 📌 Selante PU Fixa Espelho Branco 400g Cibra - Uso Profissional 🔹 Garanta já o seu adesivo PU e tenha uma fixação profissional e segura! COMERCIAL VIPASA DISTRIBUIDORA.', 59.99, 54.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd5r-m7n071dbi6v1ae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F22093861308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897914060', 'Balcão Cozinha Itatiaia Tarsila 3 Portas 2 Gavetas Branco/Preto IG3G2-120', 'Balcão Itatiaia Tarsila Preto IG3G2-120 Fabricado em aço de alta qualidade, testado e verificado em laboratório próprio da Itatiaia, e que recebe em seguida tratamento químico específico para garantir durabilidade e proteção contra ferrugem. A pintura eletrostática a pó deste armário é feita com tinta atóxica, ecologicamente correta e, portanto, de aplicação segura e sem riscos aos operadores. Possui puxadores em alumínio, de acabamento resistente, leve, durável, bonito, com alta resistência à corrosão e a variações bruscas de temperatura. O tampo do gabinete é feito em fórmica, um laminado decorativo de alta pressão e termomoldável, trazendo maior resistência a desgaste, calor (alta temperatura – 120°C), impacto e manchas. Por causa da superfície não porosa, o laminado não retém sujeira e dificulta a proliferação de fungos e bactérias. Mais limpeza e higiene para sua cozinha! ATENÇÃO: - Não nos responsabilizamos pela montagem / instalação dos produtos. - Imagens meramente ilustrativas. - Verifique com os fabricantes dos produtos eventuais limitações à utilização de todos os recursos e funcionalidades. INFORMAÇÕES TÉCNICAS: Marca: Itatiaia Linha: Tarsila Modelo: IG3G2-120 TARSILA PTO Cor: Preto Material: corpo e portas em aço Pintura/Revestimento: pintura eletrostática a pó Acabamento: Semibrilho Quantidade de portas: 3 Quantidade de gavetas: 2 Quantidade de prateleiras: 2 Quantidade de pés: 4 Corrediças: telescópica Dobradiças: metálicas 26mm Puxadores: alumínio Necessita de montagem: sim Sistema de montagem: parafusos Instruções/Cuidados: limpeza com pano umedecido Peso com embalagem: 33,95kg Dimensões do produto na embalagem: 127 (P) x 72 (L) x 13,5 (A) cm Dimensões do produto montado: 52 (P) x 120 (L) x 92 (A) cm Garantia: 12 meses', 999.9, 719.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdw3-m1d96uuzzogna1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F680601528%2F23897914060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22495930382', 'Escova de Cabelo Modeladora Térmica com Cerdas Iônicas 43mm Thermic Bronzer Lanossi', 'A Escova de Cabelo Modeladora Térmica com Cerdas Iônicas 43mm Thermic Bronzer Lanossi possui cerdas sintéticas de nylon iônicas com efeito anti frizz, ideais para auxiliar na secagem e modelar os fios. Possui tubo vazado com revestimento em cerâmica que retém e distribui uniformemente o calor do secador, facilitando a secagem rápida. Com cabo antiderrapante e anatômico, promove uma escovação segura e confortável. Seu diâmetro de 43mm é ideal para cabelos compridos. Esse produto deve ser sempre armazenado em locais limpos e secos, ao abrigo do sol e do calor. Com a linha Thermic Bronzer da Lanossi, tenha o resultado de salão nos seus cabelos em casa de forma prática e fácil! Medidas: 6,5 x 29,4 x 6,5 cm (A x L x C)', 144.9, 144.9, NULL, 'Beauty > Hair Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfg6-m9691bewpac181', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22495930382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492821862', 'Pá Para LIixo Galvanizada Com Cabo Madeira 80cm Rodobem Cores Sortidas', 'COMERCIAL VIPASA DISTRIBUIDORA A Pá para Lixo Galvanizada de 80cm é uma ferramenta resistente e durável, projetada para facilitar a limpeza e coleta de resíduos. Sua lâmina é fabricada em aço galvanizado, conferindo-lhe proteção contra corrosão e garantindo uma longa vida útil. O cabo de madeira, com 80cm de comprimento, proporciona uma empunhadura confortável e firme durante o uso, permitindo uma manipulação eficiente da pá. Além disso, a combinação do aço galvanizado e do cabo de madeira confere à pá uma estética clássica e tradicional. Ideal para uso em ambientes domésticos, comerciais ou industriais, a Pá para Lixo Galvanizada é uma escolha confiável para a coleta eficiente de resíduos sólidos. Seu design prático e robusto a torna uma ferramenta indispensável para manter a limpeza e a organização em diversos espaços. Eficiência na Limpeza: Facilita a remoção de resíduos de forma rápida e eficiente. Durabilidade Garantida: Construída com materiais de qualidade, proporcionando longa vida útil. Versatilidade de Uso: Pode ser utilizado em diversos ambientes, atendendo às necessidades de limpeza em diferentes locais. COMERCIAL VIPASA DISTRIBUIDORA', 27.99, 27.99, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcf3-lqwcsvuk36vveb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F22492821862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
