INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893865799', 'Massa Acrílica Sherwin Willams 25kg', 'Massa Acrílica Sherwin Willams 25kg DESCRIÇÃO Utilizada para corrigir pequenas imperfeições e uniformizar superfícies em ambientes externos ou paredes internas úmidas. Durante o processo de preparação da superfície, o produto tem fácil aplicação e ótimo nivelamento, proporcionando um acabamento mais liso. Ótimo Nivelamento Fácil de Aplicar Uso Interno e Externo SUPERFÍCIES Reboco, gesso, drywall concreto, fibrocimento. Quarto, sala, cozinha, banheiro, escritório, lavanderia, fachadas e muros Paredes, tetos, gesso e drywall RENDIMENTO Lata (25kg): até 50m² 2 M² Kg AMBIENTE Exterior e interior. ACABAMENTO Fosco ATRIBUTOS Ótimo Nivelamento Fácil de Aplicar SECAGEM Ao Toque: 1 hora Entre Demãos: 2 - 4 horas Final: 6 horas APLICAÇÃO Desempenadeira Espátula DEMÃO 2 a 3 demãos COR Branco DICAS Proporciona nivelamento e corrige pequenas imperfeições em ambientes externos ou paredes internas úmidas.', 330.74, 330.74, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134224-81z1k-mg5ori5s7hfo95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1581716586%2F23893865799', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
