INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393538577', 'Discos Embreagem Gp7 (11 Pecas) Cg 150 Competição', '🏍️ Kit Discos de Embreagem GP7 11 Peças Honda CG 150 Competição 📦 ENVIO RÁPIDO: MÁXIMA PERFORMANCE TORQUE AGRESSIVO E RESPOSTA IMEDIATA! O Kit GP7 de 11 peças é a escolha definitiva para quem busca desempenho profissional na sua CG 150. Desenvolvido para suportar o uso extremo em trilhas wheeling ou competições ele garante que a força do motor seja transmitida com precisão total eliminando a patinação e resistindo a altas temperaturas mesmo sob condições severas de uso. MODELOS COMPATÍVEIS: Honda CG 150 (Todos os anos) Atenção: Recomendamos confirmar a compatibilidade com o seu preparador ou mecânico antes da compra. 🏆 PRINCIPAIS BENEFÍCIOS: Mais torque na roda com redução drástica da patinação da embreagem. Engates de marcha muito mais rápidos precisos e firmes. Alta resistência ao calor em condições de uso extremo e alta rotação. Kit completo com 11 peças incluindo discos de alto atrito e separadores reforçados. Durabilidade superior ideal para motos preparadas trilhas ou entregas contínuas. ⚙️ DETALHES TÉCNICOS: Marca: GP7 Conteúdo da Embalagem: 11 Peças (Discos e Separadores Metálicos) Indicação: Wheeling / Trilha / Competição / Carga Pesada Condição: Produto novo pronto para instalação imediata 🤝 POR QUE COMPRAR NA KIZZ MOTO PEÇAS? Referência em Performance: Somos especialistas em peças de alto desempenho e confiança. Envio Ágil e Seguro: Sua encomenda é preparada com rapidez e enviada para todo o Brasil. Suporte Técnico: Nossa equipe realmente entende de motos e orienta a sua escolha técnica. Pronta Entrega: Trabalhamos com produtos em estoque e garantia de procedência. Aviso Importante: Recomendamos que a instalação seja feita por um profissional qualificado para garantir o ajuste perfeito e a máxima vida útil do kit. Imagens meramente ilustrativas. 🌟 Eleve o nível da sua máquina com a qualidade GP7. Adicione o seu Kit de Competição ao carrinho agora mesmo!', 86.35, 77.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-md25klv3qo6x87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1117095756%2F22393538577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
