INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207493235', 'Calça Infantil Menino Moletom Jeans Colorittá Azul', 'Peça-chave no guarda-roupa dos meninos, a Calça Colorittá é a combinação perfeita entre conforto e atitude. Feita em moletom jeans, ela possui elástico no cós, proporcionando liberdade de movimentos, e bolsos funcionais, que dão praticidade para o dia a dia. Além disso, sua lavanderia estonada traz um toque de modernidade, sendo perfeita para usar com camisetas, jaquetas e blusões. Ideal para passeios, encontros em família ou eventos, invista nessa peça essencial que une praticidade e estilo!Detalhes da peça: • Feita em moletom jeans • Elástico no cós • Possui bolsos • Com lavanderia estonada • Ideal para passeios, encontros em família ou eventos', 149.9, 104.93, NULL, 'Baby & Kids Fashion > Boy Clothes > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mr1try9ixt6sc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58207493235', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697725357', 'Chave Fixa 8 x 9mm Espelhada SATA ST41301SC', 'Chave Fixa 8 x 9mm Espelhada SATA ST41301SC Imagine uma ferramenta que une força, durabilidade e praticidade. Apresentamos a Chave Fixa Espelhada SATA, meticulosamente forjada em aço com um acabamento cromado polido em peça única. Essa combinação oferece não apenas robustez máxima, mas também uma resistência excepcional à corrosão. Fabricada com aço Cromo Vanádio, essa chave não é apenas uma ferramenta; é um investimento em durabilidade. Seu acabamento cromado não apenas proporciona um visual polido, mas também confere segurança adicional, já que não descasca com o tempo. Além disso, a facilidade de limpeza é notável. Com uma superfície polida, manter sua ferramenta em condições impecáveis nunca foi tão simples. E graças à inovadora tecnologia SURFACE DRIVE, preocupações com o espaneamento da cabeça do parafuso tornam-se coisa do passado. Para projetos domésticos ou desafios profissionais, a Chave Fixa Espelhada SATA é a escolha que você pode confiar. Experimente a diferença de possuir uma ferramenta que não apenas atende, mas supera as suas expectativas. Garanta já a sua e descubra o padrão de excelência em ferramentas! Características -Forjado em aço com acabamento cromado e polido em peça única para máxima robustez e resistência à corrosão. -Muito mais segura pois a camada de cromo não descasca e prática por ser mais fácil de limpar. -Fabricado em Aço Cromo Vanádio para maior resistência e durabilidade. -Tecnologia Surface Drive, evita que a cabeça do parafuso espane -Atende a Norma ASME B107.17 - Atende a Norma ASME B107.6 CódigoModelo:ST41301SC Marca: SATA Especificações Técnicas Comprimento: 149,4mm Largura: 1cm Altura: 0,40cm Tamanho: 8x 9mm Especificação ASME: ASME B107.17 Especificações DIN: DIN 3110 Unidade de Medida: Métrica Material: Aço Cromo-Vanádio (Cr-V) Peso: 30 gramas Garantia Vitalícia conforme normas do fabricante Imagens meramente ilustrativas. Todas as informações divulgadas são de responsabilidade do fabricantefornecedor. Os preços anunciados neste site podem sofrer alterações sem avisos prévios.', 19.44, 16.14, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gw-mfisb7n2p156d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F22697725357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
