INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793487482', 'Lona De Polietileno Azul 10 M X 8 M Vonder', 'Lona de polietileno azul 10 m x 8 m, VONDER Possui cantos reforçados e fio sintético ao redor da bainha para maior resistência. Fabricada em polietileno de alta e baixa densidade, com aditivo que protege contra os raios ultravioleta. Impermeável. Possui amostra do produto fora da embalagem. Indicada para indústria, agricultura, construção civil, náutica, camping, pesca, recreação, utilidades domésticas, entre outros. Não utilizar a lona diretamente sobre superfícies aquecidas ou expostas ao sol (exemplos: veículos, peças metálicas, máquinas e equipamentos), pois a ação do calor poderá provocar manchas e danos às superfícies. Não utilizar para cobertura de cargas transportadas em caminhões, caminhonetes e automóveis. Não utilizar em contato com produtos químicos e resinas e para cobertura de peças perfurantes/cortantes. O esforço excessivo e a ação de ventos fortes podem provocar o rompimento dos ilhoses, bem como da lona. Realize a amarração da lona com cordas elásticas, dando uma maior flexibilidade ao produto. Conservação: armazenar longe de fontes de calor. Caso necessário, lavar com água e sabão neutro. Não recomendado para utilização como cobertura definitiva em telhados. Especificações Técnicas: Medida da lona: 10 m x 8 m Cor da lona: Azul Espessura aproximada da lona de polietileno: 150 micra Distância entre ilhoses da lona: A cada 1 metro Massa aproximada (peso) (kg): 7,68 kg Conteúdo Da Embalagem: 1 Lona de polietileno.', 449.61, 339.22, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m30thqs8qy2tf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23793487482', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
