INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40779243008', 'Jogo Ferramentas 1/4pol Maleta Plástica 56 Peças SPARTA', 'Jogo de ferramentas completo e compacto, ideal para tarefas gerais de manutenção e reparos domésticos ou em oficina. Conjunto organizado em maleta plástica para transporte e armazenamento prático, com encaixe de 1/4 polegada adequado para peças pequenas e trabalhos de precisão. Compõe um kit de 56 peças que reúne soquetes, extensoras e acessórios essenciais, oferecendo praticidade e fácil acesso às ferramentas quando necessário. Marca SPARTA, concebido para quem busca um conjunto versátil e pronto para uso imediato. Características: Modelo: 135257 Referência: 135257 Tipo: Jogo de ferramentas Encaixe: 1/4pol. Peças: 56 Maleta: Plástica Marca: SPARTA EAN: 7899612748300 Benefícios: Organização e fácil transporte das ferramentas graças à maleta plástica. Versatilidade para diferentes reparos com 56 peças essenciais. Economia ao reunir ferramentas básicas em um único kit. Acessos rápidos e práticos aos soquetes e acessórios durante o trabalho. Ideal para uso doméstico e em oficinas por sua praticidade. Conteúdo da embalagem: Jogo de ferramentas com 56 peças em maleta plástica.', 222.36, 154.25, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mls9yva3ppfoec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F40779243008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48605611591', 'Ferro de Passar Roupa 110V 220V Ultra Potente Compacto Rápido ON-PR905', 'O ferro de passar foi desenvolvido para oferecer alto desempenho, praticidade e eficiência no cuidado diário com roupas. Possui aquecimento rápido e excelente condutividade térmica, permitindo atingir altas temperaturas para facilitar a remoção de vincos com maior rapidez. A edição a ultra potente proporciona resultados mais eficientes, garantindo tecidos bem alinhados e com melhor acabamento. Seu design compacto e ergonômico oferece conforto durante o uso, além de uma base que desliza suavemente sobre os tecidos. É indicado para diversos tipos de materiais, sendo ideal para uso doméstico no dia a dia. ESPECIFICAÇÕES GERAIS: - Tipo: Ferro de passar - Aquecimento: Alta temperatura - Condutividade térmica: Rápida - Função: Remoção de vincos - Uso: Doméstico - Base com bom deslizamento TECIDOS COMPATÍVEIS: - Tule - Seda - Fibra - Nylon - Poliéster - Lã sintética - Lã natural - Algodão - Linho DIMENSÕES: - Dimensões da base: 20,1 x 10,2 cm - Dimensões do produto: 24,3 x 10,3 x 11 cm DIFERENÇAS POR VOLTAGEM: - Versão 220V: - Potência: 1400 W - Versão 110V: - Potência: 1200 W CONTEÚDO: - 01 Ferro de passar - 01 Manual de instruções', 91.9, 63.21, NULL, 'Home Appliances > Small Household Appliances > Irons & Steamers', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mk2o8plemrr74e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F48605611591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26686213253', 'Hub USB 3.0 4 Portas Hot Swap USB-B Knup KP-HB517', 'Hub USB 3.0 4 Portas Knup KP-HB517 oferece conectividade avançada e praticidade para quem precisa expandir as opções de conexão do seu computador ou notebook. Com potência de 7,5W e entrada via interface Micro USB-B, garante performance estável e segura. Equipado com quatro portas USB 3.0 de alta velocidade, permite transferências rápidas de dados, ideal para periféricos como mouses, teclados, pen drives e HDs externos. Sua alimentação é feita via porta USB 5V/1\~1,5A, dispensando fontes externas. Compatível com Windows 7 ou superior, Chrome OS, Mac e Linux, ainda conta com a funcionalidade hot swap, permitindo conectar e desconectar dispositivos sem a necessidade de reiniciar o sistema. Compacto e funcional, é uma solução eficiente para o dia a dia. ESPECIFICAÇÕES: - Modelo: KP-HB517 - Potência: 7,5W - Interface de entrada: Micro USB-B - Interface de saída: 4 portas USB 3.0 - Alimentação: 5V/1\~1,5A - Compatibilidade: Windows 7 ou superior, Chrome OS, Mac, Linux CONTEÚDO: 1 Hub USB 3.0', 52.31, 37.66, NULL, 'Computers & Accessories > Peripherals & Accessories > USB Hubs & Card Readers', 'https://cf.shopee.com.br/file/sg-11134201-7rfg5-m9fvmes4xyuf15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F26686213253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
