INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202787221', 'Pneu Aro 18 Westlake 225/40 R18 92W ZuperEco Z-108', 'Pneu Aro 18 Westlake 225/40 R18 92W ZuperEco Z-108 Sobre a marca: A Westlake é uma marca de pneus fundada em 1958, parte do Zhongce Rubber Group, um dos maiores fabricantes de pneus do mundo. A empresa se destaca como a maior fabricante de pneus da China e ocupa a 8ª posição entre os maiores fabricantes globais, com presença em mais de 120 países. A Westlake oferece uma ampla gama de pneus para diversos tipos de veículos, incluindo carros de passeio, caminhões e máquinas agrícolas, buscando sempre oferecer produtos de alta qualidade, segurança e bom custo-benefício Informações Adicionais: - Marca: Westlake - Modelo: ZuperEco Z-108 - Medida: 225/40 R18 - Largura: 225mm - Perfil: 40% - Aro: 18 - Índice de carga: 92 - 630 kg - Índice de velocidade: W - 270 km/h - Tipo de construção: Radial - Tipo de terreno: HT - Runflat: Não - Extra Load: Não - Sidewall: Letras Pretas - Garantia: 5 anos contra defeitos de Fábrica Aplicações: - FERRARI: F355 - VOLKSWAGEN: GOLF - VOLVO: V40 - HONDA: CR-V - AUDI: A3, A3 II, A3 SEDAN, S3 OBSERVAÇÕES: IMAGEM MERAMENTE ILUSTRATIVA VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 499.5, 499.5, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mj61ajhrd9fl45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F58202787221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
