INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597744830', 'Kit 5 Shampoo Automotivo Det mol Limpeza Pesada Sandet 1L', 'Kit 5 Shampoo Automotivo Det mol Limpeza Pesada Sandet 1L O Shampoo Automotivo Detmol Limpeza Pesada Sandet é o produto ideal para quem busca limpeza e cuidado para seu veículo. Com sua fórmula concentrada, este shampoo oferece uma limpeza profunda, removendo toda sujeira e a graxa sem danificar a pintura. Informações Adicionais: - Det Mol é um detergente com alto poder de limpeza, é utilizado na lavagem de carrocerias e chassis de veículos pesados de passeio e motor. Eficaz na remoção de sujeiras como: graxa, gordura, limpeza de pisos, paredes, maquinas e superfícies pintadas. - Produto biodegradável, com concentração ideal em tensoativos e sequestrantes que asseguram uma lavagem perfeita. - Não ataca a pintura; Limpeza pesada. Modo de uso: - Para limpeza leve: Diluir 1 parte de produto em até 100 litros de água - Para limpeza pesada: Diluir 1 parte de produto para 10 litros de água. QUALQUER DÚVIDA ESTAMOS Á DISPOSIÇÃO.', 194.44, 194.44, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdvt-lzrnrbvzhu7cb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F23597744830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393928641', 'Ração Vet Life para Gatos Adultos Urinary Struvite 400gr', 'Ração Vet Life para Gatos Adultos Urinary Struvite 400gr Pet: Gatos Idade: Adultos Porte de Raça: Todas Condição: Gatos com problemas urinários por conta de cálculos Tamanho de grão: Específico para todas as raças A Ração VetLife Urinary Struvite para gatos adultos é um alimento Super Premium desenvolvido para gatos com formações de cálculos urinários extrusivos. A Ração Vetlife garante em sua fórmula uma baixa quantidade de fósforo e magnésio não contribuindo com a formação e aumento de cálculos, uma ótima quantidade de complexos antioxidantes para auxiliar na longevidade do organismo, além de seus compostos que auxiliam no controle do Ph urinário. Por que a Ração VetLife Urinary Struvite para gatos adultos é um alimento Super Premium? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendem os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração VetLife Urinary Struvite para gatos adultos foi produzida atendendo todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Composição da Ração VetLife Urinary Struvite para gatos adultos Farinha de vísceras de aves, glúten de trigo, quirera de arroz, farinha de peixe, gordura de frango, óleo de peixe refinado, ovo em pó, farinha de torresmo (proteína isolada de suíno), celulose, levedura seca de cervejaria, DL-metionina, L-carnitina, L-lisina, taurina, parede celular de levedura (mannan-oligossacarídeos), fruto-oligossacarídeos, beta caroteno, extrato de Marigold (luteína), hidrolisado de fígado suíno, vitaminas (A, D3, E, K3, B1, B2, B6, B12, C, H, PP, ácido pantotênico, ácido fólico, cloreto de colina), cloreto de sódio, cloreto de potássio, carbonato de cálcio, transquelato de ferro, transquelato de cobre, transquelato de zinco, transquelato de manganês, transquelato de selênio, iodato de cálcio, sulfato de cálcio, propionato de cálcio, concentrado de tocoferóis.', 57.88, 57.88, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-7repq-m8zk6mz2aill30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F23393928641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693913991', 'Ração N&D Ancestral Grain para cachorros adultos mini breeds frango e romã 2,5kg', 'Ração N&D Ancestral Grain para cachorros adultos mini breeds frango e romã 2,5kg Pet: Cachorros Idade: Adultos Porte de Raça: Porte Pequeno e mini Tamanho de grão: Específico para raças adultas de porte pequeno e mini A Ração N&D Ancestral Grain para cachorros adultos mini breeds frango e romã é um alimento Super Premium desenvolvido para cachorros com alta palatabilidade e sem conservantes artificiais. A Ração N&D garante em sua fórmula um alimento completo e balanceado sem conservantes artificiais, produzido em ambiente controlado e selado a vácuo, garantindo a integridade e qualidade do alimento sem contaminação externa, além de possuir baixa índice glicêmico em sua fórmula. Por que a Ração N&D Ancestral Grain para cachorros adultos mini breeds frango e romã é um alimento Super Premium? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendem os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração N&D Ancestral Grain para cachorros adultos mini breeds frango e romã foi produzida atendem todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Certificação Cruelity Free As rações N&D tem certificação de não crueldade com animais nos testes de suas rações, gerando melhores condições durantes os testes de seus produtos. Composição da Ração N&D Ancestral Grain para cachorros adultos mini breeds frango e romã Carne 