INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793225142', 'MÓDULO PARA REBOQUES E CARRETINHAS 4 SAÍDAS SINALEIRA FREIO E SETAS INTERFACE MR200 4S', 'Módulo Interface para Reboques 4 saídas FKS MR200 4S 12v O Módulo para Reboque FKS MR200 foi desenvolvido visando evitar avisos por acessórios como reboques ou iluminações de Leds em seu painel além de proteger a fiação original e a central eletrônica do veículo. Este produto atua como módulo de interface que recebe sinais elétricos do carro e os passam para a saída do reboque já filtrada e sem oscilações de tensões. Com toda a tecnologia implantada, permite remover os erros e conflitos na central veicular e permite ligar todas as iluminações do reboque como Setas, Freios e Sinaleiras. Aplicações: Veículos com iluminação LED e Halógena. Veículos que apontam avarias no painel quando ligado a reboques. Veículos com fiação de baixa potência (Evita riscos de curtos). Proteção contra ligações de conectores fora do padrão. Proteção da fiação original e da central do veículo. Saída para 4 sinais. (Sinaleira, freios e setas direita e esquerda) DADOS TÉCNICOS: Tensão nominal - 12V Corrente nominal - 10mA Consumo - 15mA Itens Inclusos: 01 Módulo MR 200 4S 01 Chicote de instalação 01 Manual * Aplicação Universal 12V NTV324', 103.9, 103.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdx3-lyxxd6x927u4d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F278256920%2F22793225142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
