INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43373050602', 'Filtro Ar condicionado Polo Fox Voyage Gol G5 G6 G7 BOSCH + Limpa Ar Orbi Envio Rapido', '🧊 Filtro de Ar Condicionado Polo Fox Voyage Gol G5 G6 G7 BOSCH + Limpa Ar Orbi – Envio Rápido Descrição do Produto: Mantenha o ar do seu veículo sempre puro e livre de impurezas com o Filtro de Ar Condicionado BOSCH, desenvolvido para proporcionar máxima filtragem e proteção ao sistema de ventilação. Acompanha o Limpa Ar Condicionado Orbi, ideal para eliminar fungos, bactérias e odores desagradáveis do sistema interno, garantindo um ambiente mais saudável e agradável dentro do carro. Compatibilidade: ✔ Volkswagen Polo ✔ Fox ✔ Voyage ✔ Gol G5, G6 e G7 (Verifique o ano e versão do veículo antes da compra.) Conteúdo do Kit: 1 Filtro de Ar Condicionado BOSCH 1 Spray Limpa Ar Orbi (Aromatiza e higieniza) Benefícios: ✅ Ar mais limpo e saudável para motorista e passageiros ✅ Protege o sistema de ventilação e o evaporador do ar-condicionado ✅ Elimina odores e microrganismos causadores de alergias ✅ Instalação fácil e rápida ✅ Produto Original BOSCH com qualidade garantida ✅ Envio rápido e seguro 🚚💨 Dica: Substitua o filtro de cabine a cada 10.000 km ou a cada 6 meses, conforme o uso do veículo.', 39.9, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-824ic-mfixy27d80zzab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357432948%2F43373050602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
