INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253777640', 'Conversor Adaptador De Fios Para Rca Corzus Cvr 4.0 Rmt', 'Conversor Adaptador De Fios Para Rca Corzus Cvr 4.0 Rmt Informações Técnicas: O Conversor RCA é indicado para CDs ou toca-fitas originais de veículos, nacionais ou importados, que não possuem saída de alta impedância (RCA). O aparelho funciona como conversor de baixa impedância (fio) para alta impedância (RCA) e filtro anti-ruído, além de possuir o fio para o acionamento remoto do aparelho, e é feito pela detecção do som. O CVR4.0RMT necessita ser alimentado a 12Volts. • Indicado para CD ou Toca-fitas originais de Veículos Nacionais ou Importados, que não possuem saídas RCA; • Transforma o sinal de baixa impedância para alta impedância (RCA); • Alimentação 12Volts; • Corrente do fio Remoto 100mA; • Filtro anti-ruído; • Anti-looping; • Peso: 0,2 kg; Conteúdo da embalagem: • 01 Conversor Adaptador De Fios Para Rca Corzus Cvr 4.0 Rmt Garantia do vendedor: 90 dias', 94.99, 90.24, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjrh163f9vr5e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1464816013%2F58253777640', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
