INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997168256', 'AHC Masters Air Rich Sun Stick SPF 50+ Pa ++++ / 22g, 14g', 'Bastão de sol rico em mestres de mestres de mestres de sol rico em ar FPS50+ PA+++ (Cosméticos Que bloqueiam os raios UV) Pak Se Participado em Produção Protetor solar duradouro e resistente à água Bastão de sol macio com efeito de sebo com efeito de controle de sol macio com sebo Formado o efeito de proteção UV por uma fina película protetora que não é facilmente apagada pela água e suor é formada para manter o efeito de proteção UV por um longo tempo mesmo durante atividades ao ar livre longas. Efeito hidratante que dura 24 horas Aplicando a tecnologia hidratante de umidade e formando uma película hidratante por aplicação da umidade que proporciona umidade à pele e forma uma película hidratante, ajuda a melhorar a umidade até o 10o andar da pele (dermatismo) e hidrata a pele 24 horas por dia e Mantenha-o. Textura de ar levemente aderente para um acabamento fosco O pó de calamina auxilia no controle do sebo e na textura do ar leve-aderente proporciona um acabamento liso sem viscosidade e brilho. Batom de água de longo prazo: Funcionalidade de proteção UV [SPF50+/PA++/Resistência à água de longo prazo] Proteção de longa duração com efeitos à prova d''água Efeitos-chave: Proteção de longa duração com fortes efeitos à prova d''água Ingredientes principais do extrato de garrafa STECA, calamina, tocofenol País de fabricação: FEITO NA COREIA', 76.98, 76.98, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134207-7rdyb-lxtdvoznduvzfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F21997168256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
