INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18099712399', 'PINO DA ALAVANCA CARABINA PRESSÃO ROSSI SPORT / UP', 'Produto de uso exclusivo em práticas esportivas. Sabendo o quanto as peças de reposição são itens importantes para quem compra qualquer tipo de equipamento, nós da AR15 SPORT disponibilizamos uma incrível variedade dessas peças em todo segmento de Tiro Esportivo. Essa em específico é uma peça original ROSSI e se trata do PINO DA ALAVANCA DE ARMAR compatível especificamente com a CARABINA DE PRESSÃO ROSSI SPORT e SPORT UP. ESPECIFICAÇÕES TÉCNICAS: - Marca: Rossi - Material: Metal - Número 20 na vista explodida - Compatibilidade: Sport e Sport Up - Dimensões: 4,9mm x 15,7mm - Peso: 1 grama ITENS INCLUSOS: - 01 Pino da Alavanca Carabina Rossi Sport e Sport Up Observação: Garantia de 03 meses mediante defeitos de fábrica. INFORMAÇÃO: Os equipamentos, peças e acessórios aqui listados são de uso exclusivo em armas de pressão (gás comprimido ou mola), airsoft, paintball, esferas plásticas (BBS) e estão em conformidade com a legislação brasileira de USO PERMITIDO "É permitido o uso de armas de pressão por ação de gás comprimido ou por ação de mola, com calibre igual ou inferior a seis milímetros (6mm ou 6.0mm), e das que lançam esferas de plástico com tinta, como os lançadores de paintball." Conforme parágrafo único do Art. 11 do DECRETO Nº 11.615, DE 21 DE JULHO DE 2023. A venda desses itens é feita somente para maiores de 18 anos mediante a comprovação de maior idade. Atenção: O envio de Armas de pressão e Airsoft é realizado somente por transportadora. Caso tenham dúvidas entrar em contato.', 17.31, 17.31, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rent-m82gub2bymxuab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404617501%2F18099712399', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47511323992', 'Amor & Gelato – Edição de luxo de Colecionador por Jenna Evans Welch, Intrínseca', 'Edição de luxo do best-seller Amor gelato, que já vendeu mais de meio milhão de exemplares no Brasil, em capa dura, com impressão trilateral, fitilho e conteúdo extra Publicado nos Estados Unidos em 2016, Amor gelato encantou os leitores ao redor do mundo e é sucesso no Brasil desde 2017, onde já atingiu a marca de mais de meio milhão de exemplares vendidos. Para comemorar uma década da aventura de Lina na Itália, a Intrínseca lança uma edição de luxo inédita, em capa dura com bordas arredondadas, guardas coloridas, fitilho, impressão trilateral e conteúdo extra. Lina vai passar o verão em Florença, mas não está nem um pouco interessada em apreciar a famosa paisagem florida e ensolarada. O único motivo da viagem é atender ao último pedido da mãe. Ela queria que Lina finalmente conhecesse o pai. Mas que tipo de pai não dá as caras por dezesseis anos? Pouco importa. Lina só quer voltar logo para casa. Tudo muda quando ela recebe um diário que a mãe escreveu na época em que estudou na Itália. De uma hora para outra, Lina se vê mergulhada naquelas páginas, completamente envolvida por uma misteriosa história de amor marcada por uma decisão difícil. As descobertas vão inspirá-la a seguir os passos da mãe, ao lado do charmoso e simpático Ren, seu novo amigo italiano, pelos mais lindos pontos turísticos da Toscana — um caminho que a levará ao segredo capaz de mudar tudo o que ela achava saber sobre sua família e sobre si mesma.', 99.9, 79.92, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/br-11134275-820l7-mo4g14uw1n9gaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F47511323992', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094060452', 'Giorno Cucina Sentire Bene Master Chef - Home Spray 250ml', 'Giorno Cucina Sentire Bene Master Chef - Home Spray 250ml Neutralizador de odores, possui tecnologia NeoFresh. Elimina a percepção de mal cheiro causada por ingredientes como: alho, cebola e fritura. Conselho de Aplicação Aplique o aromatizador borrifando para o alto. Cuidado com os olhos na aplicação.', 79.85, 44.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-7raso-ma2whzafgj15d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22094060452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256146369', 'Polo Logo Calvin Klein Jeans - Vermelho', 'A polo masculina manga curta Calvin Klein Jeans confeccionada em tecido 100% algodão, possui o logo ckj. Opção básica e essencial do guarda roupa masculino, pode ser usada em diferentes combinações. Ideal para compor produções versáteis, do casual ao sofisticado.', 279.0, 199.0, NULL, 'Men Clothes > Tops > Polo Shirts', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mr27sex588w489', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593932205%2F58256146369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594040708', 'Giorno Casa Flor de Laranjeira - Difusor de Ambiente 250ml', 'Giorno Casa Flor de Laranjeira - Difusor de Ambiente 250ml O Difusor Flor de Laranjeira conta com um aroma fresco e vibrante que evoca a sensação de um dia ensolarado no campo, trazendo alegria e energia ao ambiente. O difusor de ambiente é o símbolo perfeito de elegância e funcionalidade para a sua casa, transformando seu lar em um refúgio acolhedor e encantador. Com tecnologia refinada, ele espalha delicadamente a fragrância escolhida, criando uma sinfonia olfativa que embala os sentidos e acalma a mente. Além de funcional, é também uma peça de decoração que complementa a estética de qualquer ambiente. As notas olfativas desta versão são: Saída: Limão, Bergamota, Laranja, Gálbano, Bouquet Verde. Corpo: Alecrim, Cardamomo, Cominho, Rosas, Basilicão. Fundo: Cedro Texas, Musgo Carvalho, Âmbar. Conselho de aplicação Basta colocar as varetas difusoras no líquido perfumado e deixar que a fragrância se espalhe pelo ambiente.', 113.15, 68.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-7rasx-ma369q5gxijw6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23594040708', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094484489', 'Bolsa Feminina Chenson Microfiber Casual Mão 3185115', 'Bolsa Feminina Chenson Microfiber Casual de Mão e Transversal 3185115 Bolsa Feminina Chenson em microfibra de alta qualidade, ideal para o dia a dia com estilo e praticidade. Conta com 1 bolso externo com aba, compartimento principal com zíper, 1 bolso interno com zíper e 1 aberto. Versátil, com alça de mão dupla e alça transversal ajustável/removível. Perfeita para organizar itens essenciais com elegância. Medidas aproximadas : ( A ) 23cm x (L) 14cm (P) 25cm Cuidados: Guarde em um local seco e arejado, evitando locais úmidos. Evite colocar excesso de peso no produto para não forçar as costuras e os fechos. Proteja os objetos cortantes e/ou pontiagudos, evitando o contato direto com o produto. Evitar altas temperaturas. Cores claras poderão manchar quando em contato com outros objetos ou roupas de cores pigmentadas. Dicas de Limpeza: Para a limpeza, utilize apenas pano úmido com sabão neutro. Não mergulhar na água e não utilizar componentes químicos, solventes ou alvejantes. Não deixar de molho e secar à sombra.', 204.9, 204.9, NULL, 'Women Bags > Top-handle Bags', 'https://cf.shopee.com.br/file/sg-11134201-824jh-mfbli8m7esr2c6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1473888823%2F22094484489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793587465', 'Jogo Pastilha Freio Traseiro Tucson 04/ Santa Fé 01/ 2.0/2.7 - 382 - SYL2276', 'Jogo Pastilha Freio Traseiro Tucson 04/ Santa Fé 01/ 2.0/2.7 TUCSON 2.0 16V / 2.7 24V 04/12 - SANTA FÉ 2.0 CRDi / 2.7 V6 4X4 01/06 - EIXO TRASEIRO - SEM ALARME (SISTEMA MANDO) As pastilhas de freio são essenciais para a frenagem do automóvel, pois, são responsáveis por 70% desse trabalho. Elas fazem as rodas pararem, ao entrarem em contato com o disco de freio. É bom verificar a espessura das pastilhas a cada 5 mil quilômetros, mas recomenda-se determinar a periodicidade de troca adequada manual do veículo. Importante lembrar a substituição delas pode variar de acordo com o uso do veículo. A vida útil das pastilhas é de 25 a 35 mil quilômetros rodados, em média.', 96.0, 96.0, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-ln0r9rspr9u3ad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23793587465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897025494', 'Filtro Óleo Audi A3 1996 a 2006 - 166488 - WUNI0002', 'Filtro Óleo Audi A3 1996 a 2006 166488 WUNI0002 1.8 20V Turbo - Gasolina - Automático / Mecânico / Tiptronic - (Blindado) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 23.98, 23.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rfhx-m959yrrjq3h188', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23897025494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893404708', 'Chaveiro Venum Whey Mochila e Bolsas', 'Chaveiro Venum Whey - Ótimo para a sua mochila e estilo do treino 2 opções de cores: Branco e Preto - Venum Para sua mochila, bolsa e chaveiro com sensação de crescimento e cada vez mais bonito!', 39.9, 39.9, NULL, 'Hobbies & Collections > Souvenirs > Keychains', 'https://cf.shopee.com.br/file/sg-11134201-7rfib-m94w5ij00n3bbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1054067345%2F23893404708', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42703497316', 'FIltro Ar Condicionado PRISMA 2006/2012 - 37286 - AKX3536', 'FIltro Ar Condicionado PRISMA 2006/2012 (Sedã / Joy / Maxx) - Motor 1.0 8v Flex Power/ 1.4 8v Econo Flex - (Mecânico) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 27.63, 27.63, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rauu-maow5gms031eb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F42703497316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992528798', 'Válvula Termostática Gm Celta 2001 a 2015 - 840733 - AVTS03006T92', 'Válvula Termostática Gm Celta 2001 a 2015 840733 AVTS03006T92 1.0/1.4 8v - Kit = Carcaça + Válvula A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 48.5, 48.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rblc-lmqn8eko0bq156', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23992528798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6863448544', 'DUQUE E EU, O - VOL 1 - ARQUEIRO', 'Simon Basset, o irresistível duque de Hastings, acaba de retornar a Londres depois de seis anos viajando pelo mundo. Rico, bonito e solteiro, ele é um prato cheio para as mães da alta sociedade, que só pensam em arrumar um bom partido para suas filhas. Simon, porém, tem o firme propósito de nunca se casar. Assim, para se livrar das garras dessas mulheres, precisa de um plano infalível. É quando entra em cena Daphne Bridgerton, a irmã mais nova de seu melhor amigo. Apesar de espirituosa e dona de uma personalidade marcante, todos os homens que se interessam por ela são velhos demais, pouco inteligentes ou destituídos de qualquer tipo de charme. E os que têm potencial para ser bons maridos só a veem como uma boa amiga. A ideia de Simon é fingir que a corteja. Dessa forma, de uma tacada só, ele conseguirá afastar as jovens obcecadas por um marido e atrairá vários pretendentes para Daphne. Afinal, se um duque está interessado nela, a jovem deve ter mais atrativos do que aparenta. Mas, à medida que a farsa dos dois se desenrola, o sorriso malicioso e os olhos cheios de desejo de Simon tornam cada vez mais difícil para Daphne lembrar que tudo não passa de fingimento. Agora ela precisa fazer o impossível para não se apaixonar por esse conquistador inveterado que tem aversão a tudo o que ela mais quer na vida. Primeiro dos oito livros da série Os Bridgertons, O duque e eu é uma bela história sobre o poder do amor, contada com o senso de humor afiado e a sensibilidade que são marcas registradas de Julia Quinn, autora com 10 milhões de exemplares vendidos.', 58.4, 58.4, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-8225g-mhtiy7fvthc586', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F6863448544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497473796', 'Agulha Carburador Vw Kombi 1974 a 1986 - 104593 - 15121', 'Agulha Carburador Vw Kombi 1974 a 1986 104593 15121 CARBURADOR SOLEX DUPLO 32 PDSIT', 27.41, 27.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd4w-lugmyfxdwnose5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23497473796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699663744', 'Pré Filtro Combustível Vw Pointer 1994 a 1996 - 1354986 - T040217', 'Pré Filtro Combustível Vw Pointer 1994 a 1996 1354986 T040217 Gasolina - Sistema MarwallO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 33.87, 33.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6q-m7bn201dc7u116', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20699663744', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492574812', 'A hipótese do amor (Sucesso do TikTok)', 'Quando um namoro de mentira entre cientistas encontra a irresistível força da atração, todas as teorias cuidadosamente calculadas sobre o amor são postas à prova.Com personagens cativantes e diálogos afiados, este livro engraçado, sexy e inteligente se tornou uma das grandes sensações do TikTok.Olive Smith, aluna do doutorado em Biologia da Universidade Stanford, acredita na ciência – não em algo incontrolável como o amor.Depois de sair algumas vezes com Jeremy, ela percebe que sua melhor amiga gosta dele e decide juntá-los. Para mostrar que está feliz com essa escolha, Olive precisa ser convincente: Afinal, cientistas exigem provas.Sem muitas opções, ela resolve inventar um namoro de mentira e, num momento de pânico, beija o primeiro homem que vê pela frente.O problema é que esse homem é Adam Carlsen, um jovem professor de prestígio – conhecido por levar os alunos às lágrimas. Por isso, Olive fica chocada quando o tirano dos laboratórios concorda em levar adiante a farsa e fingir ser seu namorado.De repente, seu pequeno experimento parece perigosamente próximo da combustão e aquela pequena possibilidade científica, que era apenas uma hipótese sobre o amor, transforma-se em algo totalmente inesperado.', 58.9, 58.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rblm-ln4kmxlmjvuf28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22492574812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398049288', 'Kit Ed e Lorraine Warren: Demonologistas, Lugar Sombrio e Vidas Eternas', '"Eles enfrentaram os mistérios mais sinistros dos últimos sessenta anos, sempre em busca da verdade. Agora é a sua vez de entrar em contato com o sobrenatural. Você tem coragem? Então leia ED & LORRAINE WARREN: DEMONOLOGISTAS, a biografia definitiva dos mais famosos investigadores paranormais do nosso plano astral.Não é de hoje que os fãs do terror conhecem Ed Warren e sua esposa, Lorraine. O casal foi retratado em filmes de grande sucesso, como Invocação do Mal, Annabelle e Horror em Amityville. Mas basta folhear as páginas de ED & LORRAINE WARREN: DEMONOLOGISTAS para constatar que, muitas vezes, a vida pode ser bem mais assustadora que o cinema. Principalmente para aqueles que não têm a pretensão de negar fenômenos que nem mesmo a ciência é capaz de explicar.Em ED & LORRAINE WARREN: DEMONOLOGISTAS, Gerald Brittle desvenda alguns dos principais casos reais vividos pelos Warren. Ed e Lorraine permitiram ao autor acesso exclusivo aos seus arquivos sobrenaturais, que incluem relatos extraordinários de poltergeists, casas mal-assombradas e possessões demoníacas. O resultado é um livro rico em detalhes como nenhum outro.Lançado originalmente em 1980, e até então inédito no Brasil, ED & LORRAINE WARREN: DEMONOLOGISTAS é, sem dúvida, o mais completo dossiê sobre os exorcistas/caçadores de fantasmas mais famosos do mundo. Virou o livro de cabeceira do diretor James Wan (Jogos Mortais, Invocação do Mal 1 e 2, Annabelle), além de servir de fonte de inspiração para Vera Farmiga, que interpreta a Sra. Warren no cinema.Nas páginas do livro, o leitor acaba se tornando um pouco mais íntimo de Lorraine Rita e Edward Warren Miney. Duas almas gêmeas que se completavam ao dividir, entre tantas coisas, a mesma vocação: Oferecer ajuda espiritual aos possuídos e atormentados.OS WARREN APOSTARAM NO ESCURODesde 2006, Ed Warren não se encontra mais neste plano físico. Contudo, é fácil imaginar que Lorraine permaneça conectada a ele até os dias de hoje. Talvez até de sua mediunidade, mas certamente pela paixão de uma vida inteira juntos.Como responsável em manter o legado que ela e Ed construíram, Lorraine não poderia estar mais satisfeita com o lançamento de ED & LORRAINE WARREN: DEMONOLOGISTAS no Brasil. Só mesmo a DarkSide® Books para entregar uma edição à altura dos maiores investigadores paranormais de todos os tempos aos seus leitores possuídos, que chega para comemorar o aniversário da editora, em outubro de 2016. O casal de investigadores paranormais favorito dos darksiders - Ed & Lorraine Warren - está de volta. Depois do grande sucesso de Ed & Lorraine Warren: Demonologistas, a DarkSide® Books reabre seus Arquivos Sobrenaturais para desenterrar um dos casos mais assustadores dos últimos 30 anos.Descubra a verdadeira história por trás do exorcismo de Connecticut em ED & LORRAINE WARREN: LUGAR SOMBRIO.Mesmo quem tem medo do assunto certamente já ouviu falar deles. Seus casos mais famosos, como os de Amityville, Rhode Island e de Enfield, por exemplo, foram adaptados para o cinema. Até mesmo a endiabrada Annabelle está no currículo de assombrações, poltergeists e espíritos obsessores enfrentados pelo casal Warren. Claro, a boneca legítima faz parte da coleção que Lorraine, hoje com 90 anos, mantém em casa.ED & LORRAINE WARREN: LUGAR SOMBRIO, é o relato meticuloso dos fenômenos que infernizaram a vida de um casal norte-americano após sua mudança para uma antiga casa em que havia funcionado uma funerária anos antes.Um a um, os membros da família passam a ser atacados por uma presença sinistra, em acontecimentos cada vez mais extremos: De vozes na escuridão até violações fantasmas. É Nesse ambiente de desespero que Ed & Lorraine Warren são recebidos, prontos para mais um combate direto com o mundo das sombras.O exorcismo de Connecticut ganhou notoriedade na mídia norte-americana na época. Em 2009, a história serviu de inspiração para o filme Evocando Espíritos, de Peter Cornwell, que usou Ed & Lorraine Warren: Lugar Sombrio como principal fonte de pesquisa.Nos fóruns da internet, os fãs e a mídia especializada apostam que James Wan (Annabelle, Jogos Mortais) também vai contar sua visão dessa mesma história em breve, no aguardado Invocação do Mal 3. Wan é um admirador dos Warren, e seus filmes sempre contam com a colaboração de Lorraine. Quem sabe o próprio Edward não encontra um jeito de dar seus palpites lá do ouro lado?ED & LORRAINE WARREN: LUGAR SOMBRIO.', 215.98, 215.98, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rfh2-m32i6vu9xbu67d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23398049288', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18173561602', 'Pilha Alcalina AA Rayovac Bateria 2A Pequena kit 12 unidades', 'As pilhas alcalinas Rayovac AA duram até 20x mais que as pilhas comuns (zinco), são recomendadas para dispositivos de alto consumo de energia, como brinquedos, lanternas etc. Possuem 10 anos de validade: Garantimos que, se não utilizadas, as pilhas podem ser armazenadas por até 10 anos mantendo no mínimo, 60% da carga. Livres de mercúrio e cádmio.', 69.93, 55.19, NULL, 'Home Appliances > Batteries', 'https://cf.shopee.com.br/file/br-11134201-23020-5xdnjptbqnnv65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F751077961%2F18173561602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16169722741', 'LIVRO DE ATIVIDADES - FRACOES E DECIMAIS 17X23,5', 'Você quer ajudar seu pequeno em matemática? As atividades internas ajudarão os jovens aprendizes a criar confiança nos principais conceitos de numerais tais como frações, casas decimais e porcentagens. Trabalhando de forma divertida, as crianças dominarão novas habilidades, lidarão com diferentes tipos de problemas de números e construirão um aprendizado escolar.', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/4756866d1f584df9c743a80b5b13be0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F16169722741', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
