INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093999466', 'Kit 2 Pneus 235/55R18 104H Aplus Aro 18', 'DESCRIÇÃO DO PRODUTO Kit 2 Pneus 235/55R18 104W XL TL Aplus A610-7 desenvolvido para SUVs e crossovers que exigem desempenho, segurança e conforto no uso diário e rodoviário. Seu desenho de banda de rodagem garante excelente aderência em piso seco e molhado, proporcionando estabilidade e controle em diferentes condições de condução. Com tecnologia XL (Extra Load), possui estrutura reforçada que suporta maior carga, oferecendo mais resistência, durabilidade e performance consistente mesmo em velocidades mais altas. ESPECIFICAÇÕES TÉCNICAS - Marca: Aplus - Modelo: A610-7 - Medida: 235/55R18 - Largura: 235 mm - Perfil: 55 - Aro: 18 polegadas - Índice de carga: 104 (até 900 kg por pneu) - Índice de velocidade: W (até 270 km/h) - Construção: Radial - Tipo: Sem câmara (TL – Tubeless) - Tecnologia: XL (Extra Load) - Conteúdo: Kit com 2 pneus PRINCIPAIS BENEFÍCIOS - Alta estabilidade em curvas - Excelente aderência em piso seco e molhado - Segurança em frenagens - Condução confortável e silenciosa - Estrutura reforçada XL para maior resistência - Maior durabilidade - Desempenho esportivo com conforto COMPATIBILIDADE Compatível com veículos que utilizam a medida 235/55R18, como: - Jeep Compass - Jeep Cherokee - Honda CR-V - Toyota RAV4 - Hyundai Santa Fe - Hyundai Tucson - Mitsubishi Outlander - Chevrolet Equinox - Volkswagen Tiguan - Ford Edge - Kia Sportage - Volvo XC60 (Confirme sempre a medida no manual do veículo ou etiqueta da porta antes da compra.) INFORMAÇÕES IMPORTANTES - Produto novo - Produto com nota fiscal - Garantia contra defeitos de fabricação - Imagens meramente ilustrativas - Não acompanha rodas - Instalação deve ser feita por profissional especializado - Recomendado alinhamento e balanceamento após instalação A Confinit agradece sua preferência.', 1576.14, 1576.14, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfhw-m9q9as9trql83d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1311743114%2F22093999466', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
