INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206814544', 'Lenço Umedecido Intimus Defesa Natural 16 Unidades', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Kit com 2 pacotes deparados que contém 16 unidades cada, totalizando em um kit de 32 lenços. Os Lenços Umedecidos Íntimos Intimus Defesa Natural foram especialmente desenvolvidos para ajudar a preservar as defesas naturais por não interferirem no pH da zona íntima. C/fibras naturais, pH balanceado e dermatologicamente testado, os lenços podem ser usados a qualquer hora e em qualquer lugar, todos os dias. Este produto possui o sele de aprovação pela FLASOG - Federação Latinoamericana de Associações de Obstetrícia e Ginecologia. Importante ressaltar que os lenços umedecidos Íntimos Intimus Defesa Natural não contêm fragrância.', 20.98, 20.98, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-82632-mlqpmp10fv9f6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F58206814544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
